      message = errorMessages.join('\\n');\n      } else if (filename) {\n        message = Craft.t('app', 'Upload failed for “{filename}”.', {filename});\n      } else {\n        message = Craft.t('app', 'Upload failed.');\n      }\n    }\n\n    Craft.cp.displayError(message);\n    this.progressBar.hideProgressBar();\n    this.$container.removeClass('uploading');\n  },\n\n  /**\n   * We have to take into account files about to be added as well\n   */\n  canAddMoreFiles: function (slotsTaken) {\n    return (\n      !this.settings.limit ||\n      this.$elements.length + slotsTaken < this.settings.limit\n    );\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\nconst punycode = require('punycode/');\n\n/**\n * Link Input\n */\nCraft.LinkInput = Garnish.Base.extend(\n  {\n    /** @type Craft.LinkField */\n    field: null,\n\n    /** @type {jQuery} */\n    $container: null,\n    /** @type {jQuery} */\n    $field: null,\n    /** @type {jQuery|null} */\n    $chip: null,\n    /** @type {jQuery|null} */\n    $textInput: null,\n    /** @type {jQuery} */\n    $hiddenInput: null,\n    /** @type {Garnish.DisclosureMenu} */\n    menu: null,\n\n    init: function (container, settings) {\n      this.$container = $(container);\n      this.setSettings(settings, Craft.LinkInput.defaults);\n\n      this.$container.data('linkInput', this);\n      this.field = this.$container\n        .closest('[data-link-field]')\n        .parent()\n        .data('linkField');\n      this.$chip = this.$container.children('.chip');\n      this.$textInput = this.$container.children('.text');\n      this.$hiddenInput = this.$container.children('input[type=hidden]');\n\n      if (this.$chip.length) {\n        this.menu = this.$chip\n          .find('.action-btn')\n          .disclosureMenu()\n          .data('disclosureMenu');\n        this.initChip();\n      } else {\n        this.initTextInput();\n      }\n\n      this.addListener(this.$container, 'click', (ev) => {\n        if (\n          this.$chip?.length &&\n          !['A', 'BUTTON'].includes(ev.target.nodeName)\n        ) {\n          this.switchToTextInput();\n          this.$textInput.focus();\n        }\n      });\n    },\n\n    hasPrefix: function (value) {\n      value = value.toLowerCase();\n      for (const prefix of this.settings.prefixes) {\n        if (Craft.startsWith(value, prefix, true)) {\n          return true;\n        }\n      }\n      return false;\n    },\n\n    ensurePrefix: function (value) {\n      if (this.settings.prefixes.length && !this.hasPrefix(value)) {\n        return this.settings.prefixes[0] + value;\n      }\n      return value;\n    },\n\n    removePrefix: function (value) {\n      for (const prefix of this.settings.prefixes) {\n        value = Craft.removeLeft(value, prefix, true);\n      }\n      return value;\n    },\n\n    removeFirstPrefix: function (value) {\n      if (this.settings.prefixes.length) {\n        return Craft.removeLeft(value, this.settings.prefixes[0], true);\n      }\n      return value;\n    },\n\n    createChip: function (value) {\n      let label = this.removePrefix(value);\n      if (label.match(/^[^\\/]+\\/$/)) {\n        label = Craft.removeRight(label, '/');\n      }\n      const menuId = `menu-${Math.floor(Math.random() * 1000000)}`;\n\n      this.reset();\n      this.$chip = $(`\n<div class=\"chip chromeless\">\n  <div class=\"chip-content\">\n    <a href=\"${Craft.escapeHtml(\n      value.replace(/ /g, '+')\n    )}\" rel=\"noopener\" target=\"_blank\" class=\"truncate\">\n      ${Craft.escapeHtml(label)}\n    </a>\n    <div class=\"chip-actions\">\n      <button class=\"btn action-btn\" type=\"button\" aria-controls=\"${menuId}\"\n          aria-label=\"${Craft.t('app', 'Actions')}\"\n          data-disclosure-trigger data-icon=\"ellipsis\"></button>\n      <div id=\"${menuId}\" class=\"menu menu--disclosure\"></div>\n    </div>\n  </div>\n</div>\n`).prependTo(this.$container);\n\n      this.menu = this.$chip\n        .find('.action-btn')\n        .disclosureMenu()\n        .data('disclosureMenu');\n      this.initChip();\n    },\n\n    createTextInput: function (value) {\n      this.reset();\n      this.$textInput = Craft.ui\n        .createTextInput(this.settings.inputAttributes)\n        .attr('name', this.settings.inputName)\n        .val(value)\n        .prependTo(this.$container);\n      this.initTextInput();\n      this.$textInput.trigger('input');\n    },\n\n    switchToTextInput: function () {\n      // only remove the first prefix, if set; otherwise the wrong prefix will get added back.\n      const value = this.removeFirstPrefix(this.$hiddenInput.val());\n      this.createTextInput(value);\n    },\n\n    initTextInput: function () {\n      this.addListener(this.$textInput, 'input', () => {\n        const value = this.normalize(this.$textInput.val());\n        this.$hiddenInput.val(value);\n        this.field.updateLabel(this.removePrefix(value));\n      });\n\n      this.addListener(this.$textInput, 'blur', () => {\n        this.maybeSwitchToChip();\n      });\n      this.addListener(this.$textInput, 'keydown', (ev) => {\n        if (ev.keyCode === Garnish.ESC_KEY && this.maybeSwitchToChip()) {\n          ev.stopPropagation();\n          this.$chip.find('a').focus();\n        }\n      });\n    },\n\n    normalize: function (value) {\n      value = Craft.trim(value);\n      if (!value) {\n        return '';\n      }\n      const prefixed = this.ensurePrefix(value);\n      return this.validate(prefixed) ? prefixed : value;\n    },\n\n    validate: function (value) {\n      value = punycode.toASCII(value);\n      return !!value.match(new RegExp(this.settings.pattern, 'i'));\n    },\n\n    maybeSwitchToChip: function () {\n      if (!this.$textInput?.length) {\n        return;\n      }\n\n      const value = this.normalize(this.$textInput.val());\n      if (value && this.validate(value)) {\n        this.createChip(value);\n        return true;\n      }\n\n      return false;\n    },\n\n    initChip: function () {\n      const viewAction = this.menu.addItem({\n        label: Craft.t('app', 'View in a new tab'),\n        icon: async () => await Craft.ui.icon('share'),\n      });\n      const editAction = this.menu.addItem({\n        label: Craft.t('app', 'Edit'),\n        icon: async () => await Craft.ui.icon('pencil'),\n      });\n      const viewFullUrl = this.menu.addItem({\n        label: Craft.t('app', 'Copy URL'),\n        icon: async () => await Craft.ui.icon('link'),\n      });\n      this.menu.addHr();\n      this.menu.addGroup();\n      const removeAction = this.menu.addItem({\n        label: 'Remove',\n        icon: async () => await Craft.ui.icon('xmark'),\n        destructive: true,\n      });\n\n      this.addListener(viewFullUrl, 'activate', () => {\n        Craft.ui.createCopyTextPrompt({\n          label: 'Full URL',\n          value: this.$hiddenInput.val().replace(/ /g, '+'),\n        });\n      });\n\n      this.addListener(viewAction, 'activate', () => {\n        window.open(this.$chip.find('a').attr('href'));\n      });\n\n      this.addListener(editAction, 'activate', () => {\n        this.switchToTextInput();\n        this.$textInput.focus();\n      });\n\n      this.addListener(removeAction, 'activate', () => {\n        this.createTextInput('');\n        this.$textInput.focus();\n      });\n    },\n\n    reset: function () {\n      this.$textInput?.remove();\n      this.$chip?.remove();\n      this.menu?.destroy();\n      this.$textInput = this.$chip = this.menu = null;\n    },\n  },\n  {\n    defaults: {\n      prefixes: null,\n      pattern: null,\n      textInputAttributes: {},\n    },\n  }\n);\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Asset index class\n */\nCraft.AssetIndex = Craft.BaseElementIndex.extend(\n  {\n    $includeSubfoldersContainer: null,\n    $includeSubfoldersCheckbox: null,\n    showingIncludeSubfoldersCheckbox: false,\n\n    $uploadButton: null,\n    $uploadInput: null,\n    $progressBar: null,\n\n    uploader: null,\n    promptHandler: null,\n    progressBar: null,\n    currentFolderId: null,\n\n    $listedFolders: null,\n    itemDrag: null,\n\n    _uploadTotalFiles: 0,\n    _uploadFileProgress: {},\n    _currentUploaderSettings: {},\n    _includeSubfolders: null,\n\n    init: function (elementType, $container, settings) {\n      settings = Object.assign({}, Craft.AssetIndex.defaults, settings);\n      this.setSettings(settings, Craft.BaseElementIndex.defaults);\n\n      if (this.settings.context === 'index') {\n        // remember whether includeSubfolders was set in the query string,\n        // before the URL is updated\n        const queryParams = Craft.getQueryParams();\n        if (queryParams.includeSubfolders !== undefined) {\n          this._includeSubfolders = !!parseInt(queryParams.includeSubfolders);\n        }\n      }\n\n      this.base(elementType, $container, this.settings);\n\n      if (this.settings.context === 'index') {\n        this.itemDrag = new Garnish.DragDrop({\n          activeDropTargetClass: 'sel',\n          minMouseDist: 10,\n          hideDraggee: false,\n          moveHelperToCursor: true,\n          activeDropTargetClass: 'active-drop-target',\n          handle: (item) => $(item).closest('tr,li'),\n          filter: () => {\n            const $container = this.itemDrag.$targetItem.closest('tr,li');\n            this.view.elementSelect.selectItem($container);\n            return this._findDraggableItems(this.view.getSelectedElements());\n          },\n          helper: ($item, index) =>\n            $('<div class=\"offset-drag-helper\"/>')\n              .append($item)\n              .css({\n                opacity: Math.max(0.9 - 0.05 * index, 0),\n                width: '',\n                height: '',\n              }),\n          dropTargets: () => {\n            // volume sources\n            let $dropTargets = $(\n              this.$visibleSources\n                .toArray()\n                .filter(\n                  (source) =>\n                    Garnish.hasAttr(source, 'data-folder-id') &&\n                    Garnish.hasAttr(source, 'data-can-move-to')\n                )\n            );\n            if (this.sourcePath.length <= 1) {\n              // exclude the current source since we're already at the root of it\n              $dropTargets = $dropTargets.not(this.$source);\n            } else {\n              // parent folders in the source path\n              for (let i = 0; i < this.sourcePath.length - 1; i++) {\n                const step = this.sourcePath[i];\n                if (step.folderId) {\n                  $dropTargets = $dropTargets.add(step.$btn);\n                }\n              }\n            }\n            // folders in the elements listing\n            if (this.$listedFolders) {\n              $dropTargets = $dropTargets\n                .add(\n                  this.$listedFolders\n                    .filter('[data-folder-id]')\n                    .closest('tr,li')\n                )\n                .not(this.view.getSelectedElements());\n            }\n            return $dropTargets;\n          },\n          onDragStart: () => {\n            Garnish.$bod.addClass('dragging');\n            this.itemDrag.$draggee.closest('tr,li').addClass('draggee');\n          },\n          onDragStop: async () => {\n            Garnish.$bod.removeClass('dragging');\n\n            const $draggee = this.itemDrag.$draggee;\n            const targetFolderId = this._targetFolderId(\n              this.itemDrag.$activeDropTarget\n            );\n\n            if (!targetFolderId) {\n              $draggee.closest('tr,li').removeClass('draggee');\n              this.itemDrag.returnHelpersToDraggees();\n              return;\n            }\n\n            this.itemDrag.fadeOutHelpers();\n\n            const $folders = $draggee.filter('[data-is-folder]');\n            const $assets = $draggee.not($folders);\n            const folderIds = $folders.toArray().map((item) => {\n              return parseInt($(item).data('folder-id'));\n            });\n            const assetIds = $assets.toArray().map((item) => {\n              return parseInt($(item).data('id'));\n            });\n\n            const mover = new Craft.AssetMover();\n\n            const moveParams = await mover.getMoveParams(folderIds, assetIds);\n            if (!moveParams.proceed) {\n              $draggee.closest('tr,li').removeClass('draggee');\n              return;\n            }\n\n            const totalFoldersMoved = await mover.moveFolders(\n              folderIds,\n              targetFolderId,\n              this.currentFolderId\n            );\n            const totalAssetsMoved = await mover.moveAssets(\n              assetIds,\n              targetFolderId,\n              this.currentFolderId\n            );\n            const totalItemsMoved = totalFoldersMoved + totalAssetsMoved;\n            if (totalItemsMoved) {\n              mover.successNotice(\n                moveParams,\n                Craft.t(\n                  'app',\n                  '{totalItems, plural, =1{Item} other{Items}} moved.',\n                  {\n                    totalItems: totalItemsMoved,\n                  }\n                )\n              );\n              Craft.elementIndex.updateElements(true);\n            } else {\n              $draggee.closest('tr,li').removeClass('draggee');\n            }\n          },\n        });\n\n        this.addListener(Garnish.$win, 'resize,scroll', '_positionProgressBar');\n      } else {\n        this.addListener(this.$main, 'scroll', '_positionProgressBar');\n\n        if (this.settings.modal) {\n          this.settings.modal.on(\n            'updateSizeAndPosition',\n            this._positionProgressBar.bind(this)\n          );\n        }\n      }\n\n      this.addListener(this.$elements, 'keydown', this._onKeyDown.bind(this));\n    },\n\n    _findDraggableItems: function ($items) {\n      return $(\n        $items\n          .toArray()\n          .map((item) => $(item).find('.element:first')[0])\n          .filter((item) => item && Garnish.hasAttr(item, 'data-movable'))\n      );\n    },\n\n    _targetFolderId: function ($dropTarget) {\n      if (!$dropTarget || !$dropTarget.length) {\n        return false;\n      }\n\n      // source?\n      if ($dropTarget.is(this.$visibleSources)) {\n        return $dropTarget.data('folder-id');\n      }\n\n      // source path step?\n      for (let i = 0; i < this.sourcePath.length - 1; i++) {\n        const step = this.sourcePath[i];\n        if ($dropTarget.is(step.$btn)) {\n          return step.folderId;\n        }\n      }\n\n      // folder in the element listing?\n      return $dropTarget.find('.element:first').data('folder-id') || false;\n    },\n\n    afterInit: function () {\n      if (!this.settings.foldersOnly) {\n        this.initForFiles();\n      }\n\n      // Double-clicking or double-tapping on folders should open them\n      this.addListener(this.$elements, 'doubletap', function (ev, touchData) {\n        // Make sure the touch targets are the same\n        // (they may be different if Command/Ctrl/Shift-clicking on multiple elements quickly)\n        if (touchData.firstTap.target === touchData.secondTap.target) {\n          const $element = $(touchData.firstTap.target)\n            .closest('tr,ul.thumbsview > li')\n            .find('.element:first');\n          if (Garnish.hasAttr($element, 'data-is-folder')) {\n            $element.find('a').trigger('activate');\n          }\n        }\n      });\n\n      this.base();\n    },\n\n    /**\n     * Initialize the uploader.\n     *\n     * @private\n     */\n    initForFiles: function () {\n      this.promptHandler = new Craft.PromptHandler();\n      this.progressBar = new Craft.ProgressBar(this.$main, false);\n    },\n\n    createUploadInputs: function () {\n      this.$uploadButton?.remove();\n      this.$uploadInput?.remove();\n\n      this.$uploadButton = $('<button/>', {\n        type: 'button',\n        class: 'btn submit',\n        'data-icon': 'upload',\n        style: 'position: relative; overflow: hidden;',\n        'aria-label': Craft.t('app', 'Upload files'),\n        text: Craft.t('app', 'Upload files'),\n      });\n      this.addButton(this.$uploadButton);\n\n      this.$uploadInput = $(\n        '<input type=\"file\" multiple=\"multiple\" name=\"assets-upload\" />'\n      )\n        .hide()\n        .insertBefore(this.$uploadButton);\n\n      this.$uploadButton.on('click', () => {\n        if (this.$uploadButton.hasClass('disabled')) {\n          return;\n        }\n        if (!this.isIndexBusy) {\n          this.$uploadButton\n            .parent()\n            .find('input[name=assets-upload]')\n            .trigger('click');\n        }\n      });\n    },\n\n    onSelectSource: function () {\n      if (!this.settings.foldersOnly) {\n        this.currentFolderId =\n          this.currentFolderId || this.$source.data('folder-id');\n        const fsType = this.$source.data('fs-type');\n\n        this.createUploadInputs();\n\n        if (\n          this.currentFolderId &&\n          Garnish.hasAttr(this.$source, 'data-can-upload')\n        ) {\n          this.uploader?.destroy();\n          this.$uploadButton.removeClass('disabled');\n\n          const options = {\n            fileInput: this.$uploadInput,\n            dropZone: this.$container,\n            events: {\n              fileuploadstart: this._onUploadStart.bind(this),\n              fileuploadprogressall: this._onUploadProgress.bind(this),\n              fileuploaddone: this._onUploadSuccess.bind(this),\n              fileuploadalways: this._onUploadAlways.bind(this),\n              fileuploadfail: this._onUploadFailure.bind(this),\n            },\n          };\n\n          if (this.settings?.criteria?.kind) {\n            options.allowedKinds = this.settings.criteria.kind;\n          }\n\n          this._currentUploaderSettings = options;\n\n          this.uploader = Craft.createUploader(\n            fsType,\n            this.$uploadButton,\n            options\n          );\n          this.uploader.setParams({\n            folderId: this.currentFolderId,\n          });\n        } else {\n          this.$uploadButton.addClass('disabled');\n        }\n      }\n\n      this.base();\n    },\n\n    onSourcePathChange: function () {\n      const currentFolder = this.sourcePath.length\n        ? this.sourcePath[this.sourcePath.length - 1]\n        : null;\n      this.currentFolderId = currentFolder?.folderId;\n\n      if (!this.settings.foldersOnly && this.currentFolderId) {\n        this.uploader?.setParams({\n          folderId: this.currentFolderId,\n        });\n\n        // will the user be allowed to move items in this folder?\n        const canMoveSubItems =\n          this.context === 'index' && !!currentFolder.canMoveSubItems;\n        this.settings.selectable = this.settings.selectable || canMoveSubItems;\n        this.settings.multiSelect =\n          this.settings.multiSelect || canMoveSubItems;\n      }\n\n      this.base();\n    },\n\n    startSearching: function () {\n      // Does this source have subfolders?\n      if (\n        !this.settings.hideSidebar &&\n        this.sourcePath.length &&\n        this.sourcePath[this.sourcePath.length - 1].hasChildren\n      ) {\n        if (this.$includeSubfoldersContainer === null) {\n          var id =\n            'includeSubfolders-' + Math.floor(Math.random() * 1000000000);\n\n          this.$includeSubfoldersContainer = $(\n            '<div style=\"margin-bottom: -25px; opacity: 0;\"/>'\n          ).insertAfter(this.$search);\n          var $subContainer = $('<div style=\"padding-top: 5px;\"/>').appendTo(\n            this.$includeSubfoldersContainer\n          );\n          this.$includeSubfoldersCheckbox = $(\n            '<input type=\"checkbox\" id=\"' + id + '\" class=\"checkbox\"/>'\n          ).appendTo($subContainer);\n          $('<label class=\"light smalltext\" for=\"' + id + '\"/>')\n            .text(' ' + Craft.t('app', 'Search in subfolders'))\n            .appendTo($subContainer);\n\n          this.addListener(\n            this.$includeSubfoldersCheckbox,\n            'change',\n            function () {\n              this.setSelecetedSourceState(\n                'includeSubfolders',\n                this.$includeSubfoldersCheckbox.prop('checked')\n              );\n              this.updateElements();\n            }\n          );\n        } else {\n          this.$includeSubfoldersContainer\n            .velocity('stop')\n            .removeClass('hidden');\n        }\n\n        let checked;\n        if (this._includeSubfolders !== null) {\n          checked = this._includeSubfolders;\n          this._includeSubfolders = null;\n        } else {\n          checked = this.getSelectedSourceState('includeSubfolders', false);\n        }\n        this.$includeSubfoldersCheckbox.prop('checked', checked);\n\n        this.$includeSubfoldersContainer.velocity(\n          {\n            marginBottom: 0,\n            opacity: 1,\n          },\n          'fast'\n        );\n\n        this.showingIncludeSubfoldersCheckbox = true;\n      }\n\n      this.base();\n    },\n\n    stopSearching: function () {\n      if (this.showingIncludeSubfoldersCheckbox) {\n        this.$includeSubfoldersContainer.velocity('stop');\n\n        this.$includeSubfoldersContainer.velocity(\n          {\n            marginBottom: -25,\n            opacity: 0,\n          },\n          {\n            duration: 'fast',\n            complete: () => {\n              this.$includeSubfoldersContainer.addClass('hidden');\n            },\n          }\n        );\n\n        this.showingIncludeSubfoldersCheckbox = false;\n      }\n\n      this.base();\n    },\n\n    getViewSettings: function () {\n      const settings = {};\n\n      if (this.settings.context === 'index') {\n        // Allow folders to be selected\n        settings.canSelectElement = () => true;\n      }\n\n      return settings;\n    },\n\n    getViewParams: function () {\n      const data = Object.assign(this.base(), {\n        showFolders: this.settings.showFolders && !this.trashed,\n        foldersOnly: this.settings.foldersOnly,\n      });\n\n      if (\n        this.showingIncludeSubfoldersCheckbox &&\n        this.$includeSubfoldersCheckbox.prop('checked')\n      ) {\n        data.criteria.includeSubfolders = true;\n      }\n\n      return data;\n    },\n\n    /**\n     * React on upload submit.\n     *\n     * @private\n     */\n    _onUploadStart: function () {\n      this.setIndexBusy();\n\n      // Initial values\n      this._positionProgressBar();\n      this.progressBar.resetProgressBar();\n      this.progressBar.showProgressBar();\n\n      this.promptHandler.resetPrompts();\n    },\n\n    /**\n     * Update uploaded byte count.\n     */\n    _onUploadProgress: function (event, data = null) {\n      data = event instanceof CustomEvent ? event.detail : data;\n\n      var progress = parseInt(Math.min(data.loaded / data.total, 1) * 100, 10);\n      this.progressBar.setProgressPercentage(progress);\n    },\n\n    /**\n     * On upload success.\n     *\n     * @param {Object} event\n     * @param {Object} data\n     * @private\n     */\n    _onUploadSuccess: function (event, data = null) {\n      const result = event instanceof CustomEvent ? event.detail : data.result;\n\n      // Add the uploaded file to the selected ones, if appropriate\n      this.selectElementAfterUpdate(result.assetId);\n\n      // If there is a prompt, add it to the queue\n      if (result.conflict) {\n        result.prompt = {\n          message: Craft.t('app', result.conflict, {file: result.filename}),\n          choices: [\n            {value: 'keepBoth', title: Craft.t('app', 'Keep both')},\n            {value: 'replace', title: Craft.t('app', 'Replace it')},\n          ],\n          modalSettings: {\n            hideOnEsc: false,\n            hideOnShadeClick: false,\n          },\n        };\n\n        this.promptHandler.addPrompt(result);\n      }\n\n      Craft.cp.runQueue();\n    },\n\n    /**\n     * On upload complete no matter what (success, fail, or abort).\n     */\n    _onUploadAlways: function () {\n      if (this.uploader.isLastUpload()) {\n        this.progressBar.hideProgressBar();\n        this.setIndexAvailable();\n\n        if (this.promptHandler.getPromptCount()) {\n          this.promptHandler.showBatchPrompts(this._uploadFollowup.bind(this));\n        } else {\n          this._updateAfterUpload();\n        }\n      }\n    },\n\n    /**\n     * On Upload Failure.\n     */\n    _onUploadFailure: function (event, data = null) {\n      const response =\n        event instanceof CustomEvent ? event.detail : data?.jqXHR?.responseJSON;\n\n      let {message, filename, errors} = response || {};\n      filename = filename || data?.files?.[0].name;\n      let errorMessages = errors ? Object.values(errors).flat() : [];\n\n      if (!message) {\n        if (errorMessages.length) {\n          message = errorMessages.join('\\n');\n        } else if (filename) {\n          message = Craft.t('app', 'Upload failed for “{filename}”.', {\n            filename,\n          });\n        } else {\n          message = Craft.t('app', 'Upload failed.');\n        }\n      }\n\n      Craft.cp.displayError(message);\n    },\n\n    /**\n     * Update the elements after an upload, setting sort to dateModified descending, if not using index.\n     *\n     * @private\n     */\n    _updateAfterUpload: function () {\n      if (this.settings.context !== 'index') {\n        this.clearSearch();\n        this.setSelectedSortAttribute('dateCreated', 'desc');\n      }\n      this.updateElements();\n    },\n\n    /**\n     * Follow up to an upload that triggered at least one conflict resolution prompt.\n     *\n     * @param {Object} returnData\n     * @private\n     */\n    _uploadFollowup: function (returnData) {\n      this.setIndexBusy();\n      this.progressBar.resetProgressBar();\n\n      this.promptHandler.resetPrompts();\n\n      var finalCallback = () => {\n        this.progressBar.hideProgressBar();\n        this.setIndexAvailable();\n        this._updateAfterUpload();\n      };\n\n      this.progressBar.setItemCount(returnData.length);\n\n      var doFollowup = (parameterArray, parameterIndex, callback) => {\n        var data = {};\n        var action = null;\n        const {replaceAction, deleteAction} = this.uploader.settings;\n\n        const followupAlways = () => {\n          parameterIndex++;\n          this.progressBar.incrementProcessedItemCount(1);\n          this.progressBar.updateProgressBar();\n\n          if (parameterIndex === parameterArray.length) {\n            callback();\n          } else {\n            doFollowup(parameterArray, parameterIndex, callback);\n          }\n        };\n        const followupSuccess = (data) => {\n          if (data.assetId) {\n            this.selectElementAfterUpdate(data.assetId);\n          }\n\n          followupAlways();\n        };\n        const followupFailure = (data) => {\n          Craft.cp.displayError(data.message);\n          followupAlways();\n        };\n\n        if (parameterArray[parameterIndex].choice === 'replace') {\n          action = replaceAction;\n          data.sourceAssetId = parameterArray[parameterIndex].assetId;\n\n          if (parameterArray[parameterIndex].conflictingAssetId) {\n            data.assetId = parameterArray[parameterIndex].conflictingAssetId;\n          } else {\n            data.targetFilename = parameterArray[parameterIndex].filename;\n          }\n        } else if (parameterArray[parameterIndex].choice === 'cancel') {\n          action = deleteAction;\n          data.assetId = parameterArray[parameterIndex].assetId;\n        }\n\n        if (!action) {\n          // We don't really need to do another request, so let's pretend that already happened\n          followupSuccess({\n            assetId: parameterArray[parameterIndex].assetId,\n          });\n        } else {\n          Craft.sendActionRequest('POST', action, {data})\n            .then((response) => followupSuccess(response.data))\n            .catch(({response}) => followupFailure(response.data));\n        }\n      };\n\n      this.progressBar.showProgressBar();\n      doFollowup(returnData, 0, finalCallback);\n    },\n\n    /**\n     * Perform actions after updating elements\n     * @private\n     */\n    onUpdateElements: function () {\n      this._onUpdateElements(false, this.view.getAllElements());\n      this.view.on('appendElements', (ev) => {\n        this._onUpdateElements(true, ev.newElements);\n      });\n\n      this.base();\n    },\n\n    /**\n     * Do the after-update initializations\n     * @private\n     */\n    _onUpdateElements: function (append, $newElements) {\n      this.$listedFolders = $newElements.find(\n        '.element[data-is-folder][data-folder-name]'\n      );\n      for (let i = 0; i < this.$listedFolders.length; i++) {\n        const $folder = this.$listedFolders.eq(i);\n        const $label = $folder.find('.label');\n        const $link = $label.find('.label-link');\n        const folderId = parseInt($folder.data('folder-id'));\n        const folderName = $folder.data('folder-name');\n        const label = Craft.t('app', '{name} folder', {\n          name: folderName,\n        });\n        if (this.settings.disabledFolderIds.includes(folderId)) {\n          $label.attr('aria-label', label);\n          $newElements.has($folder).addClass('disabled');\n          continue;\n        }\n        const sourcePath = $folder.data('source-path');\n        if (sourcePath) {\n          const $newLink = $('<a class=\"label-link\"/>')\n            .html($link.html())\n            .attr({\n              href: Craft.getCpUrl(sourcePath[sourcePath.length - 1].uri),\n              role: 'button',\n              'aria-label': label,\n            });\n          $link.replaceWith($newLink);\n          this.addListener($newLink, 'activate', (ev) => {\n            this.sourcePath = sourcePath;\n            this.clearSearch(false);\n            this.updateElements().then(() => {\n              const firstFocusableEl = this.$elements.find(\n                ':focusable:not(.selectallcontainer)'\n              )[0];\n              if (firstFocusableEl) {\n                firstFocusableEl.focus();\n              }\n            });\n          });\n        }\n      }\n\n      if (this.itemDrag) {\n        const currentFolder = this.sourcePath[this.sourcePath.length - 1];\n        const canMoveSubItems = !!(\n          currentFolder &&\n          currentFolder.folderId &&\n          currentFolder.canMoveSubItems\n        );\n        if (!canMoveSubItems || !append) {\n          this.itemDrag.removeAllItems();\n        }\n        if (canMoveSubItems) {\n          this.itemDrag.addItems(this._findDraggableItems($newElements));\n        }\n      }\n    },\n\n    /**\n     * Handle a keypress\n     * @private\n     */\n    _onKeyDown: function (ev) {\n      if (ev.keyCode === Garnish.SPACE_KEY && ev.shiftKey) {\n        if (Craft.PreviewFileModal.openInstance) {\n          Craft.PreviewFileModal.openInstance.hide();\n        } else if (this.view.elementSelect) {\n          let $element = $(ev.target).closest('.element');\n          if (!$element.length) {\n            $element = $(ev.target).find('.element:first');\n          }\n\n          if ($element.length && !Garnish.hasAttr($element, 'data-folder-id')) {\n            Craft.PreviewFileModal.showForAsset(\n              $element,\n              this.view.elementSelect\n            );\n          }\n        }\n\n        ev.stopPropagation();\n        return false;\n      }\n    },\n\n    /**\n     * @returns {string}\n     */\n    getSourcePathLabel: function () {\n      return Craft.t('app', 'Volume path');\n    },\n\n    /**\n     * @returns {string}\n     */\n    getSourcePathActionLabel: function () {\n      return Craft.t('app', 'Folder actions');\n    },\n\n    getSourcePathActions: function () {\n      const actions = [];\n      const currentFolder = this.sourcePath[this.sourcePath.length - 1];\n\n      if (currentFolder.canCreate) {\n        actions.push({\n          label: Craft.t('app', 'New subfolder'),\n          onSelect: () => {\n            this._createSubfolder();\n          },\n        });\n      }\n\n      if (this.settings.context === 'index') {\n        if (currentFolder.canRename) {\n          actions.push({\n            label: Craft.t('app', 'Rename folder'),\n            onSelect: () => {\n              this._renameFolder();\n            },\n          });\n\n          if (currentFolder.canMove && this.getMoveTargetSourceKeys().length) {\n            actions.push({\n              label: Craft.t('app', 'Move folder'),\n              onSelect: () => {\n                this._moveFolder();\n              },\n            });\n          }\n\n          if (currentFolder.canDelete) {\n            actions.push({\n              label: Craft.t('app', 'Delete folder'),\n              destructive: true,\n              onSelect: () => {\n                this.deleteCurrentFolder();\n              },\n            });\n          }\n        }\n      }\n\n      return actions;\n    },\n\n    _createSubfolder: function () {\n      const currentFolder = this.sourcePath[this.sourcePath.length - 1];\n      const subfolderName = prompt(\n        Craft.t('app', 'Enter the name of the folder')\n      );\n\n      if (subfolderName) {\n        const data = {\n          parentId: currentFolder.folderId,\n          folderName: subfolderName,\n        };\n\n        this.setIndexBusy();\n\n        Craft.sendActionRequest('POST', 'assets/create-folder', {data})\n          .then((response) => {\n            this.setIndexAvailable();\n            Craft.cp.displayNotice(Craft.t('app', 'Folder created.'));\n            this.updateElements(true);\n          })\n          .catch(({response}) => {\n            this.setIndexAvailable();\n            Craft.cp.displayError(response.data.message);\n          });\n      }\n    },\n\n    deleteCurrentFolder: async function () {\n      if (\n        await this.deleteFolder(this.sourcePath[this.sourcePath.length - 1])\n      ) {\n        this.sourcePath = this.sourcePath.slice(0, this.sourcePath.length - 1);\n        this.updateElements();\n      }\n    },\n\n    deleteFolder: async function (folder) {\n      if (\n        !confirm(\n          Craft.t('app', 'Really delete folder “{folder}”?', {\n            folder: folder.label,\n          })\n        )\n      ) {\n        return false;\n      }\n\n      this.setIndexBusy();\n\n      try {\n        await Craft.sendActionRequest('POST', 'assets/delete-folder', {\n          data: {\n            folderId: folder.folderId,\n          },\n        });\n      } catch (e) {\n        Craft.cp.displayError(e?.response?.data?.message);\n        return false;\n      } finally {\n        this.setIndexAvailable();\n      }\n\n      Craft.cp.displayNotice(Craft.t('app', 'Folder deleted.'));\n      return true;\n    },\n\n    /**\n     * Rename\n     */\n    _renameFolder: function () {\n      const currentFolder = this.sourcePath[this.sourcePath.length - 1];\n      const newName = prompt(\n        Craft.t('app', 'Rename folder'),\n        currentFolder.label\n      );\n\n      if (!newName || newName === currentFolder.label) {\n        return;\n      }\n\n      this.setIndexBusy();\n\n      Craft.sendActionRequest('POST', 'assets/rename-folder', {\n        data: {\n          folderId: currentFolder.folderId,\n          newName: newName,\n        },\n      })\n        .then((response) => {\n          Craft.cp.displayNotice(Craft.t('app', 'Folder renamed.'));\n          const sourcePath = this.sourcePath.slice();\n          sourcePath[sourcePath.length - 1].label = response.data.newName;\n          sourcePath[sourcePath.length - 1].uri =\n            sourcePath[sourcePath.length - 2].uri + `/${response.data.newName}`;\n          this.sourcePath = sourcePath;\n        })\n        .catch(({response}) => {\n          Craft.cp.displayError(response.data.message);\n        })\n        .finally(() => {\n          this.setIndexAvailable();\n        });\n    },\n\n    getMoveTargetSourceKeys: function () {\n      return this.$sources\n        .toArray()\n        .filter((source) => {\n          const volumeHandle = $(source).data('volume-handle');\n          return (\n            volumeHandle &&\n            volumeHandle !== 'temp' &&\n            Garnish.hasAttr(source, 'data-can-move-to')\n          );\n        })\n        .map((source) => $(source).data('key'));\n    },\n\n    _moveFolder: function () {\n      const currentFolder = this.sourcePath[this.sourcePath.length - 1];\n      const parentFolder = this.sourcePath[this.sourcePath.length - 2];\n\n      const disabledFolderIds = [currentFolder.folderId];\n      if (parentFolder) {\n        disabledFolderIds.push(parentFolder.folderId);\n      }\n\n      new Craft.VolumeFolderSelectorModal({\n        sources: this.getMoveTargetSourceKeys(),\n        showTitle: true,\n        modalTitle: Craft.t('app', 'Move to'),\n        selectBtnLabel: Craft.t('app', 'Move'),\n        disabledFolderIds: disabledFolderIds,\n        indexSettings: {\n          defaultSource: this.sourceKey,\n          defaultSourcePath: this.sourcePath.slice(\n            0,\n            this.sourcePath.length - 1\n          ),\n        },\n        onSelect: ([targetFolder]) => {\n          this.$sourcePathActionsBtn.focus();\n          const mover = new Craft.AssetMover();\n          mover\n            .moveFolders([currentFolder.folderId], targetFolder.folderId)\n            .then((totalFoldersMoved) => {\n              if (totalFoldersMoved) {\n                Craft.cp.displayNotice(\n                  Craft.t(\n                    'app',\n                    '{totalItems, plural, =1{Item} other{Items}} moved.',\n                    {\n                      totalItems: totalFoldersMoved,\n                    }\n                  )\n                );\n                this.sourcePath = this.sourcePath.slice(\n                  0,\n                  this.sourcePath.length - 1\n                );\n                this.clearSearch(false);\n                this.updateElements();\n              }\n            });\n        },\n      });\n    },\n\n    _positionProgressBar: function () {\n      if (!this.progressBar) {\n        this.progressBar = new Craft.ProgressBar(this.$main, true);\n      }\n\n      var $container = $(),\n        scrollTop = 0,\n        offset = 0;\n\n      if (this.settings.context === 'index') {\n        $container = this.progressBar.$progressBar.closest('#content');\n        scrollTop = Garnish.$win.scrollTop();\n      } else {\n        $container = this.progressBar.$progressBar.closest('.main');\n        scrollTop = this.$main.scrollTop();\n      }\n\n      var containerTop = $container.offset().top;\n      var diff = scrollTop - containerTop;\n      var windowHeight = Garnish.$win.height();\n\n      if ($container.height() > windowHeight) {\n        offset = windowHeight / 2 - 6 + diff;\n      } else {\n        offset = $container.height() / 2 - 6;\n      }\n\n      if (this.settings.context !== 'index') {\n        offset = scrollTop + ($container.height() / 2 - 6);\n      }\n\n      this.progressBar.$progressBar.css({\n        top: offset,\n      });\n    },\n  },\n  {\n    defaults: {\n      showFolders: true,\n      foldersOnly: false,\n      disabledFolderIds: [],\n    },\n  }\n);\n\n// Register it!\nCraft.registerElementIndexClass(\n  'CraftCms\\\\Cms\\\\Asset\\\\Elements\\\\Asset',\n  Craft.AssetIndex\n);\n","/** global: Craft */\n/** global: Garnish */\n/**\n * File Manager.\n */\nCraft.PromptHandler = Garnish.Base.extend({\n  modal: null,\n  $modalContainerDiv: null,\n  $prompt: null,\n  $promptApplyToRemainingContainer: null,\n  $promptApplyToRemainingCheckbox: null,\n  $promptApplyToRemainingLabel: null,\n  $pomptChoices: null,\n\n  _prompts: [],\n  _promptBatchCallback: $.noop,\n  _promptBatchReturnData: [],\n  _promptBatchNum: 0,\n\n  resetPrompts: function () {\n    this._prompts = [];\n    this._promptBatchCallback = $.noop;\n    this._promptBatchReturnData = [];\n    this._promptBatchNum = 0;\n  },\n\n  addPrompt: function (prompt) {\n    this._prompts.push(prompt);\n  },\n\n  getPromptCount: function () {\n    return this._prompts.length;\n  },\n\n  showBatchPrompts: function (callback) {\n    this._promptBatchCallback = callback;\n    this._promptBatchReturnData = [];\n    this._promptBatchNum = 0;\n\n    this._showNextPromptInBatch();\n  },\n\n  _showNextPromptInBatch: function () {\n    var prompt = this._prompts[this._promptBatchNum].prompt,\n      remainingInBatch = this._prompts.length - (this._promptBatchNum + 1);\n\n    this._showPrompt(\n      prompt.message,\n      prompt.choices,\n      this._handleBatchPromptSelection.bind(this),\n      remainingInBatch,\n      prompt.modalSettings\n    );\n  },\n\n  /**\n   * Handles a prompt choice selection.\n   *\n   * @param {string} choice\n   * @param {boolean} applyToRemaining\n   * @private\n   */\n  _handleBatchPromptSelection: function (choice, applyToRemaining) {\n    var prompt = this._prompts[this._promptBatchNum],\n      remainingInBatch = this._prompts.length - (this._promptBatchNum + 1);\n\n    // Record this choice\n    var choiceData = $.extend(prompt, {choice});\n    this._promptBatchReturnData.push(choiceData);\n\n    // Are there any remaining items in the batch?\n    if (remainingInBatch) {\n      // Get ready to deal with the next prompt\n      this._promptBatchNum++;\n\n      // Apply the same choice to the remaining items?\n      if (applyToRemaining) {\n        this._handleBatchPromptSelection(choice, true);\n      } else {\n        // Show the next prompt\n        this._showNextPromptInBatch();\n      }\n    } else {\n      // All done! Call the callback\n      if (typeof this._promptBatchCallback === 'function') {\n        this._promptBatchCallback(this._promptBatchReturnData);\n      }\n    }\n  },\n\n  /**\n   * @callback showPromptCallback\n   * @param {string} choice\n   * @param {boolean} applyToRemaining\n   */\n  /**\n   * Show the user prompt with a given message and choices, plus an optional \"Apply to remaining\" checkbox.\n   *\n   * @param {string} message\n   * @param {Array} choices\n   * @param {showPromptCallback} callback\n   * @param {number} itemsToGo\n   * @param {Object} modalSettings\n   */\n  _showPrompt: function (message, choices, callback, itemsToGo, modalSettings) {\n    this._promptCallback = callback;\n\n    if (this.modal === null) {\n      this.modal = new Garnish.Modal(\n        Object.assign({closeOtherModals: false}, modalSettings)\n      );\n    }\n\n    if (this.$modalContainerDiv === null) {\n      this.$modalContainerDiv = $(\n        '<div class=\"modal fitted prompt-modal\"></div>'\n      )\n        .addClass()\n        .appendTo(Garnish.$bod);\n    }\n\n    this.$prompt = $('<div class=\"body\"></div>').appendTo(\n      this.$modalContainerDiv.empty()\n    );\n\n    this.$promptMessage = $('<p class=\"prompt-msg\"/>').appendTo(this.$prompt);\n\n    this.$promptChoices = $('<div class=\"options\"></div>').appendTo(\n      this.$prompt\n    );\n\n    this.$promptApplyToRemainingContainer = $(\n      '<label class=\"assets-applytoremaining\"/>'\n    )\n      .appendTo(this.$prompt)\n      .hide();\n    this.$promptApplyToRemainingCheckbox = $(\n      '<input type=\"checkbox\"/>'\n    ).appendTo(this.$promptApplyToRemainingContainer);\n    this.$promptApplyToRemainingLabel = $('<span/>').appendTo(\n      this.$promptApplyToRemainingContainer\n    );\n\n    this.$promptButtons = $('<div class=\"buttons right\"/>').appendTo(\n      this.$prompt\n    );\n\n    this.modal.setContainer(this.$modalContainerDiv);\n\n    this.$promptMessage.html(message);\n\n    let $cancelBtn = $('<button/>', {\n      type: 'button',\n      class: 'btn',\n      text: Craft.t('app', 'Cancel'),\n    }).appendTo(this.$promptButtons);\n    let $submitBtn = $('<button/>', {\n      type: 'submit',\n      class: 'btn submit disabled',\n      text: Craft.t('app', 'OK'),\n    }).appendTo(this.$promptButtons);\n\n    for (var i = 0; i < choices.length; i++) {\n      var $radioButtonHtml = $(\n          '<div><label><input type=\"radio\" name=\"promptAction\" value=\"' +\n            choices[i].value +\n            '\"/> ' +\n            choices[i].title +\n            '</label></div>'\n        ).appendTo(this.$promptChoices),\n        $radioButton = $radioButtonHtml.find('input');\n\n      this.addListener($radioButton, 'click', function () {\n        $submitBtn.removeClass('disabled');\n      });\n    }\n\n    this.addListener($submitBtn, 'activate', function (ev) {\n      var choice = $(ev.currentTarget)\n          .parents('.modal')\n          .find('input[name=promptAction]:checked')\n          .val(),\n        applyToRemaining = this.$promptApplyToRemainingCheckbox.prop('checked');\n\n      this._selectPromptChoice(choice, applyToRemaining);\n    });\n\n    this.addListener($cancelBtn, 'activate', function () {\n      var choice = 'cancel',\n        applyToRemaining = this.$promptApplyToRemainingCheckbox.prop('checked');\n\n      this._selectPromptChoice(choice, applyToRemaining);\n    });\n\n    if (itemsToGo) {\n      this.$promptApplyToRemainingContainer.show();\n      this.$promptApplyToRemainingLabel.html(\n        ' ' +\n          Craft.t('app', 'Apply this to the {number} remaining conflicts?', {\n            number: itemsToGo,\n          })\n      );\n    }\n\n    this.modal.show();\n    this.modal.removeListener(Garnish.Modal.$shade, 'click');\n    this.addListener(Garnish.Modal.$shade, 'click', '_cancelPrompt');\n  },\n\n  /**\n   * Handles when a user selects one of the prompt choices.\n   *\n   * @param {string} choice\n   * @param {boolean} applyToRemaining\n   * @private\n   */\n  _selectPromptChoice: function (choice, applyToRemaining) {\n    this.$prompt.fadeOut('fast', () => {\n      this.modal.hide();\n      this._promptCallback(choice, applyToRemaining);\n    });\n  },\n\n  /**\n   * Cancels the prompt.\n   */\n  _cancelPrompt: function () {\n    this._selectPromptChoice('cancel', true);\n  },\n});\n","/** global: Garnish */\n\nCraft.SlideRuleInput = Garnish.Base.extend({\n  $container: null,\n  $options: null,\n  $selectedOption: null,\n  $input: null,\n  value: null,\n  dragging: false,\n  sensitivity: 3,\n  rotateIntent: false,\n\n  startPositionX: null,\n\n  init: function (id, settings) {\n    this.setSettings(settings, Craft.SlideRuleInput.defaultSettings);\n\n    this.value = 0;\n    this.graduationsMin = -70;\n    this.graduationsMax = 70;\n    this.slideMin = -45;\n    this.slideMax = 45;\n\n    this.$container = $('#' + id);\n    this.$overlay = $('<div class=\"overlay\"></div>').appendTo(this.$container);\n    this.$cursor = $('<div class=\"cursor\"></div>').appendTo(this.$container);\n    this.$graduations = $('<div class=\"graduations\"></div>').appendTo(\n      this.$container\n    );\n    this.$graduationsUl = $('<ul></ul>')\n      .attr({\n        'aria-hidden': 'true',\n      })\n      .appendTo(this.$graduations);\n\n    this.$container.attr({\n      role: 'slider',\n      tabindex: '0',\n      'aria-valuemin': this.slideMin,\n      'aria-valuemax': this.slideMax,\n      'aria-valuenow': '0',\n      'aria-valuetext': Craft.t(\n        'app',\n        '{num, number} {num, plural, =1{degree} other{degrees}}',\n        {\n          num: 0,\n        }\n      ),\n    });\n\n    for (var i = this.graduationsMin; i <= this.graduationsMax; i++) {\n      var $li = $(\n        '<li class=\"graduation\" data-graduation=\"' +\n          i +\n          '\"><div class=\"label\">' +\n          i +\n          '</div></li>'\n      ).appendTo(this.$graduationsUl);\n\n      if (i % 5 === 0) {\n        $li.addClass('main-graduation');\n      }\n\n      if (i === 0) {\n        $li.addClass('selected');\n      }\n    }\n\n    this.$options = this.$container.find('.graduation');\n\n    this.addListener(this.$container, 'resize', this._handleResize.bind(this));\n    this.addListener(\n      this.$container,\n      'tapstart',\n      this._handleTapStart.bind(this)\n    );\n    this.addListener(Garnish.$bod, 'tapmove', this._handleTapMove.bind(this));\n    this.addListener(Garnish.$bod, 'tapend', this._handleTapEnd.bind(this));\n    this.addListener(\n      this.$container,\n      'keydown',\n      this._handleKeypress.bind(this)\n    );\n\n    // Set to zero\n\n    // this.setValue(0);\n\n    setTimeout(() => {\n      // (n -1) options because the border is placed on the left of the 10px box\n      this.graduationsCalculatedWidth = (this.$options.length - 1) * 10;\n      this.$graduationsUl.css(\n        'left',\n        -this.graduationsCalculatedWidth / 2 + this.$container.width() / 2\n      );\n    }, 50);\n  },\n\n  _handleResize: function () {\n    var left = this.valueToPosition(this.value);\n    this.$graduationsUl.css('left', left);\n  },\n\n  _handleKeypress: function (event) {\n    const current = parseInt(this.$container.attr('aria-valuenow'), 10);\n\n    switch (event.keyCode) {\n      case Garnish.UP_KEY:\n      case Garnish.RIGHT_KEY:\n        this.setValue(current + 1);\n        break;\n      case Garnish.DOWN_KEY:\n      case Garnish.LEFT_KEY:\n        this.setValue(current - 1);\n        break;\n      case Garnish.PAGE_UP_KEY:\n        this.setValue(current + 10);\n        break;\n      case Garnish.PAGE_DOWN_KEY:\n        this.setValue(current - 10);\n        break;\n      case Garnish.HOME_KEY:\n        this.setValue(this.slideMin);\n        break;\n      case Garnish.END_KEY:\n        this.setValue(this.slideMax);\n        break;\n    }\n\n    this.onChange();\n  },\n\n  _handleTapStart: function (ev, touch) {\n    ev.preventDefault();\n\n    // Only allow rotation if the user taps on anything within the graduations container\n    this.rotateIntent = $(ev.target).is('.graduations *');\n\n    if (!this.rotateIntent) return;\n\n    this.startPositionX = touch.position.x;\n    this.startLeft = this.$graduationsUl.position().left;\n\n    this.onStart();\n  },\n\n  _handleTapMove: function (ev, touch) {\n    if (!this.rotateIntent) return;\n\n    if (Math.abs(touch.position.x - this.startPositionX) > this.sensitivity) {\n      this.dragging = true;\n      this.$container.addClass('dragging');\n      ev.preventDefault();\n      this._setValueFromTouch(touch);\n      this.onChange();\n    }\n  },\n\n  _setValueFromTouch: function (touch) {\n    let referencePosition = this.dragging\n      ? this.startPositionX\n      : this.$cursor.offset().left + this.$cursor.outerWidth() / 2;\n    let delta;\n\n    if (this.dragging) {\n      delta = referencePosition - touch.position.x;\n    } else {\n      delta = touch.position.x - referencePosition;\n    }\n\n    const position = this.startLeft - delta;\n    const value = this.positionToValue(position);\n    this.setValue(value);\n  },\n\n  setValue: function (value) {\n    var left = this.valueToPosition(value);\n    if (value < this.slideMin) {\n      value = this.slideMin;\n      left = this.valueToPosition(value);\n    } else if (value > this.slideMax) {\n      value = this.slideMax;\n      left = this.valueToPosition(value);\n    }\n\n    this.$graduationsUl.css('left', left);\n\n    if (value >= this.slideMin && value <= this.slideMax) {\n      this.$options.removeClass('selected');\n\n      $.each(this.$options, function (key, option) {\n        if ($(option).data('graduation') > 0) {\n          if ($(option).data('graduation') <= value) {\n            $(option).addClass('selected');\n          }\n        }\n        if ($(option).data('graduation') < 0) {\n          if ($(option).data('graduation') >= value) {\n            $(option).addClass('selected');\n          }\n        }\n\n        if ($(option).data('graduation') == 0) {\n          $(option).addClass('selected');\n        }\n      });\n    }\n\n    this.$container.attr({\n      'aria-valuenow': value,\n      'aria-valuetext': Craft.t(\n        'app',\n        '{num, number} {num, plural, =1{degree} other{degrees}}',\n        {num: parseInt(value, 10)}\n      ),\n    });\n    this.value = value;\n  },\n\n  _handleTapEnd: function (ev, touch) {\n    if (!this.rotateIntent) return;\n\n    if (this.dragging) {\n      ev.preventDefault();\n      this.dragging = false;\n      this.$container.removeClass('dragging');\n    } else {\n      this._setValueFromTouch(touch);\n      this.onChange();\n    }\n\n    this.onEnd();\n    this.startPositionX = null;\n    this.rotateIntent = false;\n  },\n\n  positionToValue: function (position) {\n    var scaleMin = this.graduationsMin * -1;\n    var scaleMax = (this.graduationsMin - this.graduationsMax) * -1;\n\n    return (\n      ((this.$graduations.width() / 2 + position * -1) /\n        this.graduationsCalculatedWidth) *\n        scaleMax -\n      scaleMin\n    );\n  },\n\n  valueToPosition: function (value) {\n    var scaleMin = this.graduationsMin * -1;\n    var scaleMax = (this.graduationsMin - this.graduationsMax) * -1;\n\n    return -(\n      ((value + scaleMin) * this.graduationsCalculatedWidth) / scaleMax -\n      this.$graduations.width() / 2\n    );\n  },\n\n  onStart: function () {\n    if (typeof this.settings.onChange === 'function') {\n      this.settings.onStart(this);\n    }\n  },\n\n  onChange: function () {\n    if (typeof this.settings.onChange === 'function') {\n      this.settings.onChange(this);\n    }\n  },\n\n  onEnd: function () {\n    if (typeof this.settings.onChange === 'function') {\n      this.settings.onEnd(this);\n    }\n  },\n\n  defaultSettings: {\n    onStart: $.noop,\n    onChange: $.noop,\n    onEnd: $.noop,\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Link Field\n */\nCraft.LinkField = Garnish.Base.extend({\n  /** @type {jQuery} */\n  $container: null,\n  /** @type {jQuery} */\n  $typeSelect: null,\n  /** @type {jQuery} */\n  $labelInput: null,\n  /** @type {jQuery} */\n  $filenameInput: null,\n\n  init: function (container, settings) {\n    this.$container = $(container);\n    this.$container.data('linkField', this);\n\n    this.$typeSelect = this.$container.find('select:first');\n    this.$labelInput = this.$container\n      .children('[data-label-field]:first')\n      .find('.text:first');\n    this.$filenameInput = this.$container.find(\n      '[data-filename-field]:first .text:first'\n    );\n\n    if (this.$typeSelect.length) {\n      this.$typeSelect\n        .fieldtoggle()\n        .data('fieldtoggle')\n        .on('toggleChange', () => {\n          this.updateLabel();\n          this.updateFilename();\n        });\n    }\n  },\n\n  getActiveLinkTypeContainer: function () {\n    return this.$container.find('[data-link-type]:not(.hidden):first');\n  },\n\n  updateLabel: function (label = null) {\n    const $container = this.getActiveLinkTypeContainer();\n    if (label === null) {\n      label = $container.data('linkLabel') || '';\n    } else {\n      $container.data('linkLabel', label);\n    }\n    this.$labelInput.prop('placeholder', label);\n  },\n\n  updateFilename: function (filename = null) {\n    const $container = this.getActiveLinkTypeContainer();\n    if (filename === null) {\n      filename = $container.data('filename') || '';\n    } else {\n      $container.data('filename', filename);\n    }\n    this.$filenameInput.prop('placeholder', filename);\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\n/**\n * IntervalManager class\n */\nCraft.IntervalManager = Garnish.Base.extend(\n  {\n    _intervalId: null,\n\n    init: function (settings) {\n      this.setSettings(settings, Craft.IntervalManager.defaults);\n    },\n\n    start: function () {\n      this._intervalId = setInterval(() => {\n        this.settings.onInterval();\n      }, this.settings.interval);\n    },\n\n    stop: function () {\n      clearInterval(this._intervalId);\n      this._intervalId = null;\n    },\n  },\n  {\n    defaults: {\n      interval: 5000,\n      onInterval: $.noop,\n    },\n  }\n);\n","/** global: Craft */\n/** global: Garnish */\n/** global: $ */\n/** global: jQuery */\n\n/**\n * Base component select input\n */\nCraft.ComponentSelectInput = Garnish.Base.extend(\n  {\n    componentSelect: null,\n    componentSort: null,\n\n    $container: null,\n    $form: null,\n    $list: null,\n    $components: null,\n    $addBtn: null,\n    $createBtn: null,\n\n    _initialized: false,\n\n    init: function (settings) {\n      this.setSettings(settings, Craft.ComponentSelectInput.defaults);\n\n      // No reason for this to be sortable if we're only allowing one selection\n      if (this.settings.limit === 1) {\n        this.settings.sortable = false;\n      }\n\n      this.$container = $(`#${this.settings.id}`);\n      this.$form = this.$container.closest('form');\n\n      // Store a reference to this class\n      this.$container.data('componentSelect', this);\n\n      this.$list = this.$container.children('ul');\n      this.$addBtn = this.$container.find('.add-btn:first');\n      this.$createBtn = this.$container.find('.create-btn:first');\n\n      this.initComponentSelect();\n      this.initComponentSort();\n      this.resetComponents();\n\n      if (this.$addBtn.length) {\n        this.getOptions().on('activate', (ev) => {\n          const $button = $(ev.currentTarget);\n          this.addComponent($button.data('type'), $button.data('id'));\n        });\n      }\n\n      if (this.$createBtn.length && this.settings.createAction) {\n        this.$createBtn.on('activate', () => {\n          const slideout = new Craft.CpScreenSlideout(\n            this.settings.createAction\n          );\n          slideout.on('submit', (ev) => {\n            const data = ev.response.data;\n            this.addComponent(data.modelClass, data.modelId, true);\n          });\n          slideout.on('close', () => {\n            this.$createBtn.focus();\n          });\n        });\n      }\n\n      if (this.componentSelect) {\n        this.addListener(Garnish.$win, 'mousedown', (ev) => {\n          if (\n            !this.$container.is(ev.target) &&\n            !this.$container.find(ev.target).length\n          ) {\n            this.componentSelect?.deselectAll();\n          }\n        });\n      }\n\n      this._initialized = true;\n    },\n\n    get totalSelected() {\n      return this.$components.length;\n    },\n\n    getComponents() {\n      return this.$list.find('.chip');\n    },\n\n    getOptions() {\n      if (!this.$addBtn.length) {\n        return $();\n      }\n\n      return this.$addBtn\n        .disclosureMenu()\n        .data('disclosureMenu')\n        .$container.find('button');\n    },\n\n    getOption(id) {\n      return this.getOptions().filter(`[data-id=\"${id}\"]`);\n    },\n\n    showOption: function (id) {\n      this.getOption(id).parent('li').removeClass('hidden');\n    },\n\n    hideOption: function (id) {\n      this.getOption(id).parent('li').addClass('hidden');\n    },\n\n    initComponentSelect: function () {\n      if (this.settings.selectable) {\n        this.componentSelect = new Garnish.Select({\n          multi: this.settings.sortable,\n          filter: (target) => {\n            return !$(target).closest('a[href],button,[role=button]').length;\n          },\n          // prevent keyboard focus since component selection is only needed for drag-n-drop\n          makeFocusable: false,\n        });\n      }\n    },\n\n    initComponentSort: function () {\n      if (this.settings.sortable && Craft.hasMousePointerEvents()) {\n        this.componentSort = new Garnish.DragSort({\n          container: this.$list,\n          filter: this.settings.selectable\n            ? () => {\n                // Only return all the selected items if the target item is selected\n                if (\n                  this.componentSort.$targetItem\n                    .children('.chip')\n                    .hasClass('sel')\n                ) {\n                  return this.componentSelect.getSelectedItems().parent('li');\n                } else {\n                  return this.componentSort.$targetItem;\n                }\n              }\n            : null,\n          ignoreHandleSelector: null,\n          handle: '> .chip > .chip-content > .chip-actions > .move',\n          axis: this.getComponentSortAxis(),\n          collapseDraggees: true,\n          magnetStrength: 4,\n          helperLagBase: 1.5,\n          onSortChange: () => {\n            this.onChange();\n          },\n        });\n      }\n    },\n\n    getComponentSortAxis: function () {\n      if (!this.$list.hasClass('inline-chips')) {\n        return 'y';\n      }\n      return null;\n    },\n\n    canAddMoreComponents: function () {\n      return (\n        !this.settings.limit || this.$components.length < this.settings.limit\n      );\n    },\n\n    updateButtons() {\n      if (this.canAddMoreComponents()) {\n        if (this.$addBtn.length) {\n          if (this.getOptions().parent(':not(.hidden)').length) {\n            this.$addBtn.removeClass('hidden');\n          } else {\n            this.$addBtn.addClass('hidden');\n          }\n        }\n\n        if (this.$createBtn.length) {\n          this.$createBtn.removeClass('hidden');\n        }\n      } else {\n        if (this.$addBtn.length) {\n          this.$addBtn.addClass('hidden');\n        }\n        if (this.$createBtn.length) {\n          this.$createBtn.addClass('hidden');\n        }\n      }\n\n      const $container = this.$addBtn.length && this.$addBtn.parent('.flex');\n      if ($container && $container.length) {\n        if ($container.children(':not(.hidden)').length) {\n          $container.removeClass('hidden');\n        } else {\n          $container.addClass('hidden');\n        }\n      }\n    },\n\n    focusNextLogicalElement: function () {\n      if (this.canAddMoreComponents()) {\n        // If can add more components, focus ADD button\n        if (this.$addBtn.length) {\n          this.$addBtn.get(0).focus();\n        }\n      } else {\n        // If can't add more components, focus on the final remove\n        this.focusLastRemoveBtn();\n      }\n    },\n\n    focusLastRemoveBtn: function () {\n      const $removeBtns = this.$container.find('.delete');\n\n      if (!$removeBtns.length) return;\n\n      $removeBtns.last()[0].focus();\n    },\n\n    resetComponents: function () {\n      if (this.$components !== null) {\n        this.removeComponents(this.$components);\n      } else {\n        this.$components = $();\n      }\n\n      this.addComponents(this.getComponents());\n    },\n\n    addComponents: function ($components) {\n      // add the action triggers\n      for (let i = 0; i < $components.length; i++) {\n        this.addComponentInternal($components.eq(i));\n      }\n\n      if (this.settings.selectable) {\n        this.componentSelect.addItems($components);\n      }\n\n      if (this.settings.sortable) {\n        this.componentSort?.addItems($components.parent('li'));\n      }\n\n      $components.on('keydown', (ev) => {\n        if ([Garnish.BACKSPACE_KEY, Garnish.DELETE_KEY].includes(ev.keyCode)) {\n          ev.stopPropagation();\n          ev.preventDefault();\n          const $selected = this.componentSelect.getSelectedItems();\n          for (let i = 0; i < $selected.length; i++) {\n            this.removeComponent($selected.eq(i));\n          }\n        }\n      });\n\n      this.$components = this.$components.add($components);\n\n      this.onChange();\n    },\n\n    addComponentInternal: function ($component) {\n      if (this.settings.addItemsToActionMenus) {\n        const actions = this.defineComponentActions($component);\n        Craft.addActionsToChip($component, actions);\n\n        const disclosureMenu = this.getDisclosureMenu($component);\n        const moveForwardBtn = disclosureMenu.$container.find(\n          '[data-move-forward]'\n        )[0];\n        const moveBackwardBtn = disclosureMenu.$container.find(\n          '[data-move-backward]'\n        )[0];\n\n        disclosureMenu.on('show', () => {\n          const $li = $component.parent();\n          const $prev = $li.prev('li:has(.chip)');\n          const $next = $li.next('li:has(.chip)');\n\n          if (moveForwardBtn) {\n            disclosureMenu.toggleItem(moveForwardBtn, $prev.length);\n          }\n          if (moveBackwardBtn) {\n            disclosureMenu.toggleItem(moveBackwardBtn, $next.length);\n          }\n        });\n\n        this.addListener($component, 'dblclick,taphold', (ev) => {\n          // don't open the edit slideout if we are tapholding to drag\n          if (ev.type === 'taphold' && ev.target.nodeName === 'BUTTON') {\n            return;\n          }\n          disclosureMenu.$container.find('[data-edit-action]').click();\n        });\n      }\n\n      if (this.settings.sortable && Craft.hasMousePointerEvents()) {\n        const $chipActions = $component.find('.chip-actions');\n        if (!$chipActions.has('.move').length) {\n          $('<button/>', {\n            type: 'button',\n            class: 'move icon',\n            title: Craft.t('app', 'Reorder'),\n            'aria-label': Craft.t('app', 'Reorder'),\n            'aria-describedby': $component.find('.label').attr('id'),\n          }).appendTo($chipActions);\n        }\n      }\n\n      this.hideOption($component.data('id'));\n    },\n\n    defineComponentActions: function ($component) {\n      const actions = [];\n\n      if (this.settings.sortable) {\n        const axis = this.getComponentSortAxis();\n        actions.push({\n          icon: async () =>\n            await Craft.ui.icon(\n              axis === 'y'\n                ? 'arrow-up'\n                : Craft.orientation === 'ltr'\n                  ? 'arrow-left'\n                  : 'arrow-right'\n            ),\n          label:\n            axis === 'y'\n              ? Craft.t('app', 'Move up')\n              : Craft.t('app', 'Move forward'),\n          onActivate: (el) => {\n            // don't use `this` in case the chip ends up getting assigned to a different component select\n            $(el)\n              .closest('.menu')\n              .data('disclosureMenu')\n              .$trigger.closest('.componentselect')\n              .data('componentSelect')\n              .moveComponentForward($component);\n          },\n          attributes: {\n            'data-move-forward': true,\n          },\n        });\n        actions.push({\n          icon: async () =>\n            await Craft.ui.icon(\n              axis === 'y'\n                ? 'arrow-down'\n                : Craft.orientation === 'ltr'\n                  ? 'arrow-right'\n                  : 'arrow-left'\n            ),\n          label:\n            axis === 'y'\n              ? Craft.t('app', 'Move down')\n              : Craft.t('app', 'Move backward'),\n          onActivate: (el) => {\n            // don't use `this` in case the chip ends up getting assigned to a different component select\n            $(el)\n              .closest('.menu')\n              .data('disclosureMenu')\n              .$trigger.closest('.componentselect')\n              .data('componentSelect')\n              .moveComponentBackward($component);\n          },\n          attributes: {\n            'data-move-backward': true,\n          },\n        });\n      }\n\n      actions.push({\n        icon: async () => await Craft.ui.icon('remove'),\n        label: Craft.t('app', 'Remove'),\n        onActivate: (el) => {\n          // don't use `this` in case the chip ends up getting assigned to a different component select\n          $(el)\n            .closest('.menu')\n            .data('disclosureMenu')\n            .$trigger.closest('.componentselect')\n            .data('componentSelect')\n            .removeComponent($component);\n        },\n        destructive: true,\n      });\n\n      if (this.$addBtn.length) {\n        actions.push({\n          icon: async () => await Craft.ui.icon('arrows-rotate'),\n          label: Craft.t('app', 'Replace'),\n          callback: () => {\n            const menu = this.$addBtn.disclosureMenu().data('disclosureMenu');\n            menu.$alignmentElement = $component;\n            menu.show();\n          },\n        });\n      }\n\n      return actions;\n    },\n\n    getDisclosureMenu: function ($component) {\n      return $component\n        .find('> .chip-content > .chip-actions .action-btn')\n        .disclosureMenu()\n        .data('disclosureMenu');\n    },\n\n    onChange() {\n      this.componentSelect?.resetItemOrder();\n      this.$components = $().add(this.$components);\n\n      this.updateButtons();\n\n      if (this._initialized) {\n        this.trigger('change');\n      }\n    },\n\n    moveComponentForward($element) {\n      const $li = $element.closest('li');\n      const $prev = $li.prev();\n      if ($prev.length) {\n        $li.insertBefore($prev);\n        this.onChange();\n      }\n    },\n\n    moveComponentBackward($element) {\n      const $li = $element.closest('li');\n      const $next = $li.next();\n      if ($next.length) {\n        $li.insertAfter($next);\n        this.onChange();\n      }\n    },\n\n    removeComponents: function ($components) {\n      if (this.settings.selectable) {\n        this.componentSelect.removeItems($components);\n      }\n\n      // Disable the hidden input in case the form is submitted before this component gets removed from the DOM\n      $components.children('input').prop('disabled', true);\n\n      for (let i = 0; i < $components.length; i++) {\n        this.showOption($components.eq(i).data('id'));\n      }\n\n      // Move the focus to the next component in the list, if there is one\n      let $nextComponent;\n      if (this.settings.selectable) {\n        const lastComponentIndex = this.$components.index($components.last());\n        $nextComponent = this.$components.eq(lastComponentIndex + 1);\n      }\n      if ($nextComponent.length) {\n        $nextComponent.focus();\n      } else {\n        this.focusNextLogicalElement();\n      }\n\n      this.$components = this.$components.not($components);\n      this.onChange();\n    },\n\n    removeComponent: function ($component, animate = true, callback = null) {\n      if (typeof animate == 'function') {\n        callback = animate;\n        animate = true;\n      }\n\n      // Remove any inputs from the form data\n      $('[name]', $component).removeAttr('name');\n      this.removeComponents($component);\n\n      const afterRemove = () => {\n        $component.parent('li').remove();\n        if (callback) {\n          callback();\n        }\n      };\n\n      if (animate) {\n        this.animateComponentAway($component, afterRemove);\n      } else {\n        afterRemove();\n      }\n    },\n\n    animateComponentAway: function ($component, callback) {\n      $component.css('z-index', 0);\n\n      var animateCss = {\n        opacity: -1,\n      };\n      animateCss['margin-' + Craft.left] = -(\n        $component.outerWidth() +\n        parseInt($component.css('margin-' + Craft.right))\n      );\n\n      animateCss['margin-bottom'] = -(\n        $component.outerHeight() + parseInt($component.css('margin-bottom'))\n      );\n\n      $component.velocity(\n        animateCss,\n        Craft.ComponentSelectInput.REMOVE_FX_DURATION,\n        () => {\n          if (callback) {\n            callback();\n          }\n        }\n      );\n    },\n\n    getSelectedComponentIds() {\n      const ids = [];\n      for (let i = 0; i < this.$components.length; i++) {\n        ids.push(this.$components.eq(i).data('id'));\n      }\n      return ids;\n    },\n\n    async addComponent(type, id, addToMenu = false) {\n      const disclosureMenu = this.$addBtn.l