    await this.applyConfig((config) => config);\n  },\n\n  get index() {\n    const tabConfig = this.tab.config;\n    if (typeof tabConfig === 'undefined') {\n      return -1;\n    }\n    return tabConfig.elements.findIndex((c) => c.uid === this.uid);\n  },\n\n  get config() {\n    if (!this.uid) {\n      throw 'Tab is missing its UID';\n    }\n    let config = this.tab.config.elements.find((c) => c.uid === this.uid);\n    if (!config) {\n      config = {\n        uid: this.uid,\n      };\n      this.config = config;\n    }\n    return config;\n  },\n\n  set config(config) {\n    const tabConfig = this.tab.config;\n    const index = this.index;\n    if (index !== -1) {\n      tabConfig.elements[index] = config;\n    } else {\n      const newIndex = $.inArray(\n        this.$container[0],\n        this.$container.parent().children('.fld-element')\n      );\n      tabConfig.elements.splice(newIndex, 0, config);\n    }\n    this.tab.config = tabConfig;\n  },\n\n  updateConfig: function (callback) {\n    const config = callback(this.config);\n    if (config !== false) {\n      this.config = config;\n    }\n  },\n\n  updatePositionInConfig: function () {\n    this.tab.updateConfig((config) => {\n      const elementConfig = this.config;\n      const oldIndex = this.index;\n      const newIndex = $.inArray(\n        this.$container[0],\n        this.$container.parent().children('.fld-element')\n      );\n      if (oldIndex !== -1) {\n        config.elements.splice(oldIndex, 1);\n      }\n      config.elements.splice(newIndex, 0, elementConfig);\n      return config;\n    });\n  },\n\n  destroy: function () {\n    if (this.tab.designer.settings.withCardViewDesigner) {\n      const cvd = this.tab.designer.cvd;\n      if (cvd) {\n        // this needs to be called before removeCheckbox()\n        cvd.updateThumbnailsDropdown(this, 'remove');\n\n        const previewOptions = this.$container.data('preview-options');\n        if (previewOptions?.length) {\n          previewOptions.forEach((option) => {\n            cvd.removeCheckbox(option.value.replace(/\\{uid}/g, this.uid));\n          });\n        }\n      }\n    }\n\n    this.tab.updateConfig((config) => {\n      const index = this.index;\n      if (index === -1) {\n        return false;\n      }\n      config.elements.splice(index, 1);\n      return config;\n    });\n\n    // Set focus to the closest element's first focusable element\n    const $focusElement = this.$container.siblings().find(':focusable:first');\n    if ($focusElement.length) {\n      $focusElement.focus();\n    } else {\n      this.tab.$addBtn.focus();\n    }\n\n    this.tab.designer.elementDrag.removeItems(this.$container);\n    this.$container.remove();\n\n    if (this.isField) {\n      this.tab.designer.refreshSelectedFields();\n\n      if (!this.isMultiInstance) {\n        this.tab.designer.removeFieldByHandle(\n          this.defaultHandle || this.attribute\n        );\n      }\n    } else {\n      // if it's not a field (so a ui element) and it's not multi instance, make it visible for selection again\n      if (!this.isMultiInstance) {\n        let uiLibraryElement = this.tab.designer.$uiLibraryElements.filter(\n          `[data-type=\"${this.$container.data('type')}\"]:first`\n        );\n        if (uiLibraryElement.length) {\n          $(uiLibraryElement[0]).removeClass('hidden');\n        }\n      }\n    }\n\n    this.base();\n  },\n});\n\nCraft.FieldLayoutDesigner.BaseDrag = Garnish.Drag.extend({\n  designer: null,\n  $insertion: null,\n  showingInsertion: false,\n  $caboose: null,\n\n  /**\n   * Constructor\n   */\n  init: function (designer, settings) {\n    this.designer = designer;\n    this.base(this.findItems(), settings);\n  },\n\n  /**\n   * On Drag Start\n   */\n  onDragStart: function () {\n    this.base();\n\n    // Create the insertion\n    this.$insertion = this.createInsertion();\n\n    // Add the caboose\n    this.$caboose = this.createCaboose();\n    this.$items = $().add(this.$items.add