g area on the image within the image editor\n * @property {Object} imageVerticeCoords - The corner coordinates of the image being edited\n */\n\nCraft.AssetImageEditor = Garnish.Modal.extend(\n  {\n    // jQuery objects\n    $body: null,\n    $footer: null,\n    $imageTools: null,\n    $buttons: null,\n    $cancelBtn: null,\n    $replaceBtn: null,\n    $saveBtn: null,\n    $focalPointBtn: null,\n    $editorContainer: null,\n    $straighten: null,\n    $croppingCanvas: null,\n    $fabricElementEditBtn: null,\n    $spinner: null,\n    $constraintContainer: null,\n    $constraintRadioInputs: null,\n    $orientationField: null,\n    $customConstraints: null,\n\n    // FabricJS objects\n    canvas: null,\n    image: null,\n    viewport: null,\n    focalPoint: null,\n    prevFocalPoint: null,\n    focalPointInnerCircle: null,\n    focalPointOuterCircle: null,\n    focalPointPickedIndicator: null,\n    grid: null,\n    croppingCanvas: null,\n    clipper: null,\n    handleFocusIndicator: null,\n    croppingRectangle: null,\n    cropperHandles: null,\n    cropperGrid: null,\n    croppingShade: null,\n    mediumBlueColor: null,\n    moveIcon: null,\n\n    // Image state attributes\n    imageStraightenAngle: 0,\n    viewportRotation: 0,\n    originalWidth: 0,\n    originalHeight: 0,\n    imageVerticeCoords: null,\n    zoomRatio: 1,\n\n    // Editor state attributes\n    animationInProgress: false,\n    currentView: '',\n    assetId: null,\n    cacheBust: null,\n    draggingCropper: false,\n    movingCropper: false,\n    scalingCropper: false,\n    handlePicked: false,\n    draggingFocal: false,\n    cropperPickedUp: false,\n    focusedEditButton: null,\n    focalPickedUp: false,\n    focalClicked: false,\n    cropperClicked: false,\n    previousMouseX: 0,\n    previousMouseY: 0,\n    shiftKeyHeld: false,\n    editorHeight: 0,\n    editorWidth: 0,\n    cropperState: false,\n    scaleFactor: 1,\n    flipData: {},\n    focalPointState: false,\n    maxImageSize: null,\n    lastLoadedDimensions: null,\n    imageIsLoading: false,\n    mouseMoveEvent: null,\n    croppingConstraint: false,\n    constraintOrientation: 'landscape',\n    showingCustomConstraint: false,\n    rectangleHasFocusOutline: false,\n    saving: false,\n    dragEditMode: true,\n\n    announcerTimeout: null,\n\n    // Rendering proxy functions\n    renderImage: null,\n    renderCropper: null,\n\n    _queue: null,\n\n    init: function (assetId, settings) {\n      this._queue = new Craft.Queue();\n\n      this.cacheBust = Date.now();\n\n      this.setSettings(settings, Craft.AssetImageEditor.defaults);\n\n      if (this.settings.allowDegreeFractions === null) {\n        this.settings.allowDegreeFractions = Craft.isImagick;\n      }\n\n      if (Garnish.prefersReducedMotion()) {\n        this.settings.animationDuration = 1;\n      }\n\n      this.assetId = assetId;\n      this.flipData = {x: 0, y: 0};\n\n      // Build the modal\n      this.$container = $(\n        '<form class=\"modal fitted imageeditor\"></form>'\n      ).appendTo(Garnish.$bod);\n      this.$body = $('<div class=\"body\"></div>').appendTo(this.$container);\n      this.$footer = $('<div class=\"footer\"/>').appendTo(this.$container);\n\n      this.base(this.$container, this.settings);\n\n      this.$buttons = $('<div class=\"buttons right\"/>').appendTo(this.$footer);\n      this.$cancelBtn = $('<button/>', {\n        type: 'button',\n        class: 'btn cancel',\n        text: Craft.t('app', 'Cancel'),\n      }).appendTo(this.$buttons);\n\n      if (this.settings.allowSavingAsNew) {\n        this.$saveBtn = Craft.ui\n          .createButton({\n            class: 'save copy',\n            label: Craft.t('app', 'Save as a new {type}', {\n              type: Craft.elementTypeNames[\n                'CraftCms\\\\Cms\\\\Asset\\\\Elements\\\\Asset'\n              ][2],\n            }),\n            spinner: true,\n          })\n          .appendTo(this.$buttons);\n        this.addListener(this.$saveBtn, 'activate', this.saveImage);\n      }\n\n      this.$replaceBtn = Craft.ui\n        .createSubmitButton({\n          class: 'save replace',\n          label: Craft.t('app', 'Save'),\n          spinner: true,\n        })\n        .appendTo(this.$buttons);\n\n      this.addListener(this.$replaceBtn, 'activate', this.saveImage);\n      this.addListener(this.$cancelBtn, 'activate', this.hide);\n      this.removeListener(this.$shade, 'click');\n\n      this.maxImageSize = this.getMaxImageSize();\n      Craft.sendActionRequest('POST', 'assets/image-editor', {\n        data: {assetId},\n      }).then((response) => this.loadEditor(response.data));\n\n      // Get colors\n      const root = document.documentElement;\n      const rootStyles = window.getComputedStyle(root);\n      this.mediumBlueColor = rootStyles.getPropertyValue('--blue-500');\n      this.addLiveRegion();\n    },\n\n    /**\n     * Get the max image size that is viewable in the editor currently\n     */\n    getMaxImageSize: function () {\n      var browserViewportWidth =\n        Garnish.$doc.get(0).documentElement.clientWidth;\n      var browserViewportHeight =\n        Garnish.$doc.get(0).documentElement.clientHeight;\n\n      return (\n        Math.max(browserViewportHeight, browserViewportWidth) *\n        (window.devicePixelRatio > 1 ? 2 : 1)\n      );\n    },\n\n    /**\n     * Load the editor markup and start loading components and the image.\n     *\n     * @param {Object} data\n     */\n    loadEditor: function (data) {\n      if (!data.html) {\n        Craft.cp.displayError(\n          Craft.t('app', 'Could not load the image editor.')\n        );\n      }\n\n      this.$body.html(data.html);\n      this.$tabs = $('.tabs li', this.$body);\n      this.$viewsContainer = $('.views', this.$body);\n      this.$views = $('> div', this.$viewsContainer);\n      this.$imageTools = $('.image-container .image-tools', this.$body);\n      this.$editorContainer = $('.image-container .image', this.$body);\n      this.$cons