d: null,\n\n    $deleteActionRadios: null,\n    $deleteSubmitBtn: null,\n\n    userSelect: null,\n    _deleting: false,\n\n    init: function (userId, settings) {\n      this.id = Math.floor(Math.random() * 1000000000);\n      this.userId = userId;\n      settings = $.extend(Craft.DeleteUserModal.defaults, settings);\n\n      let $form = $(\n        '<form class=\"modal fitted deleteusermodal\" method=\"post\" accept-charset=\"UTF-8\">' +\n          Craft.getCsrfInput() +\n          '<input type=\"hidden\" name=\"action\" value=\"users/delete-user\"/>' +\n          (!Array.isArray(this.userId)\n            ? '<input type=\"hidden\" name=\"userId\" value=\"' + this.userId + '\"/>'\n            : '') +\n          (settings.redirect\n            ? '<input type=\"hidden\" name=\"redirect\" value=\"' +\n              settings.redirect +\n              '\"/>'\n            : '') +\n          '</form>'\n      ).appendTo(Garnish.$bod);\n      let $body = $(\n        '<div class=\"body\">' +\n          '<div class=\"content-summary\">' +\n          '<p>' +\n          Craft.t('app', 'What do you want to do with their content?') +\n          '</p>' +\n          '<ul class=\"bullets\"></ul>' +\n          '</div>' +\n          '<div class=\"options\">' +\n          '<label><input type=\"radio\" name=\"contentAction\" value=\"transfer\"/> ' +\n          Craft.t('app', 'Transfer it to:') +\n          '</label>' +\n          '<div id=\"transferselect' +\n          this.id +\n          '\" class=\"elementselect\">' +\n          '<ul class=\"elements\"></ul>' +\n          '<button type=\"button\" class=\"btn add icon dashed\">' +\n          Craft.t('app', 'Choose a user') +\n          '</button>' +\n          '</div>' +\n          '</div>' +\n          '<div>' +\n          '<label class=\"error\"><input type=\"radio\" name=\"contentAction\" value=\"delete\"/> ' +\n          Craft.t('app', 'Delete their content') +\n          '</label>' +\n          '</div>' +\n          '</div>'\n      ).appendTo($form);\n      let $buttons = $('<div class=\"buttons right\"/>').appendTo($body);\n      let $cancelBtn = $('<button/>', {\n        type: 'button',\n        class: 'btn',\n        text: Craft.t('app', 'Cancel'),\n      }).appendTo($buttons);\n\n      const $contentSummary = $body.find('.content-summary');\n      if (settings.contentSummary.length) {\n        for (let i = 0; i < settings.contentSummary.length; i++) {\n          $contentSummary\n            .find('ul')\n            .append($('<li/>', {text: settings.contentSummary[i]}));\n        }\n      } else {\n        $contentSummary.find('ul').remove();\n      }\n\n      this.$deleteActionRadios = $body.find('input[type=radio]');\n      this.$deleteSubmitBtn = Craft.ui\n        .createSubmitButton({\n          class: 'disabled',\n          label: this._submitBtnLabel(false),\n          spinner: true,\n        })\n        .appendTo($buttons);\n\n      var idParam;\n\n      if (Array.isArray(this.userId)) {\n        idParam = ['and'];\n\n        for (let i = 0; i < this.userId.length; i++) {\n          idParam.push('not ' + this.userId[i]);\n        }\n      } else {\n        idParam = 'not ' + this.userId;\n      }\n\n      this.userSelect = new Craft.BaseElementSelectInput({\n        id: 'transferselect' + this.id,\n        name: 'transferContentTo',\n        elementType: 'CraftCms\\\\Cms\\\\User\\\\Elements\\\\User',\n        criteria: {\n          id: idParam,\n        },\n        limit: 1,\n        modalSettings: {\n          closeOtherModals: false,\n        },\n        onSelectElements: () => {\n          this.updateSizeAndPosition();\n\n          if (!this.$deleteActionRadios.first().prop('checked')) {\n            this.$deleteActionRadios.first().trigger('click');\n          } else {\n            this.validateDeleteInputs();\n          }\n        },\n        onRemoveElements: this.validateDeleteInputs.bind(this),\n        selectable: false,\n        editable: false,\n      });\n\n      this.addListener($cancelBtn, 'click', 'hide');\n\n      this.addListener(\n        this.$deleteActionRadios,\n        'change',\n        'validateDeleteInputs'\n      );\n      this.addListener($form, 'submit', 'handleSubmit');\n\n      this.base($form, settings);\n    },\n\n    _submitBtnLabel: function (withContent) {\n      let message = withContent\n        ? 'Delete {num, plural, =1{user} other{users}} and content'\n        : 'Delete {num, plural, =1{user} other{users}}';\n\n      return Craft.t('app', message, {\n        num: Array.isArray(this.userId) ? this.userId.length : 1,\n      });\n    },\n\n    validateDeleteInputs: function () {\n      var validates = false;\n\n      if (this.$deleteActionRadios.eq(1).prop('checked')) {\n        validates = true;\n        this.$deleteSubmitBtn.find('.label').text(this._submitBtnLabel(true));\n      } else {\n        this.$deleteSubmitBtn.find('.label').text(this._submitBtnLabel(false));\n        if (this.$deleteActionRadios.eq(0).prop('checked')) {\n          validates = !!this.userSelect.totalSelected;\n        }\n      }\n\n      this.updateSizeAndPosition();\n\n      if (validates) {\n        this.$deleteSubmitBtn.removeClass('disabled');\n      } else {\n        this.$deleteSubmitBtn.addClass('disabled');\n      }\n\n      return validates;\n    },\n\n    handleSubmit: function (ev) {\n      if (this._deleting || !this.validateDeleteInputs()) {\n        ev.preventDefault();\n        return;\n      }\n\n      this.$deleteSubmitBtn.addClass('loading');\n      this.disable();\n      this.userSelect.disable();\n      this._deleting = true;\n\n      // Let the onSubmit callback prevent the form from getting submitted\n      try {\n        if (this.settings.onSubmit() === false) {\n          ev.preventDefault();\n        }\n      } catch (e) {\n        ev.preventDefault();\n        this.$deleteSubmitBtn.removeClass('loading');\n        throw e;\n      }\n    },\n\n    onFadeIn: function () {\n      // Auto-focus the first radio\n      if (!Garnish.isMobileBrowser(true)) {\n        this.$deleteActionRadios.first().focus();\n      }\n\n      this.base();\n    },\n  },\n  {\n    defaults: {\n      contentSummary: [],\n      onSubmit: $.noop,\n      redirect: null,\n    },\n  }\n);\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Entry select input\n */\nCraft.EntrySelectInput = Craft.BaseElementSelectInput.extend({\n  get section() {\n    if (!this.settings.sectionId) {\n      return null;\n    }\n    return Craft.publishableSections.find(\n      (s) => s.id === this.settings.sectionId\n    );\n  },\n\n  canCreateElements: function () {\n    return !!this.section;\n  },\n\n  createElement: async function (title) {\n    const response = await Craft.sendActionRequest('POST', 'entries/create', {\n      data: {\n        siteId: this.settings.criteria.siteId,\n        section: this.section.handle,\n        authorId: Craft.userId,\n        title,\n      },\n    });\n\n    const entry = response.data.entry;\n\n    try {\n      await this.showElementEditor(entry);\n    } catch (e) {\n      return null;\n    }\n\n    return entry.id;\n  },\n\n  showElementEditor: function (entry) {\n    return new Promise((resolve, reject) => {\n      const slideout = Craft.createElementEditor(\n        'CraftCms\\\\Cms\\\\Entry\\\\Elements\\\\Entry',\n        {\n          siteId: this.settings.criteria.siteId,\n          elementId: entry.id,\n          draftId: entry.draftId,\n          params: {\n            fresh: 1,\n          },\n        }\n      );\n\n      let submitted = false;\n\n      slideout.on('submit', () => {\n        submitted = true;\n        resolve();\n      });\n\n      slideout.on('close', () => {\n        if (!submitted) {\n          reject();\n        }\n      });\n    });\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\n/** global: $ */\n/** global: jQuery */\n\n/**\n * Base component select input\n */\nCraft.EntryTypeSelectInput = Craft.ComponentSelectInput.extend(\n  {\n    init: function (settings = {}) {\n      this.base(\n        Object.assign({}, Craft.EntryTypeSelectInput.defaults, settings)\n      );\n    },\n\n    addComponentInternal: function ($component) {\n      if (this.settings.allowOverrides) {\n        const disclosureMenu = this.getDisclosureMenu($component);\n        const $editBtn = disclosureMenu.$container.find('[data-edit-action]');\n        if ($editBtn.length) {\n          disclosureMenu.hideItem($editBtn[0]);\n        }\n        if (this.settings.addItemsToActionMenus) {\n          Craft.addActionsToChip(\n            $component,\n            [\n              {\n                icon: async () => await Craft.ui.icon('gear'),\n                label: Craft.t('app', 'Settings'),\n                onActivate: (el) => {\n                  $(el)\n                    .closest('.menu')\n                    .data('disclosureMenu')\n                    .$trigger.closest('.componentselect')\n                    .data('componentSelect')\n                    .createSettings($component);\n                },\n              },\n            ],\n            true\n          );\n        }\n      }\n\n      this.base($component);\n    },\n\n    createSettings: async function ($component) {\n      let data;\n      try {\n        const response = await Craft.sendActionRequest(\n          'POST',\n          'entry-types/render-override-settings',\n          {\n            data: JSON.parse($component.find('input').val()),\n          }\n        );\n        data = response.data;\n      } catch (e) {\n        Craft.cp.displayError(e?.response?.data?.message);\n        throw e;\n      }\n\n      const settingsNamespace = data.namespace;\n      const slideout = await this.createSlideout(data);\n\n      slideout.$container.on('submit', (ev) => {\n        ev.preventDefault();\n        this.applySettings($component, slideout, settingsNamespace);\n      });\n      slideout.on('close', () => {\n        slideout.destroy();\n      });\n\n    