const $field = $(field);\n        $field.removeClass('has-errors');\n        $field.children('.input').removeClass('errors prevalidate');\n        $field.children('ul.errors').remove();\n      });\n\n      try {\n        let data;\n\n        try {\n          const response = await Craft.sendActionRequest(\n            'POST',\n            'entry-types/apply-override-settings',\n            {\n              data: {\n                id: $component.data('id'),\n                settingsNamespace,\n                settings: slideout.$container.serialize(),\n              },\n            }\n          );\n          data = response.data;\n        } catch (e) {\n          let errors = e?.response?.data?.errors;\n          if (errors) {\n            Object.entries(errors).forEach(([name, fieldErrors]) => {\n              const $field = slideout.$container.find(\n                `[data-error-key=\"${name}\"]`\n              );\n              if ($field.length) {\n                Craft.ui.addErrorsToField($field, fieldErrors);\n              }\n            });\n          }\n\n          Craft.cp.displayError(e?.response?.data?.message);\n          throw e;\n        }\n\n        const $newContainer = $(data.chipHtml);\n        $component\n          .find('.chip-label')\n          .replaceWith($newContainer.find('.chip-label'));\n\n        // Update the input with the new config, but keep the old group value around\n        const $input = $component.find('input');\n        const config = {...data.config};\n        const group = JSON.parse($input.val()).group;\n        if (group) {\n          config.group = group;\n        }\n        $input.val(JSON.stringify(config));\n\n        Craft.initUiElements($component);\n\n        this.trigger('applySettings');\n\n        slideout.close();\n        slideout.destroy();\n      } finally {\n        $submitBtn.removeClass('loading');\n      }\n    },\n\n    renderSettings: function (id) {\n      return Object.assign(this.base(), {\n        in