tedCallback() is called after insetBefore/insertAfter\n    // everything can get initialised as expected\n    // we can't use Element.moveBefore/Element.moveAfter as those are experimental at the moment and not available in Safari & FF\n    this.append(this.labelLink);\n\n    this.tooltip?.remove();\n    if (this.$tabs?.length) {\n      this.$tabs.data('tabs')?.off('selectTab');\n    }\n  }\n\n  calculateWidth(text) {\n    const tag = document.createElement('span');\n    Object.assign(tag.style, {\n      position: 'absolute',\n      visibility: 'hidden',\n      whiteSpace: 'nowrap',\n      fontFamily: 'inherit',\n    });\n    tag.innerText = text;\n\n    this.appendChild(tag);\n    const result = tag.clientWidth;\n    this.removeChild(tag);\n    return result;\n  }\n}\n\ncustomElements.define('craft-element-label', CraftElementLabel);\n","/** global: Craft */\n\n/**\n * Nested element manager\n */\nCraft.NestedElementManager = Garnish.Base.extend(\n  {\n    $container: null,\n    $btnContainer: null,\n    elementType: null,\n    $createBtn: null,\n    $pasteBtn: null,\n\n    // cards\n    $elements: null,\n    elementSort: null,\n    elementSelect: null,\n\n    // index\n    elementIndex: null,\n\n    /**\n     * @type {Craft.ElementEditor|null}\n     */\n    elementEditor: null,\n    creatingElement: false,\n\n    init: function (container, elementType, settings) {\n      this.$container = $(container);\n      this.elementType = elementType;\n      this.setSettings(settings, Craft.NestedElementManager.defaults);\n\n      // Is this already a nested element manager?\n      if (this.$container.data('nestedElementManager')) {\n        console.warn(\n          'Double-instantiating a nested element manager on an element'\n        );\n        this.$container.data('nestedElementManager').destroy();\n      }\n\n      this.$container.data('nestedElementManager', this);\n\n      if (this.settings.mode === 'cards') {\n        if (this.$container.is(':has(.elements)')) {\n   