dDetail,\n  JobInfo,\n  JobStatusKey,\n  JobUpdateDetail,\n  QueueJobData,\n  QueueServiceOptions,\n} from '@src/types';\nimport {JobStatus} from '@src/types';\nimport axios from 'axios';\nimport {ConfigService} from '@src/services/Config';\n\n/**\n * Service for managing queue job tracking.\n *\n * @event job-update - Fired when job data changes\n * @event job-complete - Fired when all jobs are done\n * @event job-failed - Fired when a job fails\n *\n * @example\n * ```ts\n * const queue = QueueService.getInstance();\n * queue.addEventListener('job-update', (e) => {\n *   console.log(e.detail.displayedJob);\n * });\n * queue.startTracking();\n * ```\n */\nexport class QueueService extends EventTarget {\n  static #instance: QueueService | null = null;\n  #instanceId = Math.random().toString(36).slice(2);\n\n  // Configuration\n  enabled: boolean = true;\n  #appId: string = '';\n  canAccessQueueManager: boolean = false;\n  #runAutomatically: boolean = true;\n\n  // Job state\n  totalJobs: number = 0;\n  jobInfo: JobInfo[] = [];\n  displayedJob: JobInfo | null = null;\n  displayedJobUnchangedCount: number = 1;\n\n  // Polling control\n  #trackingTimeout: ReturnType<typeof setTimeout> | null = null;\n  isTracking: boolean = false;\n  #abortController: AbortController | null = null;\n\n  // Cross-tab broadcasting\n  #broadcaster: BroadcastChannel | null = null;\n\n  // Configuration service instance\n  #config: ConfigService = ConfigService.getInstance();\n\n  /** Get the singleton instance */\n  static getInstance(): QueueService {\n    if (!QueueService.#instance) {\n      QueueService.#instance = new QueueService();\n    }\n    return QueueService.#instance;\n  }\n\n  /** Reset the singleton (mainly for testing) */\n  static resetInstance(): void {\n    if (QueueService.#instance) {\n      QueueService.#instance.stopTracking();\n      QueueService.#instance.#broadcaster?.close();\n      QueueService.#instance = null;\n    }\n  }\n\n  initialize(options: QueueServiceOptions = {}) {\n    this.#appId = options.appId ?? '';\n    this.canAccessQueueManager = options.canAccessQueueManager ?? false;\n    this.#runAutomatically = options.runAutomatically ?? true;\n    this.#initBroadcaster();\n  }\n\n  // ─── Public Methods ──────────────────────────────────────────────────────────\n\n  /**\n   * Run the queue and start tracking jobs.\n   * Sends a request to execute waiting jobs.\n   * Does nothing if runAutomatically is false.\n   */\n  async runQueue(): Promise<void> {\n    if (!this.#runAutomatically) {\n      // Just track progress without triggering queue execution\n      this.startTracking(false, true);\n      return;\n    }\n\n    try {\n      await axios.post(this.#config.getActionUrl('queue/run'));\n    } catch (e: unknown) {\n      // Ignore errors - queue might already be running\n      console.error(e);\n    }\n\n    this.startTracking(false, true);\n  }\n\n  /**\n   * Start tracking job progress.\n   * @param delay - Delay before starting: true for adaptive delay, number for ms, false for immediate\n   * @param force - Force tracking even if already tracking\n   */\n  startTracking(delay: boolean | number = false, force: boolean = false): void {\n    if (this.isTracking && !force) {\n      return;\n    }\n\n    // Clear any existing timeout\n    if (this.#trackingTimeout) {\n      clearTimeout(this.#trackingTimeout);\n      this.#trackingTimeout = null;\n    }\n\n    // Determine delay\n    let delayMs = 0;\n    if (delay === true) {\n      delayMs = this.#getAdaptiveDelay();\n    } else if (typeof delay === 'number') {\n      delayMs = delay;\n    }\n\n    if (delayMs > 0) {\n      this.#trackingTimeout = setTimeout(() => {\n        this.#trackJobProgress();\n      }, delayMs);\n    } else {\n      this.#trackJobProgress();\n    }\n  }\n\n  /** Stop tracking job progress */\n  stopTracking(): void {\n    this.isTracking = false;\n\n    if (this.#trackingTimeout) {\n      clearTimeout(this.#trackingTimeout);\n      this.#trackingTimeout = null;\n    }\n\n    if (this.#abortController) {\n      this.#abortController.abort();\n      this.#abortController = null;\n    }\n  }\n\n  /**\n   * Set job data from server response.\n   * Used for initial data and cross-tab sync.\n   */\n  setJobData(data: Array<JobInfo>): void {\n    this.totalJobs = data.length;\n    this.#setJobInfo(data);\n  }\n\n  // ─── Private Methods ─────────────────────────────────────────────────────────\n\n  #initBroadcaster(): void {\n    if (typeof BroadcastChannel === 'undefined' || !this.#appId) {\n      return;\n    }\n\n    const channelName = `CraftCMS:${this.#appId}:queue`;\n    this.#broadcaster = new BroadcastChannel(channelName);\n\n    this.#broadcaster.addEventListener('message', (ev) => {\n      this.#handleBroadcastMessage(ev.data);\n    });\n  }\n\n  #handleBroadcastMessage(data: {\n    event: string;\n    instanceId?: string;\n    jobData?: QueueJobData;\n  }): void {\n    // Ignore messages from our own tab\n    if (data.instanceId === this.#instanceId) return;\n\n    switch (data.event) {\n      case 'beforeTrackJobProgress':\n        // Another tab is taking over tracking\n        this.stopTracking();\n        break;\n\n      case 'trackJobProgress':\n        // Another tab finished polling - use their data\n        if (data.jobData) {\n          this.setJobData(data.jobData.jobs);\n        }\n        // Schedule our next poll with extra delay to avoid conflicts\n        if (this.displayedJob !== null) {\n          const delay = this.#getAdaptiveDelay() + 1000;\n          this.startTracking(delay);\n        }\n        break;\n    }\n  }\n\n  #broadcast(event: string, data?: object): void {\n    this.#broadcaster?.postMessage({\n      event,\n      instanceId: this.#instanceId,\n      ...data,\n    });\n  }\n\n  #getAdaptiveDelay(): number {\n    // Start at 500ms, increase by 500ms for each unchanged poll, cap at 60s\n    return Math.min(60000, this.displayedJobUnchangedCount * 500);\n  }\n\n  async #trackJobProgress(): Promise<void> {\n    // Notify other tabs we're taking over\n    this.#broadcast('beforeTrackJobProgress');\n\n    this.isTracking = true;\n    this.#abortController = new AbortController();\n\n    try {\n      const response = await axios.get<QueueJobData>(\n        this.#config.getActionUrl('queue/get-job-info'),\n        {\n          params: {dontExtendSession: 1},\n          signal: this.#abortController.signal,\n        }\n      );\n\n      this.setJobData(response.data.jobs);\n\n      // Broadcast to other tabs\n      this.#broadcast('trackJobProgress', {jobData: response.data});\n\n      // Continue polling while there's an active job to display\n      if (this.displayedJob !== null) {\n        this.startTracking(true, true);\n      }\n    } catch (error) {\n      // Ignore aborted requests\n      if (error instanceof Error && error.name === 'CanceledError') {\n        return;\n      }\n\n      // For auth errors, stop tracking - user needs to log in\n      const axiosError = error as {response?: {status: number}};\n      if (\n        axiosError.response?.status === 400 ||\n        axiosError.response?.status === 403\n      ) {\n        this.stopTracking();\n        return;\n      }\n\n      // For other errors, retry with delay if there's still an active job\n      if (this.displayedJob !== null) {\n        this.startTracking(true, true);\n      }\n    } finally {\n      this.isTracking = false;\n      this.#abortController = null;\n    }\n  }\n\n  #displayedJobEqual(a: JobInfo | null, b: JobInfo | null): boolean {\n    if (a === null && b === null) return true;\n    if (a === null || b === null) return false;\n    return (\n      a.id === b.id &&\n      a.progress === b.progress &&\n      a.progressLabel === b.progressLabel &&\n      a.status === b.status\n    );\n  }\n\n  #setJobInfo(jobs: JobInfo[]): void {\n    const oldDisplayedJob = this.displayedJob;\n\n    this.jobInfo = jobs;\n    this.displayedJob = this.#selectDisplayedJob();\n\n    if (this.#displayedJobEqual(oldDisplayedJob, this.displayedJob)) {\n      this.displayedJobUnchangedCount++;\n    } else {\n      this.displayedJobUnchangedCount = 1;\n    }\n\n    // Emit events\n    this.#emitJobUpdate();\n\n    // Check for failed jobs\n    if (this.displayedJob?.status.value === JobStatus.Failed) {\n      this.#emitJobFailed(this.displayedJob);\n    }\n\n    // Check for completion\n    if (this.displayedJob === null && oldDisplayedJob) {\n      this.#emitJobComplete();\n    }\n  }\n\n  #selectDisplayedJob(): JobInfo | null {\n    if (this.jobInfo?.length === 0) {\n      return null;\n    }\n\n    // Priority: Reserved > Failed > Waiting (non-delayed)\n    const priorities: JobStatusKey[] = [\n      JobStatus.Reserved,\n      JobStatus.Failed,\n      JobStatus.Pending,\n    ];\n\n    for (const status of priorities) {\n      const job = this.jobInfo.find((j) => {\n        if (j.status.value !== status) {\n          return false;\n        }\n\n        // Skip delayed waiting jobs\n        return !(status === JobStatus.Pending && j.delay > 0);\n      });\n\n      if (job) {\n        return job;\n      }\n    }\n\n    return null;\n  }\n\n  #emitJobUpdate(): void {\n    const detail: JobUpdateDetail = {\n      totalJobs: this.totalJobs,\n      jobInfo: this.jobInfo,\n      displayedJob: this.displayedJob,\n    };\n    this.dispatchEvent(new CustomEvent('job-update', {detail}));\n  }\n\n  #emitJobComplete(): void {\n    this.dispatchEvent(new CustomEvent('job-complete'));\n  }\n\n  #emitJobFailed(job: JobInfo): void {\n    const detail: JobFailedDetail = {job};\n    this.dispatchEvent(new CustomEvent('job-failed', {detail}));\n  }\n}\n","/** Job status constants matching server-side values */\nexport const JobStatus = {\n  Pending: 1,\n  Reserved: 2,\n  Done: 3,\n  Failed: 4,\n  Delayed: 5,\n  Cancelled: 6,\n} as const;\n\nexport type JobStatusKey = (typeof JobStatus)[keyof typeof JobStatus];\n\n/** Individual job information from server */\nexport interface JobInfo {\n  uid: string;\n  id: number;\n  description: string;\n  dateCreated: string;\n  progress: number;\n  progressLabel: string | null;\n  status: {\n    label: JobStatusKey;\n    value: number;\n  };\n  delay: number;\n  error?: string;\n  label: string;\n}\n\n/** Response from queue/get-job-info endpoint */\nexport interface QueueJobData {\n  total: number;\n  jobs: JobInfo[];\n}\n\n/** Options for initializing QueueService */\nexport interface QueueServiceOptions {\n  /** Whether queue tracking is enabled */\n  enabled?: boolean;\n  /** Application ID for cross-tab broadcasting */\n  appId?: string;\n  /** Whether current user can access queue manager */\n  canAccessQueueManager?: boolean;\n  /** Whether to run the queue automatically via HTTP requests */\n  runAutomatically?: boolean;\n}\n\n/** Detail for job-update event */\nexport interface JobUpdateDetail {\n  totalJobs: number;\n  jobInfo: JobInfo[];\n  displayedJob: JobInfo | null;\n}\n\n/** Detail for job-failed event */\nexport interface JobFailedDetail {\n  job: JobInfo;\n}\n","// Import from the deep service module rather than the package root. The root\n// entry (`@craftcms/cp`) side-effect-registers WebAwesome components (e.g.\n// `wa-icon`); pulling that into this separately-webpacked legacy bundle causes\n// a duplicate custom-element registration when it loads alongside the Vite app.\nimport {QueueService} from '@craftcms/cp/services/Queue.ts.mjs';\n/** global: Craft */\n/** global: Garnish */\n/** global: $ */\n/** global: jQuery */\n\n/**\n * CP class\n */\nCraft.CP = Garnish.Base.extend(\n  {\n    elementThumbLoader: null,\n    animationBlocker: null,\n    authManager: null,\n    announcerTimeout: null,\n    modalLayers: [],\n\n    $nav: null,\n    $navToggle: null,\n    $globalLiveRegion: null,\n    $globalSkipLinkList: null,\n    $activeLiveRegion: null,\n    $globalSidebar: null,\n    $globalContainer: null,\n    $mainContainer: null,\n    $pageContainer: null,\n    $alerts: null,\n    $crumbs: null,\n    $crumbList: null,\n    $crumbItems: null,\n    $crumbMenuTriggerItem: null,\n    $crumbMenu: null,\n    $crumbMenuList: null,\n    $crumbMenuItems: null,\n    $notificationContainer: null,\n    $notificationHeading: null,\n    $main: null,\n    $primaryForm: null,\n    $headerContainer: null,\n    $header: null,\n    $mainContent: null,\n    $details: null,\n    $detailsToggle: null,\n    $detailsSkipLink: null,\n    $sidebarContainer: null,\n    $sidebarToggle: null,\n    $sidebar: null,\n    $contentContainer: null,\n    $edition: null,\n\n    $confirmUnloadForms: null,\n    $deltaForms: null,\n    $collapsibleTables: null,\n\n    isMobile: null,\n    fixedHeader: false,\n\n    tabManager: null,\n\n    enableQueue: true,\n    totalJobs: 0,\n    displayedJobInfo: null,\n    displayedJobInfoUnchanged: 1,\n    trackJobProgressTimeout: null,\n    trackingJobProgress: false,\n    jobProgressCancelToken: null,\n    jobProgressIcon: null,\n\n    checkingForUpdates: false,\n    forcingRefreshOnUpdatesCheck: false,\n    includingDetailsOnUpdatesCheck: false,\n    checkForUpdatesCallbacks: null,\n    checkForUpdatesFailureCallbacks: null,\n\n    copyElementCallbacks: null,\n    elementCopyNotification: null,\n\n    resizeTimeout: null,\n\n    /** @type QueueService */\n    QueueService: QueueService.getInstance(),\n\n    init: function () {\n      this.elementThumbLoader = new Craft.ElementThumbLoader();\n\n      // Is this session going to expire?\n      if (Craft.remainingSessionTime !== 0) {\n        this.authManager = new Craft.AuthManager();\n      }\n\n      // Find all the key elements\n      this.$nav = $('#nav');\n      this.$navToggle = $('#primary-nav-toggle');\n      this.$globalLiveRegion = $('#global-live-region');\n      this.$globalSkipLinkList = $('#global-skip-links');\n      this.$activeLiveRegion = this.$globalLiveRegion;\n      this.$globalSidebar = $('#global-sidebar');\n      this.$globalContainer = $('#global-container');\n      this.$mainContainer = $('#main-container');\n      this.$pageContainer = $('#page-container');\n      this.$alerts = $('#alerts');\n      this.$crumbs = $('#crumbs');\n      this.$crumbList = $('#crumb-list');\n      this.$crumbItems = this.$crumbList.children('li');\n      this.$notificationContainer = $('#notifications');\n      this.$notificationHeading = $('#cp-notification-heading');\n      this.$main = $('#main');\n      this.$primaryForm = $('#main-form');\n      this.$headerContainer = $('#header-container');\n      this.$header = $('#header');\n      this.$mainContent = $('#main-content');\n      this.$details = $('#details');\n      this.$detailsToggle = $('#details-toggle');\n      this.$detailsSkipLink = $('[href=\"#details-container\"]');\n      this.$detailsContainer = $('#details-container');\n      this.$sidebarContainer = $('#sidebar-container');\n      this.$sidebarToggle = $('#sidebar-toggle');\n      this.$sidebar = $('#sidebar');\n      this.$contentContainer = $('#content-container');\n      this.$collapsibleTables = $('table.collapsible');\n\n      this.isMobile = Garnish.isMobileBrowser();\n\n      //this.updateContentHeading();\n\n      if (!this.isMobile && this.$header.length) {\n        this.addListener(Garnish.$win, 'scroll', 'updateFixedHeader');\n        this.updateFixedHeader();\n      }\n\n      Garnish.$doc.ready(() => {\n        // Update responsive tables on window resize\n        this.addListener(Garnish.$win, 'resize', (ev) => {\n          // Ignore element resizes\n          if (ev.target === window) {\n            this.handleWindowResize();\n\n            clearTimeout(this.resizeTimeout);\n            var cp = this;\n            this.resizeTimeout = setTimeout(function () {\n              cp.setSidebarNavAttributes();\n            }, 100);\n          }\n        });\n        this.handleWindowResize();\n        this.setSidebarNavAttributes();\n\n        // Wait a frame before initializing any confirm-unload