rse = require('./parse')\nvar walk = require('./walk')\nvar stringify = require('./stringify')\n\nfunction ValueParser(value) {\n  if (this instanceof ValueParser) {\n    this.nodes = parse(value)\n    return this\n  }\n  return new ValueParser(value)\n}\n\nValueParser.prototype.toString = function () {\n  return Array.isArray(this.nodes) ? stringify(this.nodes) : ''\n}\n\nValueParser.prototype.walk = function (cb, bubble) {\n  walk(this.nodes, cb, bubble)\n  return this\n}\n\nValueParser.unit = require('./unit')\n\nValueParser.walk = walk\n\nValueParser.stringify = stringify\n\nmodule.exports = ValueParser\n","class CraftGlobalSidebar extends HTMLElement {\n  get items() {\n    return this.querySelectorAll('.sidebar-action');\n  }\n\n  connectedCallback() {\n    this.trigger = this.querySelector('#sidebar-trigger');\n\n    if (this.trigger) {\n      this.trigger.addEventListener('open', this.expand.bind(this));\n      this.trigger.addEventListener('close', this.collapse.bind(this));\n    }\n  }\n\n  disconnectedCallback() {\n    if (this.trigger) {\n      this.trigger.removeEventListener('open', this.expand.bind(this));\n      this.trigger.removeEventListener('close', this.collapse.bind(this));\n    }\n\n    this.expand();\n  }\n\n  itemHasTooltip(item) {\n    return item.querySelector('craft-tooltip');\n  }\n\n  createTooltips() {\n    if (this.items) {\n      this.items.forEach((item) => {\n        if (this.itemHasTooltip(item)) return;\n\n        const tooltip = document.createElement('craft-tooltip');\n        tooltip.setAttribute('placement', 'right');\n        tooltip.setAttribute('trigger', `.sidebar-action`);\n        tooltip.setAttribute('text', item.querySelector('.label')?.textContent);\n        item.append(tooltip);\n      });\n    }\n  }\n\n  destroyTooltips() {\n    if (this.items) {\n      this.items.forEach((item) => {\n        const tooltip = item.querySelector('craft-tooltip');\n        tooltip?.remove();\n      });\n    }\n  }\n\n  expand() {\n    document.body.setAttribute('data-sidebar', 'expanded');\n    Craft.setCookie('sidebar', 'expanded');\n    this.destroyTooltips();\n  }\n\n  collapse() {\n    document.body.setAttribute('data-sidebar', 'collapsed');\n    Craft.setCookie('sidebar', 'collapsed');\n    this.createTooltips();\n  }\n}\n\ncustomElements.define('craft-global-sidebar', CraftGlobalSidebar);\n","var openParentheses = '('.charCodeAt(0)\nvar closeParentheses = ')'.charCodeAt(0)\nvar singleQuote = \"'\".charCodeAt(0)\nvar doubleQuote = '\"'.charCodeAt(0)\nvar backslash = '\\\\'.charCodeAt(0)\nvar slash = '/'.charCodeAt(0)\nvar comma = ','.charCodeAt(0)\nvar colon = ':'.charCodeAt(0)\nvar star = '*'.charCodeAt(0)\nvar uLower = 'u'.charCodeAt(0)\nvar uUpper = 'U'.charCodeAt(0)\nvar plus = '+'.charCodeAt(0)\nvar isUnicodeRange = /^[a-f0-9?-]+$/i\n\nmodule.exports = function (input) {\n  var tokens = []\n  var value = input\n\n  var next, quote, prev, token, escape, escapePos, whitespacePos, parenthesesOpenPos\n  var pos = 0\n  var code = value.charCodeAt(pos)\n  var max = value.length\n  var stack = [{ nodes: tokens }]\n  var balanced = 0\n  var parent\n\n  var name = ''\n  var before = ''\n  var after = ''\n\n  while (pos < max) {\n    // Whitespaces\n    if (code <= 32) {\n      next = pos\n      do {\n        next += 1\n        code = value.charCodeAt(next)\n      } while (code <= 32)\n      token = value.slice(pos, next)\n\n      prev = tokens[tokens.length - 1]\n      if (code === closeParentheses && balanced) {\n        after = token\n      } else if (prev && prev.type === 'div') {\n        prev.after = token\n        prev.sourceEndIndex += token.length\n      } else if (\n        code === comma ||\n        code === colon ||\n        (code === slash &&\n          value.charCodeAt(next + 1) !== star &&\n          (!parent || (parent && parent.type === 'function' && false)))\n      ) {\n        before = token\n      } else {\n        tokens.push({\n          type: 'space',\n          sourceIndex: pos,\n          sourceEndIndex: next,\n          value: token,\n        })\n      }\n\n      pos = next\n\n      // Quotes\n    } else if (code === singleQuote || code === doubleQuote) {\n      next = pos\n      quote = code === singleQuote ? \"'\" : '\"'\n      token = {\n        type: 'string',\n        sourceIndex: pos,\n        quote: quote,\n      }\n      do {\n        escape = false\n        next = value.indexOf(quote, next + 1)\n        if (~next) {\n          escapePos = next\n          while (value.charCodeAt(escapePos - 1) === backslash) {\n            escapePos -= 1\n            escape = !escape\n          }\n        } else {\n          value += quote\n          next = value.length - 1\n          token.unclosed = true\n        }\n      } while (escape)\n      token.value = value.slice(pos + 1, next)\n      token.sourceEndIndex = token.unclosed ? next : next + 1\n      tokens.push(token)\n      pos = next + 1\n      code = value.charCodeAt(pos)\n\n      // Comments\n    } else if (code === slash && value.charCodeAt(pos + 1) === star) {\n      next = value.indexOf('*/', pos)\n\n      token = {\n        type: 'comment',\n        sourceIndex: pos,\n        sourceEndIndex: next + 2,\n      }\n\n      if (next === -1) {\n        token.unclosed = true\n        next = value.length\n        token.sourceEndIndex = next\n      }\n\n      token.value = value.slice(pos + 2, next)\n      tokens.push(token)\n\n      pos = next + 2\n      code = value.charCodeAt(pos)\n\n      // Operation within calc\n    } else if ((code === slash || code === star) && parent && parent.type === 'function' && true) {\n      token = value[pos]\n      tokens.push({\n        type: 'word',\n        sourceIndex: pos - before.length,\n        sourceEndIndex: pos + token.length,\n        value: token,\n      })\n      pos += 1\n      code = value.charCodeAt(pos)\n\n      // Dividers\n    } else if (code === slash || code === comma || code === colon) {\n      token = value[pos]\n\n      tokens.push({\n        type: 'div',\n        sourceIndex: pos - before.length,\n        sourceEndIndex: pos + token.length,\n        value: token,\n        before: before,\n        after: '',\n      })\n      before = ''\n\n      pos += 1\n      code = value.charCodeAt(pos)\n\n      // Open parentheses\n    } else if (openParentheses === code) {\n      // Whitespaces after open parentheses\n      next = pos\n      do {\n        next += 1\n        code = value.charCodeAt(next)\n      } while (code <= 32)\n      parenthesesOpenPos = pos\n      token = {\n        type: 'function',\n        sourceIndex: pos - name.length,\n        value: name,\n        before: value.slice(parenthesesOpenPos + 1, next),\n      }\n      pos = next\n\n      if (name === 'url' && code !== singleQuote && code !== doubleQuote) {\n        next -= 1\n        do {\n          escape = false\n          next = value.indexOf(')', next + 1)\n          if (~next) {\n            escapePos = next\n            while (value.charCodeAt(escapePos - 1) === backslash) {\n              escapePos -= 1\n              escape = !escape\n            }\n          } else {\n            value += ')'\n            next = value.length - 1\n            token.unclosed = true\n          }\n        } while (escape)\n        // Whitespaces before closed\n        whitespacePos = next\n        do {\n          whitespacePos -= 1\n          code = value.charCodeAt(whitespacePos)\n        } while (code <= 32)\n        if (parenthesesOpenPos < whitespacePos) {\n          if (pos !== whitespacePos + 1) {\n            token.nodes = [\n              {\n                type: 'word',\n                sourceIndex: pos,\n                sourceEndIndex: whitespacePos + 1,\n                value: value.slice(pos, whitespacePos + 1),\n              },\n            ]\n          } else {\n            token.nodes = []\n          }\n          if (token.unclosed && whitespacePos + 1 !== next) {\n            token.after = ''\n            token.nodes.p