tNextCheckedItem: function () {\n    const $item = this.$item.nextAll(\n      '.checkbox-select-item:not(.all):has(input[type=checkbox]:checked):first'\n    );\n    return $item.length ? $item : null;\n  },\n\n  getAllCheckedSiblings: function () {\n    return this.$item.siblings(\n      '.checkbox-select-item:not(.all):has(input[type=checkbox]:checked)'\n    );\n  },\n\n  moveUp: function () {\n    const $prev = this.getPrevCheckedItem();\n    if ($prev) {\n      this.$item.insertBefore($prev);\n      this.$item.trigger('movedUp');\n      this.select.trigger('sortChange');\n    }\n  },\n\n  moveDown: function () {\n    const $next = this.getNextCheckedItem();\n    if ($next) {\n      this.$item.insertAfter($next);\n      this.$item.trigger('movedDown');\n      this.select.trigger('sortChange');\n    }\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\n\n/**\n * Base uploader class\n */\nCraft.BaseUploader = Garnish.Base.extend(\n  {\n    allowedKinds: null,\n    $element: null,\n    $fileInput: null,\n    settings: null,\n    fsType: null,\n    formData: {},\n    events: {},\n    _rejectedFiles: {},\n    _extensionList: null,\n    _inProgressCounter: 0,\n\n    init: function ($element, settings) {\n      this._rejectedFiles = {size: [], type: [], limit: []};\n      this.$element = $element;\n      this.settings = $.extend({}, Craft.BaseUploader.defaults, settings);\n      this.formData = this.settings.formData;\n      this.$fileInput = this.settings.fileInput || $element;\n      this.events = this.settings.events;\n\n      if (!this.settings.url) {\n        this.settings.url = this.settings.replace\n          ? Craft.getActionUrl(this.settings.replaceAction)\n          : Craft.getActionUrl(this.settings.createAction);\n      }\n\n      if (this.settings.allowedKinds && this.settings.allowedKinds.length) {\n        if (typeof this.settings.allowedKinds === 'string') {\n          this.settings.allowedKinds = [this.settings.allowedKinds];\n        }\n\n     