            );\n              Craft.elementIndex.updateElements(true);\n            }\n          }\n          // if no, just close the notice;\n          notice.$closeBtn.trigger('click');\n        });\n      }\n    },\n\n    moveAssets: function (assetIds, targetFolderId, currentFolderId) {\n      const requests = assetIds.map((assetId) => {\n        return {\n          for: 'asset',\n          action: 'assets/move-asset',\n          params: {\n            assetId,\n            folderId: targetFolderId,\n            initialFolderId: currentFolderId,\n          },\n        };\n      });\n      return this._batchMoveRequests(requests, {\n        conflictChoices: [\n          {\n            value: 'keepBoth',\n            title: Craft.t('app', 'Keep both'),\n          },\n          {\n            value: 'replace',\n            title: Craft.t('app', 'Replace it'),\n          },\n        ],\n        handleConflictChoice: function (prompt) {\n          const params = {\n            folderId: prompt.request.params.folderId,\n            assetId: prompt.assetId,\n            initialFolderId: prompt.request.params.initialFolderId,\n          };\n          switch (prompt.choice) {\n            case 'replace':\n              params.force = true;\n              break;\n            case 'keepBoth':\n              params.filename = prompt.suggestedFilename;\n              break;\n          }\n          return {\n            action: 'assets/move-asset',\n            params,\n          };\n        },\n      });\n    },\n\n    moveFolders: function (folderIds, targetFolderId, currentFolderId) {\n      return new Promise((resolve, reject) => {\n        const transferList = [];\n        let folderIdsToDelete = [];\n        let folderIdsWithFailedAssets = [];\n\n        const requests = folderIds.map((folderId) => {\n          return {\n            for: 'folder',\n            action: 'assets/move-folder',\n            params: {\n              folderId,\n              parentId: targetFolderId,\n              initialParentId: currentFolderId,\n            },\n            onSuccess: (response) => {\n              if (response.transferList.length) {\n                response.transferList.forEach(\n                  (item) => (item['oldFolderId'] = folderId)\n                );\n                transferList.push(...response.transferList);\n              }\n              folderIdsToDelete.push(folderId);\n            },\n          };\n        });\n\n        this._batchMoveRequests(requests, {\n          conflictChoices: [\n            {\n              value: 'replace',\n              title: Craft.t(\n                'app',\n                'Replace the folder (all existing files will be deleted)'\n              ),\n            },\n            {\n              value: 'merge',\n              title: Craft.t(\n                'app',\n                'Merge the folder (any conflicting files will be replaced)'\n              ),\n            },\n          ],\n          handleConflictChoice: function (prompt) {\n            const params = {\n              folderId: prompt.folderId,\n              parentId: prompt.parentId,\n              initialParentId: prompt.request.params.initialParentId,\n            };\n            switch (prompt.choice) {\n              case 'replace':\n                params.force = true;\n                break;\n              case 'merge':\n                params.merge = true;\n                break;\n            }\n            return {\n              action: 'assets/move-folder',\n              params,\n            };\n          },\n        })\n          .then((totalMoved) => {\n            this._processTransferList(transferList).then((response) => {\n              response.forEach((asset) => {\n                if (asset.error?.length) {\n                  let oldFolderId = asset.request.params.oldFolderId;\n\n                  // store the old folder ID of the asset that failed to move\n                  if (!folderIdsWithFailedAssets.includes(oldFolderId)) {\n                    folderIdsWithFailedAssets.push(oldFolderId);\n                  }\n\n                  // if the old folder ID of the asset that failed to move is due for deletion, prevent it\n                  if (folderIdsToDelete.includes(oldFolderId)) {\n                    folderIdsToDelete = folderIdsToDelete.filter(\n                      function (item) {\n                        return item !== oldFolderId;\n                      }\n                    );\n                  }\n                }\n              });\n\n              // adjust number of moved folders\n              totalMoved = totalMoved - folderIdsWithFailedAssets.length;\n              this._deleteFolders(folderIdsToDelete).then(() => {\n                resolve(totalMoved);\n              });\n            });\n          })\n          .catch(reject);\n      });\n    },\n\n    _processTransferList: function (transferList) {\n      return this._batchRequests(\n        transferList.map((params) => {\n          return {\n            action: 'assets/move-asset',\n            params,\n          };\n        })\n      );\n    },\n\n    _deleteFolders: function (folderIds) {\n      return this._batchRequests(\n        folderIds.map((folderId) => {\n          return {\n            action: 'assets/delete-folder',\n            params: {folderId},\n          };\n        })\n      );\n    },\n\n    _batchMoveRequests: function (requests, settings) {\n      return new Promise((resolve) => {\n        let totalMoved = 0;\n\n        this._batchRequests(requests).then((responses) => {\n          Craft.elementIndex.promptHandler.resetPrompts();\n\n          // Loop through all the responses\n          for (const response of responses) {\n            if (response.success) {\n              if (response.newFolderId) {\n                this.undoMovedFolders.folderIds.push(response.newFolderId);\n                if (this.undoMovedFolders.targetFolderId === null) {\n                  this.undoMovedFolders.targetFolderId =\n                    response.request.params.initialParentId;\n                }\n              } else {\n                this.undoMovedAssets.assetIds.push(\n                  response.request.params.assetId\n                );\n                if (this.undoMovedAssets.targetFolderId === null) {\n                  this.undoMovedAssets.targetFolderId =\n                    response.request.params.initialFolderId;\n                }\n              }\n              totalMoved++;\n            }\n\n            // Push prompt into prompt array\n            if (response.conflict) {\n              this.conflictCount++;\n              Craft.elementIndex.promptHandler.addPrompt(\n                Object.assign({}, response, {\n                  prompt: {\n                    message: response.conflict,\n                    choices: settings.conflictChoices,\n                  },\n                })\n              );\n            }\n\n            if (response.error) {\n              Craft.cp.displayError(response.error);\n            }\n          }\n\n          if (!Craft.elementIndex.promptHandler.getPromptCount()) {\n            resolve(totalMoved);\n            return;\n          }\n\n          Craft.elementIndex.promptHandler.showBatchPrompts((prompts) => {\n            Craft.elementIndex.promptHandler.resetPrompts();\n            const nextRequests = [];\n            for (const prompt of prompts) {\n              if (prompt.choice === 'cancel') {\n                continue;\n              }\n              if (settings.handleConflictChoice) {\n                const nextRequest = settings.handleConflictChoice(prompt);\n                if (prompt.request && prompt.request.onSuccess) {\n                  nextRequest.onSuccess = prompt.request.onSuccess;\n                }\n                nextRequests.push(nextRequest);\n              }\n            }\n            this._batchMoveRequests(nextRequests, settings).then(\n              (nextTotalMoved) => {\n                resolve(totalMoved + nextTotalMoved);\n              }\n            );\n          });\n        });\n      });\n    },\n\n    _batchRequests: function (requests) {\n      return new Promise((resolve) => {\n        if (!requests.length) {\n          resolve([]);\n          return;\n        }\n\n        Craft.elementIndex.setIndexBusy(false);\n        Craft.elementIndex._positionProgressBar();\n        Craft.elementIndex.progressBar.resetProgressBar();\n        Craft.elementIndex.progressBar.setItemCount(requests.length);\n        Craft.elementIndex.progressBar.showProgressBar();\n\n        const responses = [];\n        let activeRequests = requests.length;\n\n        for (const request of requests) {\n          Craft.sendActionRequest('POST', request.action, {\n            data: request.params,\n          })\n            .then((response) => {\n              responses.push(\n                Object.assign(\n                  {\n                    success: true,\n                  },\n                  response.data,\n                  {request}\n                )\n              );\n              if (request.onSuccess) {\n                request.onSuccess(response.data);\n              }\n            })\n            .catch((failure) => {\n              if (failure.response && failure.response.data) {\n                responses.push(\n                  Object.assign(\n                    {\n                      success: false,\n                    },\n                    failure.response.data,\n                    {request}\n                  )\n                );\n              }\n            })\n            .finally(() => {\n              // Was that the last one?\n              if (--activeRequests === 0) {\n                Craft.elementIndex.setIndexAvailable();\n                Craft.elementIndex.progressBar.hideProgressBar();\n                // If assets were just merged we should get the reference tags updated right away\n                Craft.cp.runQueue();\n                resolve(responses);\n              } else {\n                Craft.elementIndex.progressBar.incrementProcessedItemCount(1);\n                Craft.elementIndex.progressBar.updateProgressBar();\n              }\n            });\n        }\n      });\n    },\n  },\n  {\n    // the number of selected items (assets and folders) that can be moved before we ask for confirmation\n    countLimit: 50,\n\n    // the total weight/size of all the selected assets (standalone and in selected folders)\n    // that can be moved before we ask for confirmation\n    sizeLimit: 50000000, // 50MB\n  }\n);\n","/** global: Craft */\n/** global: Garnish */\nCraft.ElementFieldSettings = Garnish.Base.extend({\n  allowMultipleSources: null,\n  $maintainHierarchyField: null,\n  $maintainHierarchyButton: null,\n  $sourcesField: null,\n  $sourceSelect: null,\n  $branchLimitField: null,\n  $maxRelationsField: null,\n  $minRelationsField: null,\n  $defaultPlacementField: null,\n  $viewModeField: null,\n\n  init: function (\n    allowMultipleSources,\n    maintainHierarchyFieldId,\n    sourcesFieldId,\n    branchLimitFieldId,\n    minRelationsFieldId,\n    maxRelationsFieldId,\n    defaultPlacementFieldId,\n    viewModeFieldId\n  ) {\n    this.allowMultipleSources = allowMultipleSources;\n    this.$maintainHierarchyField = $(`#${maintainHierarchyFieldId}`);\n    this.$maintainHierarchyButton = this.$maintainHierarchyField.find('button');\n    this.$sourcesField = $(`#${sourcesFieldId}`);\n    if (!this.allowMultipleSources) {\n      this.$sourceSelect = this.$sourcesField.find('select');\n    }\n    this.$branchLimitField = $(`#${branchLimitFieldId}`);\n    this.$minRelationsField = $(`#${minRelationsFieldId}`);\n    this.$maxRelationsField = $(`#${maxRelationsFieldId}`);\n    this.$defaultPlacementField = $(`#${defaultPlacementFieldId}`);\n    this.$viewModeField = $(`#${viewModeFieldId}`);\n\n    this.updateLimitFields();\n    this.addListener(\n      this.$maintainHierarchyButton,\n      'change',\n      'updateLimitFields'\n    );\n\n    if (this.allowMultipleSources) {\n      this.$sourcesField.find('[type=checkbox]').each(\n        function (index, checkbox) {\n          this.addListener(\n            $(checkbox),\n            'change',\n            'updateMaintainHierarchyField'\n          );\n        }.bind(this)\n      );\n    } else {\n      this.addListener(\n        this.$sourceSelect,\n        'change',\n        'updateMaintainHierarchyField'\n      );\n    }\n    this.updateMaintainHierarchyField();\n  },\n\n  updateLimitFields: function () {\n    if (\n      !this.$maintainHierarchyField.hasClass('hidden') &&\n      this.$maintainHierarchyButton.hasClass('on')\n    ) {\n      this.$minRelationsField.addClass('hidden');\n      this.$maxRelationsField.addClass('hidden');\n      this.$branchLimitField.removeClass('hidden');\n      this.$defaultPlacementField.addClass('hidden');\n      this.$viewModeField.find('select').val('list').trigger('change');\n      this.$viewModeField.addClass('hidden');\n    } else {\n      this.$branchLimitField.addClass('hidden');\n      this.$minRelationsField.removeClass('hidden');\n      this.$maxRelationsField.removeClass('hidden');\n      this.$defaultPlacementField.removeClass('hidden');\n      this.$viewModeField.removeClass('hidden');\n    }\n  },\n\n  updateMaintainHierarchyField: function () {\n    let showField;\n    if (this.allowMultipleSources) {\n      const $checkedInputs = this.$sourcesField.find(\n        '[type=\"checkbox\"]:checked'\n      );\n      showField =\n        $checkedInputs.length === 1 && $checkedInputs.data('structure-id');\n    } else {\n      showField = this.$sourceSelect\n        .children('option:selected')\n        .data('structure-id');\n    }\n\n    if (showField) {\n      this.$maintainHierarchyField.removeClass('hidden');\n    } else {\n      this.$maintainHierarchyField.addClass('hidden');\n    }\n\n    this.updateLimitFields();\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Accordion\n */\nCraft.Accordion = Garnish.Base.extend({\n  $trigger: null,\n  targetSelector: null,\n\n  _$target: null,\n\n  init: function (trigger) {\n    this.$trigger = $(trigger);\n\n    // Is this already an accordion trigger?\n    if (this.$trigger.data('accordion')) {\n      console.warn('Double-instantiating an accordion trigger on an element');\n      this.$trigger.data('accordion').destroy();\n    }\n\n    this.$trigger.data('accordion', this);\n    this.targetSelector = this.$trigger.attr('aria-controls')\n      ? `#${this.$trigger.attr('aria-controls')}`\n      : null;\n\n    if (this.targetSelector) {\n      this._$target = $(this.targetSelector);\n    }\n\n    this.addListener(this.$trigger, 'click', 'onTriggerClick');\n    this.addListener(this.$trigger, 'keypress', (event) => {\n      const key = event.keyCode;\n\n      if (key === Garnish.SPACE_KEY || key === Garnish.RETURN_KEY) {\n        event.preventDefault();\n        this.onTriggerClick();\n      }\n    });\n  },\n\n  onTriggerClick: function () {\n    const isOpen = this.$trigger.attr('aria-expanded') === 'true';\n\n    if (isOpen) {\n      this.hideTarget(this._$target);\n    } else {\n      this.showTarget(this._$target);\n    }\n  },\n\n  showTarget: function ($target) {\n    if ($target && $target.length) {\n      this.showTarget._currentHeight = $target.height();\n\n      $target.removeClass('hidden');\n\n      this.$trigger\n        .removeClass('collapsed')\n        .addClass('expanded')\n        .attr('aria-expanded', 'true');\n\n      for (let i = 0; i < $target.length; i++) {\n        (($t) => {\n          if ($t.prop('nodeName') !== 'SPAN') {\n            $t.height('auto');\n            this.showTarget._targetHeight = $t.height();\n            $t.css({\n              height: this.showTarget._currentHeight,\n              overflow: 'hidden',\n            });\n\n            $t.velocity('stop');\n\n            $t.velocity(\n              {height: this.showTarget._targetHeight},\n              Garnish.getUserPreferredAnimationDuration('fast'),\n              function () {\n                $t.css({\n                  height: '',\n                  overflow: '',\n                });\n              }\n            );\n          }\n        })($target.eq(i));\n      }\n\n      delete this.showTarget._targetHeight;\n      delete this.showTarget._currentHeight;\n\n      // Trigger a resize event in case there are any grids in the target that need to initialize\n      Garnish.$win.trigger('resize');\n    }\n  },\n\n  hideTarget: function ($target) {\n    if ($target && $target.length) {\n      this.$trigger\n        .removeClass('expanded')\n        .addClass('collapsed')\n        .attr('aria-expanded', 'false');\n\n      for (let i = 0; i < $target.length; i++) {\n        (($t) => {\n          if ($t.hasClass('hidden')) {\n            return;\n          }\n          if ($t.prop('nodeName') === 'SPAN') {\n            $t.addClass('hidden');\n          } else {\n            $t.css('overflow', 'hidden');\n            $t.velocity('stop');\n            $t.velocity(\n              {height: 0},\n              Garnish.getUserPreferredAnimationDuration('fast'),\n              function () {\n                $t.addClass('hidden');\n              }\n            );\n          }\n        })($target.eq(i));\n      }\n    }\n  },\n\n  destroy: function () {\n    this.$trigger.removeData('accordion');\n    this.base();\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Handle Generator\n */\nCraft.UriFormatGenerator = Craft.BaseInputGenerator.extend({\n  generateTargetValue: function (sourceVal) {\n    // Remove HTML tags\n    sourceVal = sourceVal.replace(/<(.*?)>/g, '');\n\n    // Make it lowercase\n    sourceVal = sourceVal.toLowerCase();\n\n    // Convert extended ASCII characters to basic ASCII\n    sourceVal = Craft.asciiString(sourceVal);\n\n    // Handle must start with a letter and end with a letter/number\n    sourceVal = sourceVal.replace(/^[^a-z]+/, '');\n    sourceVal = sourceVal.replace(/[^a-z0-9]+$/, '');\n\n    // Get the \"words\"\n    var words = Craft.filterArray(sourceVal.split(/[^a-z0-9]+/));\n\n    return words.join(Craft.slugWordSeparator);\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\n\n/**\n * Queue\n */\nCraft.Queue = Garnish.Base.extend({\n  running: false,\n  paused: false,\n  pausedForVisibility: false,\n  jobs: null,\n\n  get length() {\n    return this.jobs.length;\n  },\n\n  get isPaused() {\n    return this.paused || this.pausedForVisibility;\n  },\n\n  init: function () {\n    this.jobs = [];\n\n    Garnish.$doc.on('visibilitychange', () => {\n      if (this.pausedForVisibility && Craft.isVisible()) {\n        this.pausedForVisibility = false;\n        this._resume();\n      }\n    });\n  },\n\n  /**\n   * Adds a job to the queue.\n   * @param {function} job\n   * @returns {Promise}\n   */\n  push: function (job) {\n    return this._add(job, 'push');\n  },\n\n  /**\n   * Adds a job to the beginning of the queue.\n   * @param {function} job\n   * @returns {Promise}\n   */\n  unshift: function (job) {\n    return this._add(job, 'unshift');\n  },\n\n  pause: function () {\n    if (!this.paused) {\n      this.paused = true;\n      if (!this.pausedForVisibility) {\n        this.trigger('pause');\n      }\n    }\n  },\n\n  resume: function () {\n    if (this.paused) {\n      this.paused = false;\n      this._resume();\n    }\n  },\n\n  /**\n   * Adds a job to the queue.\n   * @param {function} job\n   * @param {string} method\n   * @returns {Promise}\n   * @private\n   */\n  _add: function (job, method) {\n    return new Promise((resolve, reject) => {\n      this.jobs[method](() => {\n        return new Promise((qResolve, qReject) => {\n          job()\n            .then((value) => {\n              // ...arguments doesn't work here :(\n              resolve(value);\n              qResolve();\n            })\n            .catch((value) => {\n              // ...arguments doesn't work here :(\n              reject(value);\n              qReject();\n            });\n        });\n      });\n\n      if (!this.running) {\n        this.trigger('beforeRun');\n        this.running = true;\n        this._exec();\n      }\n    });\n  },\n\n  clear: function () {\n    this.jobs.length = 0;\n  },\n\n  /**\n   * Runs the next job in the queue.\n   * @private\n   */\n  _exec: function () {\n    if (!this.jobs.length) {\n      this.running = false;\n      this.trigger('afterRun');\n      return;\n    }\n\n    if (!this.pausedForVisibility && !Craft.isVisible()) {\n      this.pausedForVisibility = true;\n      if (!this.paused) {\n        this.trigger('pause');\n      }\n    }\n\n    if (this.paused || this.pausedForVisibility) {\n      return;\n    }\n\n    this.trigger('beforeExec');\n    const job = this.jobs.shift();\n    job().finally(() => {\n      this.trigger('afterExec');\n      this._exec();\n    });\n  },\n\n  _resume: function () {\n    if (!this.isPaused) {\n      this.trigger('resume');\n      this._exec();\n    }\n  },\n});\n\nCraft.queue = new Craft.Queue();\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Environment Variable Name Generator\n */\nCraft.EnvVarGenerator = Craft.BaseInputGenerator.extend({\n  generateTargetValue: function (sourceVal) {\n    // Remove HTML tags\n    let name = sourceVal.replace(/<(.*?)>/g, '');\n\n    // Remove inner-word punctuation\n    name = name.replace(/['\"‘’“”ʻ\\[\\]\\(\\)\\{\\}:]/g, '');\n\n    // Make it lowercase\n    name = name.toLowerCase();\n\n    // Convert extended ASCII characters to basic ASCII\n    name = Craft.asciiString(name);\n\n    // Start with a letter\n    name = name.replace(/^[^a-z]+/, '');\n\n    // Get the \"words\"\n    const words = Craft.filterArray(name.split(/[^a-z0-9]+/));\n\n    return words.join('_').toUpperCase();\n  },\n});\n","var minus = '-'.charCodeAt(0)\nvar plus = '+'.charCodeAt(0)\nvar dot = '.'.charCodeAt(0)\nvar exp = 'e'.charCodeAt(0)\nvar EXP = 'E'.charCodeAt(0)\n\n// Check if three code points would start a number\n// https://www.w3.org/TR/css-syntax-3/#starts-with-a-number\nfunction likeNumber(value) {\n  var code = value.charCodeAt(0)\n  var nextCode\n\n  if (code === plus || code === minus) {\n    nextCode = value.charCodeAt(1)\n\n    if (nextCode >= 48 && nextCode <= 57) {\n      return true\n    }\n\n    var nextNextCode = value.charCodeAt(2)\n\n    if (nextCode === dot && nextNextCode >= 48 && nextNextCode <= 57) {\n      return true\n    }\n\n    return false\n  }\n\n  if (code === dot) {\n    nextCode = value.charCodeAt(1)\n\n    if (nextCode >= 48 && nextCode <= 57) {\n      return true\n    }\n\n    return false\n  }\n\n  if (code >= 48 && code <= 57) {\n    return true\n  }\n\n  return false\n}\n\n// Consume a number\n// https://www.w3.org/TR/css-syntax-3/#consume-number\nmodule.exports = function (value) {\n  var pos = 0\n  var length = value.length\n  var code\n  var nextCode\n  var nextNextCode\n\n  if (length === 0 || !likeNumber(value)) {\n    return false\n  }\n\n  code = value.charCodeAt(pos)\n\n  if (code === plus || code === minus) {\n    pos++\n  }\n\n  while (pos < length) {\n    code = value.charCodeAt(pos)\n\n    if (code < 48 || code > 57) {\n      break\n    }\n\n    pos += 1\n  }\n\n  code = value.charCodeAt(pos)\n  nextCode = value.charCodeAt(pos + 1)\n\n  if (code === dot && nextCode >= 48 && nextCode <= 57) {\n    pos += 2\n\n    while (pos < length) {\n      code = value.charCodeAt(pos)\n\n      if (code < 48 || code > 57) {\n        break\n      }\n\n      pos += 1\n    }\n  }\n\n  code = value.charCodeAt(pos)\n  nextCode = value.charCodeAt(pos + 1)\n  nextNextCode = value.charCodeAt(pos + 2)\n\n  if (\n    (code === exp || code === EXP) &&\n    ((nextCode >= 48 && nextCode <= 57) ||\n      ((nextCode === plus || nextCode === minus) && nextNextCode >= 48 && nextNextCode <= 57))\n  ) {\n    pos += nextCode === plus || nextCode === minus ? 3 : 2\n\n    while (pos < length) {\n      code = value.charCodeAt(pos)\n\n      if (code < 48 || code > 57) {\n        break\n      }\n\n      pos += 1\n    }\n  }\n\n  return {\n    number: value.slice(0, pos),\n    unit: value.slice(pos),\n  }\n}\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Live Preview\n */\nCraft.LivePreview = Garnish.Base.extend(\n  {\n    $extraFields: null,\n    $trigger: null,\n    $shade: null,\n    $editorContainer: null,\n    $editor: null,\n    $dragHandle: null,\n    $previewContainer: null,\n    $iframeContainer: null,\n    $iframe: null,\n    $fieldPlaceholder: null,\n\n    previewUrl: null,\n    token: null,\n    basePostData: null,\n    inPreviewMode: false,\n    fields: null,\n    lastPostData: null,\n    updateIframeInterval: null,\n    loading: false,\n    checkAgain: false,\n\n    dragger: null,\n    dragStartEditorWidth: null,\n\n    _slideInOnIframeLoad: false,\n\n    _scrollX: null,\n    _scrollY: null,\n\n    _editorWidth: null,\n    _editorWidthInPx: null,\n\n    init: function (settings) {\n      this.setSettings(settings, Craft.LivePreview.defaults);\n\n      // Should preview requests use a specific URL?\n      // This won't affect how the request gets routed (the action param will override it),\n      // but it will allow the templates to change behavior based on the request URI.\n      if (this.settings.previewUrl) {\n        this.previewUrl = this.settings.previewUrl;\n      } else {\n        this.previewUrl = Craft.baseSiteUrl.replace(/\\/+$/, '') + '/';\n      }\n\n      // Load the preview over SSL if the current request is\n      if (document.location.protocol === 'https:') {\n        this.previewUrl = this.previewUrl.replace(/^http:/, 'https:');\n      }\n\n      // Set the base post data\n      this.basePostData = $.extend({}, this.settings.previewParams);\n\n      // Find the DOM elements\n      this.$extraFields = $(this.settings.extraFields);\n      this.$trigger = $(this.settings.trigger);\n      this.$fieldPlaceholder = $('<div/>');\n\n      // Set the initial editor width\n      this.editorWidth = Craft.getLocalStorage(\n        'LivePreview.editorWidth',\n        Craft.LivePreview.defaultEditorWidth\n      );\n\n      // Event Listeners\n      this.addListener(this.$trigger, 'activate', 'toggle');\n\n      Craft.cp.on('beforeSaveShortcut', () => {\n        if (this.inPreviewMode) {\n          this.moveFieldsBack();\n        }\n      });\n\n      Craft.Preview.instances.push(this);\n    },\n\n    get editorWidth() {\n      return this._editorWidth;\n    },\n\n    get editorWidthInPx() {\n      return this._editorWidthInPx;\n    },\n\n    set editorWidth(width) {\n      var inPx;\n\n      // Is this getting set in pixels?\n      if (width >= 1) {\n        inPx = width;\n        width /= Garnish.$win.width();\n      } else {\n        inPx = Math.round(width * Garnish.$win.width());\n      }\n\n      // Make sure it's no less than the minimum\n      if (inPx < Craft.LivePreview.minEditorWidthInPx) {\n        inPx = Craft.LivePreview.minEditorWidthInPx;\n        width = inPx / Garnish.$win.width();\n      }\n\n      this._editorWidth = width;\n      this._editorWidthInPx = inPx;\n    },\n\n    toggle: function () {\n      if (this.inPreviewMode) {\n        this.exit();\n      } else {\n        this.enter();\n      }\n    },\n\n    enter: function () {\n      if (this.inPreviewMode) {\n        return;\n      }\n\n      if (!this.token) {\n        this.createToken();\n        return;\n      }\n\n      this.trigger('beforeEnter');\n      this.trigger('beforeOpen');\n\n      $(document.activeElement).trigger('blur');\n\n      if (!this.$editor) {\n        this.$shade = $('<div/>', {class: 'modal-shade dark'}).appendTo(\n          Garnish.$bod\n        );\n        this.$editorContainer = $('<div/>', {\n          class: 'lp-editor-container',\n        }).appendTo(Garnish.$bod);\n        this.$previewContainer = $('<div/>', {\n          class: 'lp-preview-container',\n        }).appendTo(Garnish.$bod);\n        this.$iframeContainer = $('<div/>', {\n          class: 'lp-iframe-container',\n        }).appendTo(this.$previewContainer);\n\n        var $editorHeader = $('<header/>', {class: 'flex'}).appendTo(\n          this.$editorContainer\n        );\n        this.$editor = $('<form/>', {class: 'lp-content'}).appendTo(\n          this.$editorContainer\n        );\n        this.$dragHandle = $('<div/>', {class: 'lp-draghandle'}).appendTo(\n          this.$editorContainer\n        );\n        var $closeBtn = $('<button/>', {\n          type: 'button',\n          class: 'btn',\n          text: Craft.t('app', 'Close Preview'),\n        }).appendTo($editorHeader);\n        $('<div/>', {class: 'flex-grow'}).appendTo($editorHeader);\n        let $saveBtn = $('<button/>', {\n          type: 'button',\n          class: 'btn submit',\n          text: Craft.t('app', 'Save'),\n        }).appendTo($editorHeader);\n\n        this.dragger = new Garnish.BaseDrag(this.$dragHandle, {\n          axis: Garnish.X_AXIS,\n          onDragStart: this._onDragStart.bind(this),\n          onDrag: this._onDrag.bind(this),\n          onDragStop: this._onDragStop.bind(this),\n        });\n\n        this.addListener($closeBtn, 'click', 'exit');\n        this.addListener($saveBtn, 'click', 'save');\n      }\n\n      // Set the sizes\n      this.handleWindowResize();\n      this.addListener(Garnish.$win, 'resize', 'handleWindowResize');\n\n      this.$editorContainer.css(Craft.left, -this.editorWidthInPx + 'px');\n      this.$previewContainer.css(Craft.right, -this.getIframeWidth());\n\n      // Move all the fields into the editor rather than copying them\n      // so any JS that's referencing the elements won't break.\n      this.fields = [];\n      var $fields = $(this.settings.fields);\n\n      for (var i = 0; i < $fields.length; i++) {\n        var $field = $($fields[i]),\n          $clone = this._getClone($field);\n\n        // It's important that the actual field is added to the DOM *after* the clone,\n        // so any radio buttons in the field get deselected from the clone rather than the actual field.\n        this.$fieldPlaceholder.insertAfter($field);\n        $field.detach();\n        this.$fieldPlaceholder.replaceWith($clone);\n        $field.appendTo(this.$editor);\n\n        this.fields.push({\n          $field: $field,\n          $clone: $clone,\n        });\n      }\n\n      if (this.updateIframe()) {\n        this._slideInOnIframeLoad = true;\n      } else {\n        this.slideIn();\n      }\n\n      Craft.ElementThumbLoader.retryAll();\n\n      Garnish.uiLayerManager.addLayer(this.$sidebar);\n      Garnish.uiLayerManager.registerShortcut(Garnish.ESC_KEY, () => {\n        this.exit();\n      });\n\n      this.inPreviewMode = true;\n      this.trigger('enter');\n      this.trigger('open');\n    },\n\n    createToken: function () {\n      const data = {previewAction: this.settings.previewAction};\n      Craft.sendActionRequest('POST', 'live-preview/create-token', {data}).then(\n        (response) => {\n          this.token = response.data.token;\n          this.enter();\n        }\n      );\n    },\n\n    save: function () {\n      Craft.cp.submitPrimaryForm();\n    },\n\n    handleWindowResize: function () {\n      // Reset the width so the min width is enforced\n      this.editorWidth = this.editorWidth;\n\n      // Update the editor/iframe sizes\n      this.updateWidths();\n    },\n\n    slideIn: function () {\n      $('html').addClass('noscroll');\n      this.$shade.velocity('fadeIn');\n\n      this.$editorContainer\n        .show()\n        .velocity('stop')\n        .animateLeft(0, 'slow', () => {\n          this.trigger('slideIn');\n          Garnish.$win.trigger('resize');\n        });\n\n      this.$previewContainer\n        .show()\n        .velocity('stop')\n        .animateRight(0, 'slow', () => {\n          this.updateIframeInterval = setInterval(\n            this.updateIframe.bind(this),\n            1000\n          );\n        });\n    },\n\n    exit: function () {\n      if (!this.inPreviewMode) {\n        return;\n      }\n\n      this.trigger('beforeExit');\n      this.trigger('beforeClose');\n\n      $('html').removeClass('noscroll');\n\n      this.removeListener(Garnish.$win, 'resize');\n      Garnish.uiLayerManager.removeLayer();\n\n      if (this.updateIframeInterval) {\n        clearInterval(this.updateIframeInterval);\n      }\n\n      this.moveFieldsBack();\n\n      this.$shade.delay(200).velocity('fadeOut');\n\n      this.$editorContainer\n        .velocity('stop')\n        .animateLeft(-this.editorWidthInPx, 'slow', () => {\n          for (var i = 0; i < this.fields.length; i++) {\n            this.fields[i].$newClone.remove();\n          }\n          this.$editorContainer.hide();\n          this.trigger('slideOut');\n        });\n\n      this.$previewContainer\n        .velocity('stop')\n        .animateRight(-this.getIframeWidth(), 'slow', () => {\n          this.$previewContainer.hide();\n        });\n\n      Craft.ElementThumbLoader.retryAll();\n\n      this.inPreviewMode = false;\n      this.trigger('exit');\n      this.trigger('close');\n    },\n\n    moveFieldsBack: function () {\n      for (var i = 0; i < this.fields.length; i++) {\n        var field = this.fields[i];\n        field.$newClone = this._getClone(field.$field);\n\n        // It's important that the actual field is added to the DOM *after* the clone,\n        // so any radio buttons in the field get deselected from the clone rather than the actual field.\n        this.$fieldPlaceholder.insertAfter(field.$field);\n        field.$field.detach();\n        this.$fieldPlaceholder.replaceWith(field.$newClone);\n        field.$clone.replaceWith(field.$field);\n      }\n\n      Garnish.$win.trigger('resize');\n    },\n\n    getIframeWidth: function () {\n      return Garnish.$win.width() - this.editorWidthInPx;\n    },\n\n    updateWidths: function () {\n      this.$editorContainer.css('width', this.editorWidthInPx + 'px');\n      this.$previewContainer.width(this.getIframeWidth());\n    },\n\n    updateIframe: function (force) {\n      if (force) {\n        this.lastPostData = null;\n      }\n\n      if (!this.inPreviewMode) {\n        return false;\n      }\n\n      if (this.loading) {\n        this.checkAgain = true;\n        return false;\n      }\n\n      // Has the post data changed?\n      var postData = $.extend(\n        Garnish.getPostData(this.$editor),\n        Garnish.getPostData(this.$extraFields)\n      );\n\n      if (\n        !this.lastPostData ||\n        !Craft.compare(postData, this.lastPostData, false)\n      ) {\n        this.lastPostData = postData;\n        this.loading = true;\n\n        var $doc = this.$iframe\n          ? $(this.$iframe[0].contentWindow.document)\n          : null;\n\n        this._scrollX = $doc ? $doc.scrollLeft() : 0;\n        this._scrollY = $doc ? $doc.scrollTop() : 0;\n\n        $.ajax({\n          url:\n            this.previewUrl +\n            (this.previewUrl.indexOf('?') !== -1 ? '&' : '?') +\n            Craft.tokenParam +\n            '=' +\n            this.token,\n          method: 'POST',\n          data: $.extend({}, postData, this.basePostData),\n          headers: {\n            'X-Craft-Token': this.token,\n          },\n          xhrFields: {\n            withCredentials: true,\n          },\n          crossDomain: true,\n          success: this.handleSuccess.bind(this),\n          error: this.handleError.bind(this),\n        });\n\n        return true;\n      } else {\n        return false;\n      }\n    },\n\n    forceUpdateIframe: function () {\n      return this.updateIframe(true);\n    },\n\n    handleSuccess: function (data) {\n      var html =\n        data +\n        '<script type=\"text/javascript\">window.scrollTo(' +\n        this._scrollX +\n        ', ' +\n        this._scrollY +\n        ');</script>';\n\n      // Create a new iframe\n      var $iframe = $('<iframe class=\"lp-preview\" frameborder=\"0\"/>');\n      if (this.$iframe) {\n        $iframe.insertBefore(this.$iframe);\n      } else {\n        $iframe.appendTo(this.$iframeContainer);\n      }\n\n      this.addListener($iframe, 'load', function () {\n        if (this.$iframe) {\n          this.$iframe.remove();\n        }\n        this.$iframe = $iframe;\n\n        if (this._slideInOnIframeLoad) {\n          this.slideIn();\n          this._slideInOnIframeLoad = false;\n        }\n\n        this.removeListener($iframe, 'load');\n      });\n\n      Garnish.requestAnimationFrame(() => {\n        $iframe[0].contentWindow.document.open();\n        $iframe[0].contentWindow.document.write(html);\n        $iframe[0].contentWindow.document.close();\n        this.onResponse();\n      });\n    },\n\n    handleError: function () {\n      this.onResponse();\n    },\n\n    onResponse: function () {\n      this.loading = false;\n\n      if (this.checkAgain) {\n        this.checkAgain = false;\n        this.updateIframe();\n      }\n    },\n\n    _getClone: function ($field) {\n      var $clone = $field.clone();\n\n      // clone() won't account for input values that have changed since the original HTML set them\n      Garnish.copyInputValues($field, $clone);\n\n      // Remove any id= attributes\n      $clone.attr('id', '');\n      $clone.find('[id]').attr('id', '');\n\n      return $clone;\n    },\n\n    _onDragStart: function () {\n      this.dragStartEditorWidth = this.editorWidthInPx;\n      this.$previewContainer.addClass('dragging');\n    },\n\n    _onDrag: function () {\n      if (Craft.orientation === 'ltr') {\n        this.editorWidth = this.dragStartEditorWidth + this.dragger.mouseDistX;\n      } else {\n        this.editorWidth = this.dragStartEditorWidth - this.dragger.mouseDistX;\n      }\n\n      this.updateWidths();\n      this.trigger('drag');\n    },\n\n    _onDragStop: function () {\n      this.$previewContainer.removeClass('dragging');\n      Craft.setLocalStorage('LivePreview.editorWidth', this.editorWidth);\n    },\n\n    destroy: function () {\n      Craft.Preview.instances = Craft.Preview.instances.filter(\n        (o) => o !== this\n      );\n      this.base();\n    },\n  },\n  {\n    defaultEditorWidth: 0.33,\n    minEditorWidthInPx: 320,\n    instances: [],\n\n    defaults: {\n      trigger: '.livepreviewbtn',\n      fields: null,\n      extraFields: null,\n      previewUrl: null,\n      previewAction: null,\n      previewParams: {},\n    },\n\n    getActive: function () {\n      for (const preview of Craft.LivePreview.instances) {\n        if (preview.inPreviewMode) {\n          return preview;\n        }\n      }\n    },\n  }\n);\n\nCraft.LivePreview.init = function (settings) {\n  Craft.livePreview = new Craft.LivePreview(settings);\n};\n","/** global: Craft */\n/** global: Garnish */\n/** global: $ */\n/** global: jQuery */\n\nCraft.FieldLayoutDesigner = Garnish.Base.extend(\n  {\n    $container: null,\n    $innerContainer: null,\n    $configInput: null,\n    $tabContainer: null,\n    $newTabBtn: null,\n    $libraryContainer: null,\n    $selectedLibrary: null,\n    $fieldLibrary: null,\n    $uiLibrary: null,\n    $uiLibraryElements: null,\n    $fieldSearch: null,\n    $clearFieldSearchBtn: null,\n    $fieldGroups: null,\n    $fields: null,\n    $createFieldBtn: null,\n\n    libraryPicker: null,\n    tabGrid: null,\n    elementDrag: null,\n\n    cvd: null,\n    $cvd: null,\n\n    _config: null,\n    _$selectedFields: null,\n\n    init: function (container, settings) {\n      this.$container = $(container);\n      this.setSettings(settings, Craft.FieldLayoutDesigner.defaults);\n\n      this.$configInput = this.$container.children('input[data-config-input]');\n      this._config = JSON.parse(this.$configInput.val());\n      if (!this._config.tabs) {\n        this._config.tabs = [];\n      }\n\n      this._fieldHandles = {};\n\n      this.$innerContainer = this.$container.children('.fld-container');\n      const $workspace = this.$innerContainer.children('.fld-workspace');\n      this.$tabContainer = $workspace.children('.fld-tabs');\n      this.$newTabBtn = $workspace.children('.fld-new-tab-btn');\n      this.$libraryContainer = this.$innerContainer.children('.fld-library');\n\n      this.$fieldLibrary = this.$selectedLibrary =\n        this.$libraryContainer.children('.fld-field-library');\n      let $fieldSearchContainer = this.$fieldLibrary.children('.search');\n      this.$fieldSearch = $fieldSearchContainer.children('input');\n      this.$clearFieldSearchBtn = $fieldSearchContainer.children('.clear-btn');\n      this.$fieldGroups = this.$libraryContainer.find('.fld-field-group');\n      this.$fields = this.$fieldGroups.children('.fld-element');\n      this.$uiLibrary = this.$libraryContainer.children('.fld-ui-library');\n      this.$uiLibraryElements = this.$uiLibrary.children();\n\n      if (this.settings.readOnly) {\n        this.$fieldLibrary.attr('tabindex', '-1');\n      }\n      // Set up the layout grids\n      this.tabGrid = new Craft.Grid(this.$tabContainer, {\n        itemSelector: '.fld-tab',\n        minColWidth: 24 * 13,\n        fillMode: 'grid',\n        snapToGrid: 24,\n      });\n\n      let $tabs = this.$tabContainer.children();\n      for (let i = 0; i < $tabs.length; i++) {\n        this.initTab($($tabs[i]));\n      }\n\n      this.elementDrag = new Craft.FieldLayoutDesigner.ElementDrag(this);\n      if (!this.settings.readOnly) {\n        this.initLibraryElements(this.$libraryContainer.find('.fld-element'));\n      }\n\n      if (this.settings.customizableTabs) {\n        this.tabDrag = new Craft.FieldLayoutDesigner.TabDrag(this);\n\n        this.addListener(this.$newTabBtn, 'activate', 'addTab');\n      }\n\n      // Set up the library\n      if (this.settings.customizableUi) {\n        const $libraryPicker = this.$libraryContainer.children('.btngroup');\n        this.libraryPicker = new Craft.Listbox($libraryPicker, {\n          onChange: ($selectedOption) => {\n            const library = $selectedOption.data('library');\n            switch (library) {\n              case 'field':\n                this.$fieldLibrary.removeClass('hidden');\n                this.$uiLibrary.addClass('hidden');\n                this.$createFieldBtn.removeClass('hidden');\n                break;\n              case 'ui':\n                this.$fieldLibrary.addClass('hidden');\n                this.$uiLibrary.removeClass('hidden');\n                this.$createFieldBtn.addClass('hidden');\n                break;\n            }\n          },\n        });\n      }\n\n      this.addListener(this.$fieldSearch, 'input', () => {\n        this.updateFieldSearchResults();\n      });\n\n      this.addListener(this.$fieldSearch, 'keydown', (ev) => {\n        switch (ev.keyCode) {\n          case Garnish.ESC_KEY:\n            this.$fieldSearch.val('').trigger('input');\n            break;\n          case Garnish.RETURN_KEY:\n            // they most likely don't want to submit the form from here\n            ev.preventDefault();\n            break;\n        }\n      });\n\n      // Clear the search when the X button is clicked\n      this.addListener(this.$clearFieldSearchBtn, 'click', () => {\n        this.clearSearch();\n      });\n\n      this.refreshSelectedFields();\n\n      // Add the “New Field” button\n      this.$createFieldBtn = Craft.ui\n        .createButton({\n          label: Craft.t('app', 'New field'),\n          class: 'mt-m fullwidth add icon dashed',\n          disabled: this.settings.readOnly,\n        })\n        .appendTo(this.$libraryContainer);\n\n      this.addListener(this.$createFieldBtn, 'activate', async () => {\n        this.createField();\n      });\n\n      // initiate Card Attributes Designer\n      if (this.settings.withCardViewDesigner) {\n        this.$cvd = this.$container\n          .parents('.fld-cvd')\n          .find('.card-view-designer');\n        this.initCvd();\n      }\n    },\n\n    updateFieldSearchResults() {\n      const val = this.$fieldSearch.val().toLowerCase().replace(/['\"]/g, '');\n      if (!val) {\n        this.$fieldLibrary.find('.filtered').removeClass('filtered');\n        this.$clearFieldSearchBtn.addClass('hidden');\n        return;\n      }\n\n      this.$clearFieldSearchBtn.removeClass('hidden');\n      const $matches = this.$fields\n        .filter(`[data-keywords*=\"${val}\"]`)\n        .add(\n          this.$fieldGroups\n            .filter(`[data-name*=\"${val}\"]`)\n            .children('.fld-element')\n        )\n        .removeClass('filtered');\n      this.$fields.not($matches).addClass('filtered');\n\n      // hide any groups that don't have any results\n      for (let i = 0; i < this.$fieldGroups.length; i++) {\n        const $group = this.$fieldGroups.eq(i);\n        if ($group.find('.fld-element:not(.hidden):not(.filtered)').length) {\n          $group.removeClass('filtered');\n        } else {\n          $group.addClass('filtered');\n        }\n      }\n    },\n\n    clearSearch: function () {\n      this.$fieldSearch.val('').trigger('input');\n    },\n\n    initCvd: function () {\n      this.cvd = new Craft.FieldLayoutDesigner.CardViewDesigner(\n        this,\n        this.$cvd\n      );\n\n      // Add skip link\n      const skipLinkAnchor = this.cvd.$container.attr('id');\n\n      if (skipLinkAnchor) {\n        const $skipLink = $('<a/>', {\n          class: 'skip-link btn',\n          text: Craft.t('app', 'Skip to card view designer'),\n          href: `#${skipLinkAnchor}`,\n        });\n\n        this.cvd.$container.attr('tabindex', '-1');\n        this.$innerContainer.prepend($skipLink);\n      }\n    },\n\n    initTab: function ($tab) {\n      return new Craft.FieldLayoutDesigner.Tab(this, $tab);\n    },\n\n    removeFieldByHandle: function (attribute) {\n      this.$fields\n        .filter(`[data-attribute=\"${attribute}\"]:first`)\n        .removeClass('hidden')\n        .closest('.fld-field-group')\n        .removeClass('hidden');\n    },\n\n    addTab: function () {\n      if (!this.settings.customizableTabs) {\n        return;\n      }\n\n      let defaultValue = '';\n      if (this.tabGrid.$items.length === 0) {\n        defaultValue = Craft.t('app', 'Content');\n      }\n      const name = Craft.escapeHtml(\n        prompt(Craft.t('app', 'Give your tab a name.'), defaultValue)\n      );\n\n      if (!name) {\n        return;\n      }\n\n      const $tab = $(`\n<div class=\"fld-tab\">\n  <div class=\"tabs\">\n    <div class=\"tab sel draggable\">\n      <h3 class=\"fld-tab__name\">${name}</h3>\n    </div>\n  </div>\n  <div class=\"fld-tabcontent\">\n    <button class=\"btn add icon dashed fullwidth fld-add-btn\" type=\"button\">\n      ${Craft.t('app', 'Add')}\n    </button>\n  </div>\n</div>\n`);\n      // keep it before the resize object\n      const $lastTab = this.$tabContainer.children('.fld-tab:last');\n      if ($lastTab.length) {\n        $tab.insertAfter($lastTab);\n      } else {\n        $tab.prependTo(this.$tabContainer);\n      }\n\n      this.tabGrid.addItems($tab);\n      this.tabDrag.addItems($tab);\n\n      const tab = this.initTab($tab);\n      tab.updatePositionInConfig();\n    },\n\n    get config() {\n      return this._config;\n    },\n\n    set config(config) {\n      this._config = config;\n      this.$configInput.val(JSON.stringify(config));\n    },\n\n    updateConfig: function (callback) {\n      const config = callback(this.config);\n      if (config !== false) {\n        this.config = config;\n      }\n    },\n\n    refreshSelectedFields: function () {\n      this._$selectedFields = this.$tabContainer.find('.fld-field');\n    },\n\n    refreshLibraryFields() {\n      this.$fields = this.$fieldGroups.children('.fld-element');\n\n      for (let i = 0; i < this.$fieldGroups.length; i++) {\n        const $fieldGroup = this.$fieldGroups.eq(i);\n        const $fields = $fieldGroup.children('.fld-element');\n        $fields\n          .sort((a, b) => {\n            return $(a).data('ui-label') > $(b).data('ui-label') ? 1 : -1;\n          })\n          .appendTo($fieldGroup);\n      }\n\n      this.updateFieldSearchResults();\n    },\n\n    hasHandle: function (handle) {\n      for (let i = 0; i < this._$selectedFields.length; i++) {\n        const element = this._$selectedFields.eq(i).data('fld-element');\n        const elementHandle = element.config.handle || element.attribute;\n        if (handle === elementHandle) {\n          return true;\n        }\n      }\n\n      return false;\n    },\n\n    createField() {\n      const slideout = new Craft.CpScreenSlideout('fields/edit-field');\n\n      slideout.on('submit', async ({response}) => {\n        // add the library selector\n        const $selector = $(response.data.selectorHtml);\n        this.$fieldGroups.last().append($selector).removeClass('hidden');\n        this.refreshLibraryFields();\n        this.initLibraryElements($selector);\n\n        // add it to the active tab\n        this.addLibraryElementToActiveTab($selector);\n\n        Garnish.requestAnimationFrame(() => {\n          this.getActiveHud()?.hide();\n        });\n      });\n    },\n\n    initLibraryElements($elements) {\n      this.elementDrag.addItems($elements);\n\n      this.addListener($elements, 'activate', (ev) => {\n        // ignore if is on a dragged element\n        if (ev.currentTarget.style.visibility === 'hidden') {\n          return;\n        }\n        ev.stopPropagation();\n        ev.originalEvent.preventDefault();\n        this.addLibraryElementToActiveTab(ev.currentTarget);\n      });\n    },\n\n    cloneLibraryElementForSelection(libraryElement) {\n      // Create a new element based on that one\n      const $libraryElement = $(libraryElement);\n      const $element = $libraryElement\n        .clone()\n        .removeClass('unused')\n        .removeAttr('tabindex');\n\n      if (!Garnish.hasAttr($libraryElement, 'data-is-multi-in