his.onCancel = onCancel;\n\n      // Check the time remaining on the user’s elevated session (if any)\n      this.fetchingTimeout = true;\n\n      let data;\n\n      try {\n        const response = await Craft.sendActionRequest(\n          'POST',\n          'users/get-elevated-session-timeout'\n        );\n        data = response.data;\n      } finally {\n        this.fetchingTimeout = false;\n      }\n\n      if (\n        data.timeout === false ||\n        data.timeout >=\n          (minSafeElevatedSessionTimeout ||\n            Craft.ElevatedSessionManager.minSafeElevatedSessionTimeout)\n      ) {\n        this.onSuccess();\n      } else {\n        // Show the login modal\n        this.showLoginModal();\n      }\n    },\n\n    /**\n     * Shows the login modal.\n     */\n    async showLoginModal() {\n      if (this.showingLoginModal) {\n        return;\n      }\n\n      this.showingLoginModal = true;\n\n      if (this.loginModal) {\n        this.loginModal.destroy();\n      }\n\n      const {data} = await Craft.sendActionRequest(\n        'POST',\n        'users/login-modal',\n        {\n          data: {\n            email: Craft.userEmail,\n            forElevatedSession: true,\n          },\n        }\n      );\n      const $container = $(data.html);\n\n      this.loginModal = new Garnish.Modal($container, {\n        closeOtherModals: false,\n        shadeClass: 'modal-shade dark login-modal-shade',\n        onFadeIn: async () => {\n          Craft.initUiElements($container);\n          const $loginForm = $container.find('craft-login-form');\n          $loginForm.on('craft:login:success', (event) => {\n            event.preventDefault();\n            this.success = true;\n            this.loginModal.hide();\n          });\n        },\n        onFadeOut: () => {\n          this.loginModal.destroy();\n          this.loginModal = null;\n        },\n        onHide: () => {\n          this.showingLoginModal = false;\n          if (this.success) {\n            this.onSuccess();\n          } else if (this.onCancel) {\n            this.onCancel();\n          }\n        },\n      });\n    },\n  },\n  {\n    minSafeElevatedSessionTimeout: 5,\n  }\n);\n\n// Instantiate it\nCraft.elevatedSessionManager = new Craft.ElevatedSessionManager();\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Delete User Modal\n *\n * @deprecated in 5.10.0\n */\nCraft.DeleteUserModal = Garnish.Modal.extend(\n  {\n    id: null,\n    userId: null,\n\n    $deleteActionRadios: null,\n    $deleteSubmitBtn: null,\n\n    userSelect: null,\n    _deleting: false,\n\n    init: function (userId, settings) {\n      this.id = Math.floor(Math.random() * 1000000000);\n      this.userId = userId;\n      settings = $.extend(Craft.DeleteUserModal.defaults, settings);\n\n      let $form = $(\n        '<form class=\"modal fitted deleteusermodal\" method=\"post\" accept-charset=\"UTF-8\">' +\n          Craft.getCsrfInput() +\n          '<input type=\"hidden\" name=\"action\" value=\"users/delete-user\"/>' +\n          (!Array.isArray(this.userId)\n            ? '<input type=\"hidden\" name=\"userId\" value=\"' + this.userId + '\"/>'\n            : '') +\n          (settings.redirect\n            ? '<input type=\"hidden\" name=\"redirect\" value=\"' +\n              settings.redirect +\n              '\"/>'\n            : '') +\n          '</form>'\n      ).appendTo(Garnish.$bod);\n      let $body = $(\n        '<div class=\"body\">' +\n          '<div class=\"content-summary\">' +\n          '<p>' +\n          Craft.t('app', 'What do you want to do with their content?') +\n          '</p>' +\n          '<ul class=\"bullets\"></ul>' +\n          '</div>' +\n          '<div class=\"options\">' +\n          '<label><input type=\"radio\" name=\"contentAction\" value=\"transfer\"/> ' +\n          Craft.t('app', 'Transfer it to:') +\n          '</label>' +\n          '<div id=\"transferselect' +\n          this.id +\n          '\" class=\"elementselect\">' +\n          '<ul class=\"elements\"></ul>' +\n          '<button type=\"button\" class=\"btn add icon dashed\">' +\n          Craft.t('app', 'Choose a user') +\n          '</button>' +\n          '</div>' +\n          '</div>' +\n          '<div>' +\n          '<label class=\"error\"><input type=\"radio\" name=\"contentAction\" value=\"delete\"/> ' +\n          Craft.t('app', 'Delete their content') +\n          '</label>' +\n          '</div>' +\n          '</div>'\n      ).appendTo($form);\n      let $buttons = $('<div class=\"buttons right\"/>').appendTo($body);\n      let $cancelBtn = $('<button/>', {\n        type: 'button',\n        class: 'btn',\n        text: Craft.t('app', 'Cancel'),\n      }).appendTo($buttons);\n\n      const $contentSummary = $body.find('.content-summary');\n      if (settings.contentSummary.length) {\n        for (let i = 0; i < settings.contentSummary.length; i++) {\n          $contentSummary\n            .find('ul')\n            .append($('<li/>', {text: settings.contentSummary[i]}));\n        }\n      } else {\n        $contentSummary.find('ul').remove();\n      }\n\n      this.$deleteActionRadios = $body.find('input[type=radio]');\n      this.$deleteSubmitBtn = Craft.ui\n        .createSubmitButton({\n          class: 'disabled',\n          label: this._submitBtnLabel(false),\n          spinner: true,\n        })\n        .appendTo($buttons);\n\n      var idParam;\n\n      if (Array.isArray(this.userId)) {\n        idParam = ['and'];\n\n        for (let i = 0; i < this.userId.length; i++) {\n          idParam.push('not ' + this.userId[i]);\n        }\n      } else {\n        idParam = 'not ' + this.userId;\n      }\n\n      this.userSelect = new Craft.BaseElementSelectInput({\n        id: 'transferselect' + this.id,\n        name: 'transferContentTo',\n        elementType: 'CraftCms\\\\Cms\\\\User\\\\Elements\\\\User',\n        criteria: {\n          id: idParam,\n        },\n        limit: 1,\n        modalSettings: {\n          closeOtherModals: false,\n        },\n        onSelectElements: () => {\n          this.updateSizeAndPosition();\n\n          if (!this.$deleteActionRadios.first().prop('checked')) {\n            this.$deleteActionRadios.first().trigger('click');\n          } else {\n            this.validateDeleteInputs();\n          }\n        },\n        onRemoveElements: this.validateDeleteInputs.bind(this),\n        selectable: false,\n        editable: false,\n      });\n\n      this.addListener($cancelBtn, 'click', 'hide');\n\n      this.addListener(\n        this.$deleteActionRadios,\n        'change',\n        'validateDeleteInputs'\n      );\n      this.addListener($form, 'submit', 'handleSubmit');\n\n      this.base($form, settings);\n    },\n\n    _submitBtnLabel: function (withContent) {\n      let message = withContent\n        ? 'Delete {num, plural, =1{user} other{users}} and content'\n        : 'Delete {num, plural, =1{user} other{users}}';\n\n      return Craft.t('app', message, {\n        num: Array.isArray(this.userId) ? this.userId.length : 1,\n      });\n    },\n\n    validateDeleteInputs: function () {\n      var validates = false;\n\n      if (this.$deleteActionRadios.eq(1).prop('checked')) {\n        validates = true;\n        this.$deleteSubmitBtn.find('.label').text(this._submitBtnLabel(true));\n      } else {\n        this.$deleteSubmitBtn.find('.label').text(this._submitBtnLabel(false));\n        if (this.$deleteActionRadios.eq(0).prop('checked')) {\n          validates = !!this.userSelect.totalSelected;\n        }\n      }\n\n      this.updateSizeAndPosition();\n\n      if (validates) {\n        this.$deleteSubmitBtn.removeClass('disabled');\n      } else {\n        this.$deleteSubmitBtn.addClass('disabled');\n      }\n\n      return validates;\n    },\n\n    handleSubmit: function (ev) {\n      if (this._deleting || !this.validateDeleteInputs()) {\n        ev.preventDefault();\n        return;\n      }\n\n      this.$deleteSubmitBtn.addClass('loading');\n      this.disable();\n      this.userSelect.disable();\n      this._deleting = true;\n\n      // Let the onSubmit callback prevent the form from getting submitted\n      try {\n        if (this.settings.onSubmit() === false) {\n          ev.preventDefault();\n        }\n      } catch (e) {\n        ev.preventDefault();\n        this.$deleteSubmitBtn.removeClass('loading');\n        throw e;\n      }\n    },\n\n    onFadeIn: function () {\n      // Auto-focus the first radio\n      if (!Garnish.isMobileBrowser(true)) {\n        this.$deleteActionRadios.first().focus();\n      }\n\n      this.base();\n    },\n  },\n  {\n    defaults: {\n      contentSummary: [],\n      onSubmit: $.noop,\n      redirect: null,\n    },\n  }\n);\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Entry select input\n */\nCraft.EntrySelectInput = Craft.BaseElementSelectInput.extend({\n  get section() {\n    if (!this.settings.sectionId) {\n      return null;\n    }\n    return Craft.publishableSections.find(\n      (s) => s.id === this.settings.sectionId\n    );\n  },\n\n  canCreateElements: function () {\n    return !!this.section;\n  },\n\n  createElement: async function (title) {\n    const response = await Craft.sendActionRequest('POST', 'entries/create', {\n      data: {\n        siteId: this.settings.criteria.siteId,\n        section: this.section.handle,\n        authorId: Craft.userId,\n        title,\n      },\n    });\n\n    const entry = response.data.entry;\n\n    try {\n      await this.showElementEditor(entry);\n    } catch (e) {\n      return null;\n    }\n\n    return entry.id;\n  },\n\n  showElementEditor: function (entry) {\n    return new Promise((resolve, reject) => {\n      const slideout = Craft.createElementEditor(\n        'CraftCms\\\\Cms\\\\Entry\\\\Elements\\\\Entry',\n        {\n          siteId: this.settings.criteria.siteId,\n          elementId: entry.id,\n          draftId: entry.draftId,\n          params: {\n            fresh: 1,\n          },\n        }\n      );\n\n      let submitted = false;\n\n      slideout.on('submit', () => {\n        submitted = true;\n        resolve();\n      });\n\n      slideout.on('close', () => {\n        if (!submitted) {\n          reject();\n        }\n      });\n    });\n  },\n});\n","/** global: Craft */\n/** global: Garnish */\n/** global: $ */\n/** global: jQuery */\n\n/**\n * Base component select input\n */\nCraft.EntryTypeSelectInput = Craft.ComponentSelectInput.extend(\n  {\n    init: function (settings = {}) {\n      this.base(\n        Object.assign({}, Craft.EntryTypeSelectInput.defaults, settings)\n      );\n    },\n\n    addComponentInternal: function ($component) {\n      if (this.settings.allowOverrides) {\n        const disclosureMenu = this.getDisclosureMenu($component);\n        const $editBtn = disclosureMenu.$container.find('[data-edit-action]');\n        if ($editBtn.length) {\n          disclosureMenu.hideItem($editBtn[0]);\n        }\n        if (this.settings.addItemsToActionMenus) {\n          Craft.addActionsToChip(\n            $component,\n            [\n              {\n                icon: async () => await Craft.ui.icon('gear'),\n                label: Craft.t('app', 'Settings'),\n                onActivate: (el) => {\n                  $(el)\n                    .closest('.menu')\n                    .data('disclosureMenu')\n                    .$trigger.closest('.componentselect')\n                    .data('componentSelect')\n                    .createSettings($component);\n                },\n              },\n            ],\n            true\n          );\n        }\n      }\n\n      this.base($component);\n    },\n\n    createSettings: async function ($component) {\n      let data;\n      try {\n        const response = await Craft.sendActionRequest(\n          'POST',\n          'entry-types/render-override-settings',\n          {\n            data: JSON.parse($component.find('input').val()),\n          }\n        );\n        data = response.data;\n      } catch (e) {\n        Craft.cp.displayError(e?.response?.data?.message);\n        throw e;\n      }\n\n      const settingsNamespace = data.namespace;\n      const slideout = await this.createSlideout(data);\n\n      slideout.$container.on('submit', (ev) => {\n        ev.preventDefault();\n        this.applySettings($component, slideout, settingsNamespace);\n      });\n      slideout.on('close', () => {\n        slideout.destroy();\n      });\n\n      this.trigger('createSettings');\n    },\n\n    async createSlideout(data) {\n      const $body = $('<div/>', {class: 'entry-type-override-settings-body'});\n      $('<div/>', {class: 'fields', html: data.settingsHtml}).appendTo($body);\n      const $footer = $('<div/>', {\n        class: 'entry-type-override-settings-footer',\n      });\n      $('<div/>', {class: 'flex-grow'}).appendTo($footer);\n      const $cancelBtn = Craft.ui\n        .createButton({\n          label: Craft.t('app', 'Close'),\n          spinner: true,\n        })\n        .appendTo($footer);\n      Craft.ui\n        .createSubmitButton({\n          class: 'secondary',\n          label: Craft.t('app', 'Apply'),\n          spinner: true,\n        })\n        .appendTo($footer);\n      const $contents = $body.add($footer);\n\n      const slideout = new Craft.Slideout($contents, {\n        containerElement: 'form',\n        containerAttributes: {\n          action: '',\n          method: 'post',\n          novalidate: '',\n          class: 'entry-type-override-settings',\n        },\n      });\n      slideout.on('open', () => {\n        // Hold off a sec until it's positioned...\n        Garnish.requestAnimationFrame(() => {\n          // Focus on the first text input\n          slideout.$container.find('.text:first').focus();\n        });\n      });\n\n      $cancelBtn.on('click', () => {\n        slideout.close();\n      });\n\n      if (data.headHtml) {\n        await Craft.appendHeadHtml(data.headHtml);\n      }\n      if (data.bodyHtml) {\n        await Craft.appendBodyHtml(data.bodyHtml);\n      }\n\n      Craft.initUiElements(slideout.$container);\n\n      return slideout;\n    },\n\n    async applySettings($component, slideout, settingsNamespace) {\n      // update the UI\n      let $submitBtn = slideout.$container\n        .find('button[type=submit]')\n        .addClass('loading');\n\n      // clear errors\n      slideout.$container.find('.field.has-errors').each((i, field) => {\n        const $field = $(field);\n        $field.removeClass('has-errors');\n        $field.children('.input').removeClass('errors prevalidate');\n        $field.children('ul.errors').remove();\n      });\n\n      try {\n        let data;\n\n        try {\n          const response = await Craft.sendActionRequest(\n            'POST',\n            'entry-types/apply-override-settings',\n            {\n              data: {\n                id: $component.data('id'),\n                settingsNamespace,\n                settings: slideout.$container.serialize(),\n              },\n            }\n          );\n          data = response.data;\n        } catch (e) {\n          let errors = e?.response?.data?.errors;\n          if (errors) {\n            Object.entries(errors).forEach(([name, fieldErrors]) => {\n              const $field = slideout.$container.find(\n                `[data-error-key=\"${name}\"]`\n              );\n              if ($field.length) {\n                Craft.ui.addErrorsToField($field, fieldErrors);\n              }\n            });\n          }\n\n          Craft.cp.displayError(e?.response?.data?.message);\n          throw e;\n        }\n\n        const $newContainer = $(data.chipHtml);\n        $component\n          .find('.chip-label')\n          .replaceWith($newContainer.find('.chip-label'));\n\n        // Update the input with the new config, but keep the old group value around\n        const $input = $component.find('input');\n        const config = {...data.config};\n        const group = JSON.parse($input.val()).group;\n        if (group) {\n          config.group = group;\n        }\n        $input.val(JSON.stringify(config));\n\n        Craft.initUiElements($component);\n\n        this.trigger('applySettings');\n\n        slideout.close();\n        slideout.destroy();\n      } finally {\n        $submitBtn.removeClass('loading');\n      }\n    },\n\n    renderSettings: function (id) {\n      return Object.assign(this.base(), {\n        inputValue: this.settings.allowOverrides ? JSON.stringify({id}) : null,\n      });\n    },\n  },\n  {\n    defaults: {\n      allowOverrides: false,\n    },\n  }\n);\n","/** global: Craft */\n/** global: Garnish */\n/**\n * Element Select input\n */\nCraft.BaseElementSelectInput = Garnish.Base.extend(\n  {\n    elementSelect: null,\n    elementSort: null,\n    modal: null,\n    elementEditor: null,\n    modalFirstOpen: true,\n\n    $container: null,\n    $form: null,\n    $elementsContainer: null,\n    $elements: null,\n    $addElementBtn: null,\n    $spinner: null,\n\n    searchTimeout: null,\n    searchMenu: null,\n    $searchContainer: null,\n    $searchInput: null,\n    $searchSpinner: null,\n    _ignoreSearchBlur: false,\n\n    _initialized: false,\n    _$replaceElement: null,\n\n    get thumbLoader() {\n      console.warn(\n        'Craft.BaseElementSelectInput::thumbLoader is deprecated. Craft.cp.elementThumbLoader should be used instead.'\n      );\n      return Craft.cp.elementThumbLoader;\n    },\n\n    init: function (settings) {\n      // Normalize the settings and set them\n      // ---------------------------------------------------------------------\n\n      // Are they still passing in a bunch of arguments?\n      if (!$.isPlainObject(settings)) {\n        // Loop through all of the old arguments and apply them to the settings\n        var normalizedSettings = {},\n          args = [\n            'id',\n            'name',\n            'elementType',\n            'sources',\n            'criteria',\n            'sourceElementId',\n            'limit',\n            'modalStorageKey',\n            'fieldId',\n          ];\n\n        for (var i = 0; i < args.length; i++) {\n          if (typeof arguments[i] !== 'undefined') {\n            normalizedSettings[args[i]] = arguments[i];\n          } else {\n            break;\n          }\n        }\n\n        settings = normalizedSettings;\n      }\n\n      this.setSettings(settings, Craft.BaseElementSelectInput.defaults);\n\n      // Apply the storage key prefix\n      if (this.settings.modalStorageKey) {\n        this.modalStorageKey =\n          'BaseElementSelectInput.' + this.settings.modalStorageKey;\n      }\n\n      // No reason for this to be sortable if we're only allowing 1 selection\n      if (this.settings.limit == 1 || this.settings.maintainHierarchy) {\n        this.settings.sortable = false;\n      }\n\n      this.$container = this.getContainer();\n      this.$form = this.$container.closest('form');\n\n      // Store a reference to this class\n      this.$container.data('elementSelect', this);\n\n      this.$elementsContainer = this.getElementsContainer();\n      this.$addElementBtn = this.getAddElementsBtn();\n      this.$spinner = this.getSpinner();\n      this.$searchContainer = this.getSearchContainer();\n      this.$searchInput = this.getSearchInput();\n      this.$searchSpinner = this.getSearchSpinner();\n\n      this.initElementSelect();\n      this.initElementSort();\n      this.initSearch();\n      this.resetElements();\n\n      if (this.$addElementBtn.length) {\n        this.addListener(this.$addElementBtn, 'activate', 'showModal');\n      }\n\n      Garnish.requestAnimationFrame(() => {\n        this._initialized = true;\n      });\n\n      if (this.elementSelect) {\n        this.addListener(Garnish.$win, 'mousedown', (ev) => {\n          if (\n            !this.$container.is(ev.target) &&\n            !this.$container.find(ev.target).length &&\n            !$(ev.target).closest('.menu').length\n          ) {\n            this.elementSelect.deselectAll();\n          }\n        });\n      }\n\n      setTimeout(() => {\n        this.elementEditor = this.$container\n          .closest('form')\n          .data('elementEditor');\n      }, 100);\n    },\n\n    get totalSelected() {\n      return this.$elements.length;\n    },\n\n    getContainer: function () {\n      return $('#' + this.settings.id);\n    },\n\n    getElementsContainer: function () {\n      return this.$container.children('.elements');\n    },\n\n    getElements: function () {\n      if (this.$elementsContainer.hasClass('structure')) {\n        return this.$elementsContainer.find('> li .row .element');\n      } else {\n        return this.$elementsContainer.find('> li > .element');\n      }\n    },\n\n    getSearchContainer: function () {\n      return this.$container.find('.elementselect__search-input-wrapper');\n    },\n\n    getSearchInput: function () {\n      return this.$searchContainer.find('input');\n    },\n\n    getSearchSpinner: function () {\n      return this.$searchContainer.find('.spinner');\n    },\n\n    getAddElementsBtn: function () {\n      return this.$container.find('.btn.add:first');\n    },\n\n    getSpinner: function () {\n      return this.$container.find('.spinner');\n    },\n\n    initElementSelect: function () {\n      if (this.settings.selectable) {\n        this.elementSelect = new Garnish.Select(this.elementSelectSettings());\n      }\n    },\n\n    elementSelectSettings() {\n      return {\n        multi: this.settings.sortable,\n        filter: (target) => {\n          return !$(target).closest('a[href],button,[role=button]').length;\n        },\n        // prevent keyboard focus since element selection is only needed for drag-n-drop\n        makeFocusable: false,\n      };\n    },\n\n    initElementSort: function () {\n      // hide the diamond icon (for drag sorting) if the device doesn't have mouse events\n      if (!Craft.hasMousePointerEvents()) {\n        $(\n          '.element > .chip-content > .chip-actions > .move-btn, .element > .card-titlebar > .card-actions-container > .card-actions > .move-btn'\n        ).hide();\n      }\n\n      // init drag-sorting if device has mouse events\n      if (this.settings.sortable && Craft.hasMousePointerEvents()) {\n        this.elementSort = new Garnish.DragSort({\n          container: this.$elementsContainer,\n          filter: this.settings.selectable\n            ? () => {\n                // Only return all the selected items if the target item is selected\n                if (\n                  this.elementSort.$targetItem\n                    .children('.element')\n                    .hasClass('sel')\n                ) {\n                  return this.elementSelect.getSelectedItems().parent('li');\n                } else {\n                  return this.elementSort.$targetItem;\n                }\n              }\n            : null,\n          ignoreHandleSelector: '.delete',\n          handle: (() => {\n            switch (this.settings.viewMode) {\n              case 'list':\n              case 'list-inline':\n              case 'thumbs':\n              case 'large':\n                return '> .element > .chip-content > .chip-actions > .move-btn';\n              case 'cards':\n                return '> .element > .card-titlebar > .card-actions-container > .card-actions > .move-btn';\n              default:\n                return null;\n            }\n          })(),\n          axis: this.getElementSortAxis(),\n          collapseDraggees: true,\n          magnetStrength: 4,\n          helperLagBase: 1.5,\n          onBeforeDragStart: () => {\n            this.elementEditor?.pause();\n\n            // Disable all craft-element-labels so connectedCallback()\n            // doesn't get fired constantly during drag\n            this.$elementsContainer\n              .find('craft-element-label')\n              .attr('disabled', true);\n          },\n          onDragStop: () => {\n            this.elementEditor?.resume();\n\n            // Put things back where we found them.\n            this.$elementsContainer\n              .find('craft-element-label')\n              .removeAttr('disabled');\n          },\n          onSortChange: () => {\n            this.onSortChange();\n          },\n        });\n      }\n    },\n\n    getElementSortAxis: function () {\n      if (\n        this.settings.viewMode === 'list' &&\n        !this.getElementsContainer().hasClass('inline-chips')\n      ) {\n        return 'y';\n      }\n      return null;\n    },\n\n    canAddMoreElements: function () {\n      return (\n        this.settings.allowAdd &&\n        (!this.settings.limit || this.$elements.length < this.settings.limit)\n      );\n    },\n\n    updateAddElementsBtn: function () {\n      if (this.canAddMoreElements()) {\n        this.enableAddElementsBtn();\n      } else {\n        this.disableAddElementsBtn();\n      }\n    },\n\n    enableAddElementsBtn: function () {\n      if (this.settings.allowAdd && this.$addElementBtn.length) {\n        this.$addElementBtn.removeClass('hidden');\n        this.$searchContainer.removeClass('hidden');\n      }\n\n      this.updateButtonContainer();\n    },\n\n    disableAddElementsBtn: function () {\n      if (this.$addElementBtn.length) {\n        this.$addElementBtn.addClass('hidden');\n        this.$searchContainer.addClass('hidden');\n      }\n\n      this.updateButtonContainer();\n    },\n\n    showSpinner: function () {\n      if (this.$spinner) {\n        this.$spinner.removeClass('hidden');\n      }\n\n      this.updateButtonContainer();\n    },\n\n    hideSpinner: function () {\n      if (this.$spinner) {\n        this.$spinner.addClass('hidden');\n      }\n\n      this.updateButtonContainer();\n    },\n\n    updateButtonContainer: function () {\n      const $container =\n        this.$addElementBtn.length && this.$addElementBtn.parent('.flex');\n      if ($container?.length) {\n        if ($container.children(':not(.hidden)').length) {\n          $container.removeClass('hidden');\n        } else {\n          $container.addClass('hidden');\n        }\n      }\n    },\n\n    getNextLogicalFocusElement: function () {\n      let $focusTarget;\n      if (!this.canAddMoreElements()) {\n        return this.getLastActionBtn();\n      }\n\n      // If can add more elements, focus on search input or add button\n      if (\n        this.$searchContainer.length &&\n        !this.$searchContainer.hasClass('hidden')\n      ) {\n        return this.$searchInput;\n      }\n\n      if (\n        this.$addElementBtn.length &&\n        !this.$addElementBtn.hasClass('hidden')\n      ) {\n        return this.$addElementBtn;\n      }\n\n      // Focus on the container if neither of those are available\n      return this.$container.attr('tabindex', '-1');\n    },\n\n    focusNextLogicalElement: function () {\n      const $focusTarget = this.getNextLogicalFocusElement();\n\n      if ($focusTarget?.length) {\n        $focusTarget.focus();\n      } else {\n        console.warn('No logical element to focus on.');\n      }\n    },\n\n    /** @deprecated */\n    focusLastRemoveBtn: function () {\n      this.focusLastActionBtn();\n    },\n\n    getLastActionBtn: function () {\n      return this.$container.find('.action-btn').last();\n    },\n\n    focusLastActionBtn: function () {\n      this.getLastActionBtn().focus();\n    },\n\n    resetElements: function () {\n      if (this.$elements !== null) {\n        this.removeElements(this.$elements);\n      } else {\n        this.$elements = $();\n      }\n\n      this.addElements(this.getElements());\n    },\n\n    addElements: function ($elements) {\n      // add the action triggers\n      for (let i = 0; i < $elements.length; i++) {\n        const $element = $elements.eq(i);\n        const actions = this.defineElementActions($element);\n\n        if (actions.length) {\n          Craft.addActionsToChip($element, actions);\n\n          const disclosureMenu =\n            // Old div.chip / card structure\n            $element\n              .find(\n                '> .chip-content > .chip-actions .action-btn, > .card-titlebar > .card-actions-container > .card-actions .action-btn'\n              )\n              .data('disclosureMenu') ||\n            // New craft-chip structure: [slot=\"suffix\"] with a disclosure trigger\n            $element\n              .children('[slot=\"suffix\"]')\n              .find('[data-disclosure-trigger]')\n              .first()\n              .data('disclosureMenu');\n          const moveForwardBtn = disclosureMenu.$container.find(\n            '[data-move-forward]'\n          )[0];\n          const moveBackwardBtn = disclosureMenu.$container.find(\n            '[data-move-backward]'\n          )[0];\n\n          disclosureMenu.on('show', () => {\n            const $li = $element.parent();\n            const $prev = $li.prev();\n            const $next = $li.next();\n\n            if (moveForwardBtn) {\n              disclosureMenu.toggleItem(moveForwardBtn, $prev.length);\n            }\n            if (moveBackwardBtn) {\n              disclosureMenu.toggleItem(moveBackwardBtn, $next.length);\n            }\n          });\n        }\n\n        // only add the diamond icon (for drag-sorting) if device has mouse events\n        if (this.settings.sortable && Craft.hasMousePointerEvents()) {\n          Craft.ui\n            .createButton({\n              class: 'chromeless small move-btn',\n              icon: 'move',\n            })\n            .attr({\n              title: Craft.t('app', 'Reorder'),\n              'aria-label': Craft.t('app', 'Reorder'),\n              'aria-describedby': $element.find('.label').attr('id'),\n            })\n            .appendTo(\n              $element.find(\n                '> .chip-content > .chip-actions, > .card-titlebar > .card-actions-container > .card-actions'\n              )\n            );\n        }\n      }\n\n      Craft.cp.elementThumbLoader.load($elements);\n\n      if (this.settings.selectable) {\n        this.elementSelect.addItems($elements);\n      }\n\n      if (this.settings.sortable) {\n        this.elementSort?.addItems($elements.parent('li'));\n      }\n\n      if (this.settings.editable) {\n        this._handleShowElementEditor = (ev) => {\n          // don't open the edit slideout if we are tapholding to drag\n          if (ev.type === 'taphold' && ev.target.nodeName === 'BUTTON') {\n            return;\n          }\n\n          var $element = $(ev.currentTarget);\n          if (\n            Garnish.hasAttr($element, 'data-editable') &&\n            !$element.hasClass('disabled') &&\n            !$element.hasClass('loading')\n          ) {\n            this.createElementEditor($element);\n          }\n        };\n\n        this.addListener($elements, 'dblclick', this._handleShowElementEditor);\n\n        if ($.isTouchCapable()) {\n          this.addListener($elements, 'taphold', this._handleShowElementEditor);\n        }\n      }\n\n      $elements.on('keydown', (ev) => {\n        if ([Garnish.BACKSPACE_KEY, Garnish.DELETE_KEY].includes(ev.keyCode)) {\n          ev.stopPropagation();\n          ev.preventDefault();\n          const $elements = this.elementSelect.getSelectedItems();\n          for (let i = 0; i < $elements.length; i++) {\n            this.removeElement($elements.eq(i));\n          }\n        }\n      });\n\n      this.$elements = this.$elements.add($elements);\n\n      this.updateAddElementsBtn();\n      this.onAddElements();\n      this.onSortChange();\n    },\n\n    defineElementActions: function ($element) {\n      const actions = [];\n\n      if (this.settings.sortable) {\n        const axis = this.getElementSortAxis();\n        actions.push({\n          icon: async () =>\n            await Craft.ui.icon(\n              axis === 'y'\n                ? 'arrow-up'\n                : Craft.orientation === 'ltr'\n                  ? 'arrow-left'\n                  : 'arrow-right'\n            ),\n          label:\n            axis === 'y'\n              ? Craft.t('app', 'Move up')\n              : Craft.t('app', 'Move forward'),\n          callback: () => {\n            this.moveElementForward($element);\n          },\n          attributes: {\n            'data-move-forward': true,\n          },\n        });\n        actions.push({\n          icon: async () =>\n            await Craft.ui.icon(\n              axis === 'y'\n                ? 'arrow-down'\n                : Craft.orientation === 'ltr'\n                  ? 'arrow-right'\n                  : 'arrow-left'\n            ),\n          label:\n            axis === 'y'\n              ? Craft.t('app', 'Move down')\n              : Craft.t('app', 'Move backward'),\n          callback: () => {\n            this.moveElementBackward($element);\n          },\n          attributes: {\n            'data-move-backward': true,\n          },\n        });\n      }\n\n      if (this.settings.allowRemove) {\n        if (this.settings.elementType) {\n          actions.push({\n            icon: async () => await Craft.ui.icon('arrows-rotate'),\n            label: Craft.t('app', 'Replace'),\n            callback: () => {\n              this._$replaceElement = $element;\n              this.showModal();\n            },\n          });\n        }\n\n        actions.push({\n          icon: async () => await Craft.ui.icon('remove'),\n          label: Craft.t('app', 'Remove'),\n          callback: () => {\n            // If the element is selected, remove *all* the selected elements\n            if (this.elementSelect?.isSelected($element)) {\n              this.removeElement(this.elementSelect.getSelectedItems());\n            } else {\n              this.removeElement($element);\n            }\n          },\n        });\n      }\n\n      return actions;\n    },\n\n    createElementEditor: function ($element, settings) {\n      settings = Object.assign(\n        {\n          elementSelectInput: this,\n          prevalidate: this.settings.prevalidate,\n        },\n        settings\n      );\n\n      return Craft.createElementEditor(\n        this.settings.elementType,\n        $element,\n        settings\n      );\n    },\n\n    replaceElement: function (elementId, replacementId) {\n      return new Promise((resolve, reject) => {\n        const $existing = this.$elements.filter(`[data-id=\"${elementId}\"]`);\n\n        if (!$existing.length) {\n          reject(`No element selected with an ID of ${elementId}.`);\n          return;\n        }\n\n        this.showSpinner();\n\n        Craft.sendActionRequest('POST', 'app/render-elements', {\n          data: {\n            elements: [\n              {\n                type: this.settings.elementType,\n                id: replacementId,\n                siteId: this.settings.criteria.siteId,\n                instances: [\n                  {\n                    context: 'field',\n                    ui: ['list', 'list-inline', 'thumbs', 'large'].includes(\n                      this.settings.viewMode\n                    )\n                      ? 'chip'\n                      : 'card',\n                    size: ['thumbs', 'large'].includes(this.settings.viewMode)\n                      ? 'large'\n                      : 'small',\n                    showActionMenu: this.settings.showActionMenu,\n                  },\n                ],\n              },\n            ],\n          },\n        })\n          .then(async ({data}) => {\n            this.removeElement($existing);\n            const elementInfo = Craft.getElementInfo(\n              data.elements[replacementId][0]\n            );\n            this.selectElements([elementInfo]).then(resolve);\n            await Craft.appendHeadHtml(data.headHtml);\n            await Craft.appendBodyHtml(data.bodyHtml);\n          })\n          .catch((e) => {\n            Craft.cp.displayError(e?.response?.data?.message);\n            reject(e?.response?.data?.message);\n          })\n          .finally(() => {\n            this.hideSpinner();\n          });\n      });\n    },\n\n    onSortChange() {\n      this.elementSelect?.resetItemOrder();\n      this.$elements = $().add(this.$elements);\n    },\n\n    moveElementForward($element) {\n      const $li = $element.closest('li');\n      const $prev = $li.prev();\n      if ($prev.length) {\n        $li.insertBefore($prev);\n        this.onSortChange();\n      }\n    },\n\n    moveElementBackward($element) {\n      const $li = $element.closest('li');\n      const $next = $li.next();\n      if ($next.length) {\n        $li.insertAfter($next);\n        this.onSortChange();\n      }\n    },\n\n    /**\n     * Removes elements from the field value, without actually removing their DOM nodes.\n     * @param $elements\n     */\n    removeElements: function ($elements) {\n      if (this.settings.selectable) {\n        this.elementSelect.removeItems($elements);\n      }\n\n      if (this.modal) {\n        var ids = [];\n\n        for (var i = 0; i < $elements.length; i++) {\n          var id = $elements.eq(i).data('id');\n\n          if (id) {\n            ids.push(id);\n          }\n        }\n\n        if (ids.length) {\n          this.modal.elementIndex.enableElementsById(ids);\n        }\n      }\n\n      // Disable the hidden input in case the form is submitted before this element gets removed from the DOM\n      $elements.children('input').prop('disabled', true);\n\n      // Move the focus to the next element in the list, if there is one\n      let $nextElement, $prevElement;\n      if (this.settings.selectable) {\n        const lastElementIndex = this.$elements.index($elements.last());\n        $nextElement = this.$elements.eq(lastElementIndex + 1);\n        $prevElement =\n          lastElementIndex - 1 >= 0\n            ? this.$elements.eq(lastElementIndex - 1)\n            : null;\n      }\n      if ($nextElement?.length || $prevElement?.length) {\n        let $target;\n        if ($nextElement?.length) {\n          $target = this.getElementFocusTarget($nextElement);\n        } else {\n          $target = this.getElementFocusTarget($prevElement);\n        }\n        $target?.focus();\n      } else {\n        setTimeout(() => {\n          this.focusNextLogicalElement();\n        }, 200);\n      }\n\n      this.$elements = this.$elements.not($elements);\n      this.updateAddElementsBtn();\n      this.onSortChange();\n      this.onRemoveElements();\n    },\n\n    /**\n     * Determine which part of an element should receive focus\n     * @param $element\n     */\n    getElementFocusTarget: function ($element) {\n      if ($element.is(':focusable')) {\n        return $element;\n      } else if (Garnish.firstFocusableElement($element).length) {\n        return Garnish.firstFocusableElement($element);\n      } else {\n        return null;\n      }\n    },\n\n    /**\n     * Completely removes an element(s) from the UI and field value.\n     * @param $elements\n     */\n    removeElement: function ($elements) {\n      if (this.settings.maintainHierarchy) {\n        // Find any descendants the elements have\n        let $descendants = $();\n        for (let i = 0; i < $elements.length; i++) {\n          $descendants = $descendants.add(\n            $elements.eq(i).parent().siblings('ul').find('.element')\n          );\n        }\n        $elements = $elements.add($descendants);\n      }\n\n      // Remove any inputs from the form data\n      $('[name]', $elements).removeAttr('name');\n\n      // Remove our record of them all at once\n      this.removeElements($elements);\n\n      if (this.settings.maintainHierarchy) {\n        for (let i = 0; i < $elements.length; i++) {\n          this._animateStructureElementAway($elements, i);\n        }\n      } else {\n        for (let i = 0; i < $elements.length; i++) {\n          const $element = $elements.eq(i);\n          const $li = $element.parent('li');\n          this.animateElementAway($element);\n          $li.remove();\n        }\n      }\n    },\n\n    animateElementAway: async function ($element, callback) {\n      const offset = $element.offset();\n      const width = $element.width();\n\n      $element.appendTo(Garnish.$bod).css({\n        'z-index': 0,\n        position: 'absolute',\n        top: offset.top,\n        left: offset.left,\n        maxWidth: width + 'px',\n      });\n\n      await Craft.animate($element, {\n        opacity: -1,\n        left: offset.left + 100 * (Craft.orientation === 'ltr' ? -1 : 1),\n      });\n\n      $element.remove();\n      if (callback) {\n        callback();\n      }\n    },\n\n    showModal: function () {\n      // Make sure we haven't reached the limit\n      if (!this._$replaceElement && !this.canAddMoreElements()) {\n        return;\n      }\n\n      if (!this.modal) {\n        this.modal = this.createModal();\n        this.modalFirstOpen = false;\n      } else {\n        this.modal.show();\n      }\n    },\n\n    createModal: function () {\n      return Craft.createElementSelectorModal(\n        this.settings.elementType,\n        this.getModalSettings()\n      );\n    },\n\n    getModalSettings: function () {\n      const settings = $.extend(\n        {\n          closeOtherModals: false,\n          storageKey: this.modalStorageKey,\n          sources: this.settings.sources,\n          condition: this.settings.condition,\n          referenceElementId: this.settings.referenceElementId\n            ? this.elementEditor?.getDraftElementId(\n                this.settings.referenceElementId\n              ) || this.settings.referenceElementId\n            : null,\n          referenceElementOwnerId: this.settings.referenceElementOwnerId\n            ? this.elementEditor?.getDraftElementId(\n                this.settings.referenceElementOwnerId\n              ) || this.settings.referenceElementOwnerId\n            : null,\n          referenceElementSiteId: this.settings.referenceElementSiteId,\n          criteria: Object.assign({}, this.settings.criteria),\n          multiSelect: this.settings.limit != 1,\n          hideOnSelect: false,\n          showSiteMenu: this.settings.showSiteMenu,\n          disabledElementIds: this.getDisabledElementIds(),\n          onSelect: this.onModalSelect.bind(this),\n          onHide: this.onModalHide.bind(this),\n          triggerElement: () => this.getNextLogicalFocusElement(),\n          modalTitle: Craft.t('app', 'Choose'),\n        },\n        this.settings.modalSettings\n      );\n\n      // make sure the previously-selected source is retained each time the\n      // modal is re-opened\n      if (!this.modalFirstOpen) {\n        settings.preferStoredSource = true;\n      }\n\n      return settings;\n    },\n\n    getSelectedElementIds: function () {\n      const ids = [];\n\n      for (let i = 0; i < this.$elements.length; i++) {\n        if (\n          this.settings.modalSettings.matchSiteBeforeDisablingElement &&\n          this.settings.modalSettings.siteId\n        ) {\n          if (\n            this.$elements.eq(i).data('siteId') ==\n            this.settings.modalSettings.siteId\n          ) {\n            ids.push(this.$elements.eq(i).data('id'));\n          }\n        } else {\n          ids.push(this.$elements.eq(i).data('id'));\n        }\n      }\n\n      return ids;\n    },\n\n    getDisabledElementIds: function () {\n      var ids = this.getSelectedElementIds();\n\n      if (!this.settings.allowSelfRelations && this.settings.sourceElementId) {\n        ids.push(this.settings.sourceElementId);\n      }\n\n      if (this.settings.disabledElementIds) {\n        ids.push(...this.settings.disabledElementIds);\n      }\n\n      return ids;\n    },\n\n    onModalSelect: async function (elements) {\n      // Disable the modal\n      this.modal?.disable();\n      this.modal?.disableCancelBtn();\n      this.modal?.disableSelectBtn();\n      this.modal?.showFooterSpinner();\n\n      // Pause the element editor so we aren’t causing multiple draft saves\n      this.elementEditor?.pause();\n\n      if (this._$replaceElement) {\n        this.removeElement(this._$replaceElement);\n        this._$replaceElement = null;\n      }\n\n      // re-render the elements even if the view modes match, to be sure we have all the correct settings\n      const [inputUiType, inputUiSize] = (() => {\n        switch (this.settings.viewMode) {\n          case 'thumbs':\n          case 'large':\n            return ['chip', 'large'];\n          case 'cards':\n          case 'cards-grid':\n            return ['card', null];\n          default:\n            return ['chip', 'small'];\n        }\n      })();\n      const {data} = await Craft.sendActionRequest(\n        'POST',\n        'app/render-elements',\n        {\n          data: {\n            elements: [\n              {\n                type: this.settings.elementType,\n                id: elements.map((e) => e.id),\n                siteId: elements[0].siteId,\n                instances: [\n                  {\n                    context: 'field',\n                    ui: inputUiType,\n                    size: inputUiSize,\n                    showActionMenu: this.settings.showActionMenu,\n                  },\n                ],\n              },\n            ],\n          },\n        }\n      );\n\n      for (let i = 0; i < elements.length; i++) {\n        if (typeof data.elements[elements[i].id] !== 'undefined') {\n          elements[i].$modalElement = elements[i].$element;\n          elements[i].$element = $(data.elements[elements[i].id][0]);\n        }\n      }\n\n      if (this.settings.maintainHierarchy) {\n        await this.selectStructuredElements(elements);\n      } else {\n        if (this.settings.limit) {\n          // Cut off any excess elements\n          var slotsLeft = this.settings.limit - this.$elements.length;\n\n          if (elements.length > slotsLeft) {\n            elements = elements.slice(0, slotsLeft);\n          }\n        }\n\n        await this.selectElements(elements);\n        this.updateDisabledElementsInModal();\n      }\n\n      // Re-enable and hide the modal\n      this.modal?.enable();\n      this.modal?.enableCancelBtn();\n      this.modal?.enableSelectBtn();\n      this.modal?.hideFooterSpinner();\n      this.modal?.hide();\n\n      await Craft.appendHeadHtml(data.headHtml);\n      await Craft.appendBodyHtml(data.bodyHtml);\n\n      this.elementEditor?.resume();\n    },\n\n    onModalHide: function () {\n      // If the modal has a condition and a reference element, recreate it each time it’s opened\n      // in case something about the edited element is going to affect the condition\n      if (\n        this.modal &&\n        this.settings.condition &&\n        this.settings.referenceElementId\n      ) {\n        this.modal.destroy();\n        this.modal = null;\n      }\n\n      this._$replaceElement = null;\n    },\n\n    selectElements: async function (elements) {\n      const animateElements = [];\n\n      for (let i = 0; i < elements.length; i++) {\n        const elementInfo = elements[i];\n        const $inputElement = this.createNewElement(elementInfo);\n\n        this.appendElement($inputElement);\n        this.addElements($inputElement);\n\n        // Override the element reference with the new one\n        elementInfo.$element = $inputElement;\n\n        const $modalElement = elementInfo.$modalElement || elementInfo.$element;\n\n        if ($modalElement && $modalElement.parent().length) {\n          animateElements.push({$modalElement, $inputElement});\n        }\n      }\n\n      this.animateElementsIntoPlace(animateElements);\n      this.onSelectElements(elements);\n    },\n\n    selectStructuredElements: async function (elements) {\n      // when branchLimit is 1, a new selection needs to replace the existing one;\n      // in that case, don't include old IDs, so Structures::applyBranchLimitToElements() keeps the new element;\n      // (it's called from relational-fields/structured-input-html)\n      var selectedElementIds = this.settings.branchLimit == 1 ? [] : this.getSelectedElementIds();\n\n      for (var i = 0; i < elements.length; i++) {\n        selectedElementIds.push(elements[i].id);\n      }\n\n      var data = {\n        elementIds: selectedElementIds,\n        siteId: elements[0].siteId,\n        containerId: this.settings.id,\n        name: this.settings.name,\n        branchLimit: this.settings.branchLimit,\n        selectionLabel: this.settings.selectionLabel,\n        elementType: this.settings.elementType,\n      };\n\n      const response = await Craft.sendActionRequest(\n        'POST',\n        'relational-fields/structured-input-html',\n        {data}\n      );\n\n      const $newInput = $(response.data.html),\n        $newElementsContainer = $newInput.children('.elements');\n\n      this.$elementsContainer.replaceWith($newElementsContainer);\n      this.$elementsContainer = $newElementsContainer;\n\n      await Craft.appendHeadHtml(response.data.headHtml);\n      await Craft.appendBodyHtml(response.data.bodyHtml);\n\n      this.resetElements();\n\n      const filteredElements = [];\n      const animateElements = [];\n\n      for (let i = 0; i < elements.length; i++) {\n        const element = elements[i];\n        const $inputElement = this.getElementById(element.id);\n\n        if ($inputElement) {\n          filteredElements.push(element);\n          animateElements.push({\n            $modalElement: element.$element,\n            $inputElement,\n          });\n        }\n      }\n\n      this.animateElementsIntoPlace(animateElements);\n      this.updateDisabledElementsInModal();\n      this.onSelectElements(filteredElements);\n    },\n\n    createNewElement: function (elementInfo) {\n      var $element = elementInfo.$element.clone();\n      var removeText = Craft.t('app', 'Remove {label}', {\n        label: Craft.escapeHtml(elementInfo.label),\n      });\n      // Make a couple t