rkup and start loading components and the image.\n     *\n     * @param {Object} data\n     */\n    loadEditor: function (data) {\n      if (!data.html) {\n        Craft.cp.displayError(\n          Craft.t('app', 'Could not load the image editor.')\n        );\n      }\n\n      this.$body.html(data.html);\n      this.$tabs = $('.tabs li', this.$body);\n      this.$viewsContainer = $('.views', this.$body);\n      this.$views = $('> div', this.$viewsContainer);\n      this.$imageTools = $('.image-container .image-tools', this.$body);\n      this.$editorContainer = $('.image-container .image', this.$body);\n      this.$constraintContainer = $('.constraint-group', this.$body);\n      this.$constraintRadioInputs = $(\n        '[name=\"constraint\"]',\n        this.$constraintContainer\n      );\n      this.$orientationField = $('#orientation', this.$body);\n      this.$focalPointBtn = $('.focal-point', this.$body);\n      this.editorHeight = this.$editorContainer.innerHeight();\n      this.editorWidth = this.$editorContainer.innerWidth();\n\n      // Keyboard accessibility\n      this.$fabricElementEditBtn = $('[data-fabric-element]', this.$body);\n\n      // Get SVG to use for move/active indicator\n      const $moveSvg = $('#move-icon-wrapper svg').prop('outerHTML');\n\n      // Store move icon for later use\n      fabric.loadSVGFromString($moveSvg, (objects, options) => {\n        var obj = fabric.util.groupSVGElements(objects, options);\n        obj.set({\n          left: 0,\n          top: 0,\n          scaleX: 0.03,\n          scaleY: 0.03,\n          originX: 'center',\n          originY: 'center',\n          fill: 'white',\n        });\n\n        this.moveIcon = obj;\n      });\n\n      this._showSpinner();\n\n      this.updateSizeAndPosition();\n\n      $customConstraintWrapper = this.$constraintRadioInputs\n        .filter('[value=\"custom\"]')\n        .parent();\n\n      $customConstraintGroupLabel = $customConstraintWrapper.find('label');\n\n      // Add cus