Reposition the image relatively to the previous editor dimensions.\n      this._repositionImage(previousEditorDimensions);\n      this._repositionViewport();\n      this._repositionFocalPoint(previousEditorDimensions);\n      this._zoomImage();\n\n      this.renderImage();\n\n      if (\n        currentScaledDimensions.width / this.lastLoadedDimensions.width > 1.5 ||\n        currentScaledDimensions.height / this.lastLoadedDimensions.height > 1.5\n      ) {\n        this._reloadImage();\n      }\n    },\n\n    /**\n     * Reposition image based on how the editor dimensions have changed.\n     * This ensures keeping the image center offset, if there is any.\n     *\n     * @param {Object} previousEditorDimensions\n     */\n    _repositionImage: function (previousEditorDimensions) {\n      this.image.set({\n        left:\n          this.image.left -\n          (previousEditorDimensions.width - this.editorWidth) / 2,\n        top:\n          this.image.top -\n          (previousEditorDimensions.height - this.editorHeight) / 2,\n      });\n    },\n\n    /**\n     * Create the viewport for image editor.\n     */\n    _createViewport: function () {\n      this.viewport = new fabric.Rect({\n        width: this.image.width,\n        height: this.image.height,\n        fill: 'rgba(127,0,0,1)',\n        originX: 'center',\n        originY: 'center',\n        globalCompositeOperation: 'destination-in', // This clips everything outside of the viewport\n        left: this.image.left,\n        top: this.image.top,\n      });\n      this.canvas.add(this.viewport);\n      this.renderImage();\n    },\n\n    /**\n     * Create the focal point.\n     */\n    _createFocalPoint: function () {\n      var focalPointState = this.focalPointState;\n      var sizeFactor =\n        this.getScaledImageDimensions().width /\n        focalPointState.imageDimensions.width;\n\n      var focalX =\n        focalPointState.offsetX *\n        sizeFactor *\n        this.zoomRatio *\n        this.scaleFactor;\n      var focalY =\n        focalPointState.offsetY *\n        sizeFactor *\n        this.zoomRatio *\n        this.scaleFactor;\n\n      // Adjust by image margins\n      focalX += this.image.left;\n      focalY += this.image.top;\n\n      var deltaX = 0;\n      var deltaY = 0;\n\n      // When creating a fresh focal point, drop it dead in the center of the viewport, not the image.\n      if (\n        this.viewport &&\n        focalPointState.offsetX === 0 &&\n        focalPointState.offsetY === 0\n      ) {\n        if (this.currentView !== 'crop') {\n          deltaX = this.viewport.left - this.image.left;\n          deltaY = this.viewport.top - this.image.top;\n        } else {\n          // Unless we have a cropper showing, in which case drop it in the middle of the cropper\n          deltaX = this.clipper.left - this.image.left;\n          deltaY = this.clipper.top - this.image.top;\n        }\n\n        // Bump focal to middle of viewport\n        focalX += deltaX;\n        focalY += deltaY;\n\n        // Reflect changes in saved state\n        focalPointState.offsetX +=\n          deltaX / (sizeFactor * this.zoomRatio * this.scaleFactor);\n        focalPointState.offsetY +=\n          deltaY / (sizeFactor * this.zoomRatio * this.scaleFactor);\n      }\n\n      this.focalPointOuterCircle = new fabric.Circle({\n        radius: 8,\n        fill: 'rgba(0,0,0,0.5)',\n        strokeWidth: 2,\n        stroke: 'rgba(255,255,255,0.8)',\n        left: 0,\n        top: 0,\n        originX: 'center',\n        originY: 'center',\n      });\n\n      this.focalPointInnerCircle = new fabric.Circle({\n        radius: 1,\n        fill: 'rgba(255,255,255,0)',\n        strokeWidth: 2,\n        stroke: 'rgba(255,255,255,0.8)',\n        left: 0,\n        top: 0,\n        originX: 'center',\n        originY: 'center',\n      });\n\n      this.focalPointPickedIndicator = new fabric.Circle({\n        radius: 12,\n        strokeWidth: 0,\n        stroke: 'rgba(255,255,255,0.8)',\n        left: 0,\n        top: 0,\n        originX: 'center',\n        originY: 'center',\n      });\n\n      this.focalPoint = new fabric.Group(\n        [\n          this.focalPointPickedIndicator,\n          this.focalPointOuterCircle,\n          this.focalPointInnerCircle,\n        ],\n        {\n          originX: 'center',\n          originY: 'center',\n          left: focalX,\n          top: focalY,\n        }\n      );\n\n      this.storeFocalPointState(focalPointState);\n      this.canvas.add(this.focalPoint);\n    },\n\n    /**\n     * Toggle focal point\n     */\n    toggleFocalPoint: function () {\n      if (!this.focalPoint) {\n        this._createFocalPoint();\n        this.prevFocalPoint = null;\n      } else {\n        this.prevFocalPoint = this.focalPoint;\n        this.canvas.remove(this.focalPoint);\n        this.focalPoint = null;\n      }\n\n      this.renderImage();\n    },\n\n    /**\n     * Reposition the viewport to handle editor resizing.\n     */\n    _repositionViewport: function () {\n      if (this.viewport) {\n        var dimensions = {\n          left: this.editorWidth / 2,\n          top: this.editorHeight / 2,\n        };\n\n        // If we're cropping, nothing exciting happens for the viewport\n        if (this.currentView === 'crop') {\n          dimensions.width = this.editorWidth;\n          dimensions.height = this.editorHeight;\n        } else {\n          // If this is the first initial reposition, no cropper state yet\n          if (this.cropperState) {\n            // Recall the state\n            var state = this.cropperState;\n\n            var scaledImageDimensions = this.getScaledImageDimensions();\n            // Make sure we have the correct current image size\n            var sizeFactor =\n              scaledImageDimensions.width / state.imageDimensions.width;\n\n            // Set the viewport dimensions\n            dimensions.width = state.width * sizeFactor * this.zoomRatio;\n            dimensions.height = state.height * sizeFactor * this.zoomRatio;\n\n            // Adjust the image position to show the correct part of the image in the viewport\n            this.image.set({\n              left: this.editorWidth / 2 - state.offsetX * sizeFactor,\n              top: this.editorHeight / 2 - state.offsetY * sizeFactor,\n            });\n          } else {\n            $.extend(dimensions, this.getScaledImageDimensions());\n          }\n        }\n        this.viewport.set(dimensions);\n      }\n    },\n\n    _repositionFocalPoint: function (previousEditorDimensions) {\n      if (this.focalPoint) {\n        var offsetX = this.focalPoint.left - this.editorWidth / 2;\n        var offsetY = this.focalPoint.top - this.editorHeight / 2;\n\n        var currentWidth = this.image.width;\n        var newWidth = this.getScaledImageDimensions().width * this.zoomRatio;\n        var ratio = newWidth / currentWidth / this.scaleFactor;\n\n        offsetX -= (previousEditorDimensions.width - this.editorWidth) / 2;\n        offsetY -= (previousEditorDimensions.height - this.editorHeight) / 2;\n\n        offsetX *= ratio;\n        offsetY *= ratio;\n\n        this.focalPoint.set({\n          left: this.editorWidth / 2 + offsetX,\n          top: this.editorHeight / 2 + offsetY,\n        });\n      }\n    },\n\n    /**\n     * Return true if the image orientation has changed\n     */\n    hasOrientationChanged: function () {\n      return this.viewportRotation % 180 !== 0;\n    },\n\n    /**\n     * Return the current image dimensions that would be used in the current image area with no straightening or rotation applied.\n     */\n    getScaledImageDimensions: function () {\n      if (typeof this.getScaledImageDimensions._ === 'undefined') {\n        this.getScaledImageDimensions._ = {};\n      }\n\n      this.getScaledImageDimensions._.imageRatio =\n        this.originalHeight / this.originalWidth;\n      this.getScaledImageDimensions._.editorRatio =\n        this.editorHeight / this.editorWidth;\n\n      this.getScaledImageDimensions._.dimensions = {};\n      if (\n        this.getScaledImageDimensions._.imageRatio >\n        this.getScaledImageDimensions._.editorRatio\n      ) {\n        this.getScaledImageDimensions._.dimensions.height = Math.min(\n          this.editorHeight,\n          this.originalHeight\n        );\n        this.getScaledImageDimensions._.dimensions.width = Math.round(\n          this.originalWidth /\n            (this.originalHeight /\n              this.getScaledImageDimensions._.dimensions.height)\n        );\n      } else {\n        this.getScaledImageDimensions._.dimensions.width = Math.min(\n          this.editorWidth,\n          this.originalWidth\n        );\n        this.getScaledImageDimensions._.dimensions.height = Math.round(\n          this.originalHeight *\n            (this.getScaledImageDimensions._.dimensions.width /\n              this.originalWidth)\n        );\n      }\n\n      return this.getScaledImageDimensions._.dimensions;\n    },\n\n    /**\n     * Set the image dimensions to reflect the current zoom ratio.\n     */\n    _zoomImage: function () {\n      if (typeof this._zoomImage._ === 'undefined') {\n        this._zoomImage._ = {};\n      }\n\n      this._zoomImage._.imageDimensions = this.getScaledImageDimensions();\n      this.image.set({\n        width: this._zoomImage._.imageDimensions.width * this.zoomRatio,\n        height: this._zoomImage._.imageDimensions.height * this.zoomRatio,\n      });\n    },\n\n    /**\n     * Gets previous tab element from currently-active.\n     */\n    _getPrevTab: function () {\n      const activeTabIndex = this._getActiveTabIndex();\n\n      if (activeTabIndex < 0) return;\n\n      let newTabIndex;\n\n      if (activeTabIndex > 0) {\n        newTabIndex = activeTabIndex - 1;\n      } else {\n        newTabIndex = this.$tabs.length - 1;\n      }\n\n      return this.$tabs.eq(newTabIndex);\n    },\n\n    /**\n     * Gets next tab element from currently-active.\n     */\n    _getNextTab: function () {\n      const activeTabIndex = this._getActiveTabIndex();\n\n      if (activeTabIndex < 0) return;\n\n      let newTabIndex;\n\n      if (activeTabIndex < this.$tabs.length - 1) {\n        newTabIndex = activeTabIndex + 1;\n      } else {\n        newTabIndex = 0;\n      }\n\n      return this.$tabs.eq(newTabIndex);\n    },\n\n    /**\n     * Gets active tab element\n     */\n    _getActiveTab: function () {\n      return this.$tabs.filter('[aria-selected=\"true\"]');\n    },\n\n    /**\n     * Gets index of active tab among sibling tabs\n     */\n    _getActiveTabIndex: function () {\n      const $activeTab = this._getActiveTab();\n\n      if (!$activeTab.length) return;\n\n      return $activeTab.index();\n    },\n\n    /**\n     * Set up listeners for the controls.\n     */\n    _addControlListeners: function () {\n      // Tabs\n      this.addListener(this.$tabs, 'click', this._handleTabClick);\n      this.addListener(this.$tabs, 'keydown', (event) => {\n        switch (event.keyCode) {\n          case Garnish.LEFT_KEY:\n          case Garnish.UP_KEY:\n            event.preventDefault();\n            const $prevTab = this._getPrevTab();\n            this.activateTab($prevTab);\n            break;\n          case Garnish.RIGHT_KEY:\n          case Garnish.DOWN_KEY:\n            event.preventDefault();\n            const $nextTab = this._getNextTab();\n            this.activateTab($nextTab);\n            break;\n        }\n      });\n\n      // Rotate controls\n      this.addListener($('.rotate-left'), 'click', function () {\n        this.rotateImage(-90);\n      });\n      this.addListener($('.rotate-right'), 'click', function () {\n        this.rotateImage(90);\n      });\n      this.addListener($('.flip-vertical'), 'click', function () {\n        this.flipImage('y');\n      });\n      this.addListener($('.flip-horizontal'), 'click', function () {\n        this.flipImage('x');\n      });\n\n      // FabricJS canvas\n      this.addListener(this.$fabricElementEditBtn, 'click', (ev) => {\n        this._handleEditButtonClick(ev);\n      });\n      this.addListener(this.$fabricElementEditBtn, 'keydown', (ev) => {\n        this.dragEditMode = false;\n        this._handleKeydownOnFabricElementEditBtn(ev);\n      });\n\n      this.addListener(Garnish.$doc, 'focusin', (ev) => {\n        const targetIsEditButton = $(ev.target).is(this.$fabricElementEditBtn);\n\n        const showingEditorFocusOutlines =\n          this.handleFocusIndicator || this.rectangleHasFocusOutline;\n        const outlinesShouldBeErased =\n          showingEditorFocusOutlines && !targetIsEditButton;\n\n        if (targetIsEditButton || outlinesShouldBeErased) {\n          if (targetIsEditButton) {\n            this.focusedEditButton = $(ev.target);\n          } else {\n            this.focusedEditButton = null;\n          }\n\n          this._resetEditState();\n\n          if (this.clipper) {\n            this._redrawCropperElements();\n            this.renderCropper();\n          }\n        }\n      });\n\n      // Straighten slider\n      this.straighteningInput = new Craft.SlideRuleInput('slide-rule', {\n        onStart: () => {\n          this._showGrid();\n        },\n        onChange: (slider) => {\n          this.straighten(slider);\n        },\n        onEnd: () => {\n          this._hideGrid();\n          this._cleanupFocalPointAfterStraighten();\n        },\n      });\n\n      // Cropper scale modifier key\n      this.addListener(Garnish.$doc, 'keydown', function (ev) {\n        if (ev.keyCode === Garnish.SHIFT_KEY) {\n          this.shiftKeyHeld = true;\n        }\n      });\n      this.addListener(Garnish.$doc, 'keyup', function (ev) {\n        if (ev.keyCode === Garnish.SHIFT_KEY) {\n          this.shiftKeyHeld = false;\n        }\n      });\n\n      this.addListener(\n        this.$constraintRadioInputs,\n        'change',\n        this._handleConstraintChange\n      );\n      this.orientationBtnGroup = new Craft.Listbox(this.$orientationField, {\n        onChange: ($option) => {\n          this._handleOrientationClick($option);\n        },\n      });\n      this.addListener(\n        $('.constraint-group .custom input', this.$container),\n        'keyup',\n        this._applyCustomConstraint\n      );\n    },\n\n    /**\n     * Handle a constraint button click.\n     *\n     * @param {Object} ev\n     */\n    _handleConstraintClick: function (ev) {\n      var constraint = $(ev.currentTarget).data('constraint');\n      var $target = $(ev.currentTarget);\n      $target.siblings().removeClass('active');\n      $target.addClass('active');\n\n      if (constraint == 'custom') {\n        this._showCustomConstraint();\n        this._applyCustomConstraint();\n        return;\n      }\n\n      this._hideCustomConstraint();\n\n      this.setCroppingConstraint(constraint);\n      this.enforceCroppingConstraint();\n    },\n\n    /**\n     * Handle a constraint change.\n     *\n     * @param {Object} ev\n     */\n    _handleConstraintChange: function (ev) {\n      const constraint = $(ev.target).val();\n\n      if (constraint == 'custom') {\n        this._showCustomConstraint();\n        this._applyCustomConstraint();\n        return;\n      }\n\n      this._hideCustomConstraint();\n\n      this.setCroppingConstraint(constraint);\n      this.enforceCroppingConstraint();\n    },\n\n    /**\n     * Handle an orientation switch click.\n     *\n     * @param {Object} ev\n     */\n    _handleOrientationClick: function ($option) {\n      if ($option.data('value') === this.constraintOrientation) {\n        return;\n      }\n      this.constraintOrientation = $option.data('value');\n\n      const $constraints = $('.flip', this.$constraintContainer);\n\n      for (var i = 0; i < $constraints.length; i++) {\n        var $constraint = $($constraints[i]);\n        const labelSelector = 'label[for=\"' + $constraint.attr('id') + '\"]';\n        const $label = $(labelSelector, this.$constraintConta